const KB_10 = `[درس 1-1] سؤال: صح أم خطأ: الشحنات المتشابهة (موجبة مع موجبة، أو سالبة مع سالبة) تتجاذب. | الإجابة الصحيحة: خطأ

[درس 1-1] سؤال: عند تقريب جسم موجب الشحنة من جسم سالب الشحنة، ماذا يحدث؟ | الإجابة الصحيحة: تتجاذب الشحنتان

[درس 1-1] سؤال: صح أم خطأ: كل جسم إما مشحون بشحنة موجبة أو سالبة، ولا يوجد جسم متعادل الشحنة. | الإجابة الصحيحة: خطأ

[درس 1-1] سؤال: عندما يصبح الجسم موجب الشحنة، ماذا يكون قد حدث له؟ | الإجابة الصحيحة: فقد إلكترونات

[درس 1-1] سؤال: صح أم خطأ: تنشأ الكهرباء الساكنة عادة نتيجة انتقال الإلكترونات بين جسمين عند تلامسهما أو دلكهما ببعض. | الإجابة الصحيحة: صح

[درس 1-1] سؤال: أي المواد التالية عازلة تحتفظ بالشحنة الساكنة عليها بسهولة؟ | الإجابة الصحيحة: البلاستيك

[درس 3-1] قانون كولوم والمجال الكهربائي:
يصف قانون كولوم القوة المتبادلة بين شحنتين نقطيتين، حيث تتناسب هذه القوة طردياً مع حاصل ضرب الشحنتين وعكسياً مع مربع المسافة بينهما.

المجال الكهربائي عند نقطة معينة هو القوة التي تؤثر بها الشحنة على وحدة شحنة موجبة موضوعة عند تلك النقطة.

[درس 1-1] سؤال اختباري: عند تقريب كرتين فلزيتين (X) و(Y) مشحونتين بشحنة سالبة من بعضهما (محمولتين على عازل)
الإجابة الرسمية: الكرتان تتنافران لأن شحنتيهما متشابهتان (سالبة-سالبة)؛ توزيع الشحنات يبتعد كل عن الآخر قدر الإمكان على كل كرة.

[درس 1-1] سؤال اختباري: لماذا تنجذب كرة فلزية موجبة الشحنة نحو قضيب مشحون بشحنة سالبة عند تقريبه منها؟
الإجابة الرسمية: بسبب قوة التجاذب الكهربائي بين الشحنات الموجبة الموجودة على الكرة والشحنة السالبة الموجودة على القضيب القريب منها.

[درس 1-1] سؤال اختباري: بالونان (Q) و(R) معلّقان ومشحونان، وأحدهما ينجذب نحو الآخر بوضوح. حدد نوع الشحنة على كل من البالونين (Q) و(R).
الإجابة الرسمية: البالون (Q): شحنة موجبة (+). البالون (R): شحنة سالبة (−).

[درس 1-1] سؤال اختباري: كرة فلزية مشحونة موضوعة على قاعدة عازلة. ماذا يحدث عند تقريب ساق أبونايت موجب الشحنة من الكرة؟ ولماذا؟
الإجابة الرسمية: تجاذب؛ لأن الكرة والساق لهما شحنتان مختلفتا النوع (إحداهما موجبة والأخرى سالبة)، والشحنات المختلفة تتجاذب.

[درس 1-1] سؤال اختباري: أكمل المصطلح العلمي: أ) الكهرباء الناتجة عن تراكم الشحنات الكهربائية على أسطح المواد. ب) الجسم الذي يحتوي على عدد متساوٍ من الشحنات الموجبة والسالبة.
الإجابة الرسمية: أ) الكهرباء الساكنة. ب) جسم متعادل (متعادل كهربائياً).

[درس 1-1] سؤال اختباري: تُقرَّب ساق مشحونة بشحنة موجبة من كرة فلزية معزولة وغير مشحونة. ما نوع الشحنة التي تظهر على جانبي الكرة (X) القريب و(Y) البعيد؟
الإجابة الرسمية: الجانب (X) القريب من الساق: شحنة سالبة (بالحث). الجانب (Y) البعيد: شحنة موجبة.

[درس 1-1] سؤال اختباري: قضيب مشحون تم تقريبه من كرة فلزية معلّقة بواسطة خيط عازل، فانجذبت الكرة نحو القضيب. أ) ما نوع شحنة القضيب؟ ب) ما نوع القوة التي نشأت بين القضيب والكرة؟ ج) حدد على الشكل نوع الشحنة على سطح الكرة. د) إذا استُبدل الخيط العازل بخيط موصل للكهرباء، ماذا سيحدث للكرة؟
الإجابة الرسمية: أ) موجبة (بحسب اتجاه الانجذاب والشحنة الموضحة في الشكل). ب) قوة تجاذب. ج) يتوزع الجانب القريب من القضيب بشحنة سالبة (بالحث)، والجانب البعيد بشحنة موجبة. د) تفقد الكرة شحنتها (تتسرب الشحنة عبر الخيط الموصل إلى الأرض ولا يبقى انجذاب).

[درس 1-1] سؤال اختباري: كرتان معدنيتان متلامستان غير مشحونتين على قاعدتين عازلتين. عند تقريب قضيب مشحون من الكرة (Y)، ما نوع شحنة الكرة (X) البعيدة؟
الإجابة الرسمية: نفس نوع شحنة القضيب المقرَّب (بالحث: الشحنات المتشابهة تتنافر مبتعدة نحو الطرف البعيد X، بينما يتجمع النوع المعاكس عند الطرف القريب Y).

[درس 1-10] سؤال اختباري: ما اسم وحدة قياس النشاط الإشعاعي في النظام الدولي؟
الإجابة الرسمية: البيكريل (Bq).

[درس 1-10] سؤال اختباري: ما المصطلح العلمي الذي يدل على العبارة الآتية: "انحلال أنوية المواد المشعة غير المستقرة بإطلاق جسيمات أو إشعاعات لتصبح نواة مستقرة"؟
الإجابة الرسمية: الاضمحلال الإشعاعي.

[درس 1-11] سؤال اختباري: هل يُعتبر تخزين مادة مشعة في صندوق خشبي عادي إجراءً آمناً؟ ولماذا؟
الإجابة الرسمية: لا؛ لأن الأشعة قد تتسرب من الصندوق الخشبي مسبّبةً تلوثاً إشعاعياً للبيئة المحيطة.

[درس 1-11] سؤال اختباري: اذكر إجراءً واحداً من إجراءات السلامة عند التخلص من النفايات المشعة.
الإجابة الرسمية: استخدام حاوية تمتص الإشعاع ولا تتآكل أو تسمح بتسرب الإشعاع منها، وحفظها في مكان آمن بعيد عن المنشآت الحيوية مع وضع ملصق تحذير عليها.

[درس 1-11] سؤال اختباري: ما المادة الشائع استخدامها لتغليف أو حجب الحاويات المحتوية على مواد مشعة نظراً لقدرتها العالية على امتصاص الإشعاع؟
الإجابة الرسمية: الرصاص.

[درس 1-11] سؤال اختباري: صندوق مجوّف مبطّن بمادة الرصاص استُخدم لتخزين مادة مشعة، ووُضعت عليه علامة تحذيرية. أ) أي الإشارات المناسبة لوضعها على الخزانة؟ ب) لماذا استُخدم الرصاص تحديداً في تبطين الصندوق؟
الإجابة الرسمية: أ) إشارة الخطر الإشعاعي (رمز الإشعاع المثلثي) وليس إشارة الجمجمة (السموم). ب) لأن الرصاص مادة شديدة الامتصاص للإشعاعات (ألفا وبيتا وجاما)، مما يقلل من تسرّب الإشعاع إلى البيئة المحيطة.

[درس 1-11] سؤال اختباري: هل يمكن رمي العيّنة المشعة في حاويات القمامة العادية؟ فسّر إجابتك.
الإجابة الرسمية: لا؛ لأن ذلك يسبب تلوثاً إشعاعياً للبيئة المحيطة وقد يعرّض من يتعامل مع القمامة لمخاطر إشعاعية.

[درس 1-11] سؤال اختباري: تُخزَّن المواد المشعة في حاويات مبطنة بمعدن لتقليل كمية الإشعاع المنبعث لحماية الأشخاص القريبين. ما نوع المعدن المستخدم لهذا الغرض؟
الإجابة الرسمية: الرصاص.

[درس 1-11] سؤال اختباري: عنصر مشع يُستخدم لفحص الكلى بإعطائه للمريض على هيئة قرص دواء، ثم يُرصد شعاع جاما بالكاشف. أ) اذكر أحد إجراءات السلامة التي يجب أن يتبعها الطبيب عند استخدام العنصر المشع لفحص المريض. ب) فسّر لماذا يُستخدم في الفحص مصدر يشع أشعة جاما بدلاً من مصدر يشع أشعة ألفا.
الإجابة الرسمية: أ) إبقاء العنصر المشع بعيداً عن الجسم قدر الإمكان، أو وضع حاجز فلزي بين العنصر المشع والمريض، أو استخدام ملاقط عند التعامل مع العنصر المشع (يُقبل أي إجراء سلامة صحيح). ب) لأن أشعة ألفا تمتصها الطبقة الخارجية من خلايا الجلد ولا تخرج من الجسم لتصل للكاشف الخارجي، بينما أشعة جاما قادرة على اختراق أنسجة الجسم والخروج منه لتُرصد بالكاشف من الخارج.

[درس 1-2] سؤال اختباري: أكمل الجدول بكتابة نوع المقاومة أسفل الرمز الدال عليها في الدائرة الكهربائية (مقاومة متغيّرة، ومقاومة ضوئية LDR).
الإجابة الرسمية: الرمز الأول: مقاومة متغيّرة (Variable Resistor / Rheostat). الرمز الثاني: مقاومة ضوئية (Light Dependent Resistor - LDR).

[درس 1-3] سؤال اختباري: متى يتعرض الشخص لخطر الصدمة الكهربائية؟
الإجابة الرسمية: عند لمس السلك الكهربائي المكشوف مباشرة.

[درس 1-4] سؤال اختباري: شخص يدفع صندوقاً، والشكل يوضح اتجاهات القوى المؤثرة عليه أثناء دفعه (أربعة أسهم بالرموز A، B، C، D). ما رمز السهم الذي يمثل اتجاه قوة الاحتكاك؟
الإجابة الرسمية: A (تعمل قوة الاحتكاك بعكس اتجاه حركة الصندوق، أي بعكس اتجاه قوة الدفع).

[درس 1-4] سؤال اختباري: اكتب قوتين تسبّبان تغيرات في حجم الجسم الصلب وشكله.
الإجابة الرسمية: قوى الضغط (الانضغاط)، وقوى الشد؛ (ويُقبل أيضاً: قوى اللي، وقوى الثني).

[درس 1-4] سؤال اختباري: أي من خصائص الجسم الآتية يمكن تغييرها بواسطة القوة المحصّلة عليه؟ (السرعة والشكل والكتلة / الحجم والشكل والكتلة / السرعة والكتلة واتجاه الحركة / الحجم والشكل واتجاه الحركة)
الإجابة الرسمية: السرعة والكتلة واتجاه الحركة (القوة المحصّلة تغيّر من حركة الجسم: سرعته واتجاهه، ولا تغيّر كتلته الجوهرية ولا حجمه أو شكله بحد ذاتها في هذا السياق — والإجابة الصحيحة وفق النموذج الرسمي هي هذا الخيار).

[درس 1-5] سؤال اختباري: ما المقصود بعزم القوة؟
الإجابة الرسمية: هو مقياس تأثير الدوران الذي تحدثه قوة حول نقطة (محور) دوران معينة.

[درس 1-5] سؤال اختباري: عرّف عزم القوة.
الإجابة الرسمية: عزم القوة: تأثير الدوران الذي تُحدثه قوة حول نقطة (محور) دوران معينة.

[درس 1-6] سؤال اختباري: ما المقصود بالشغل المبذول؟
الإجابة الرسمية: هو مقدار الطاقة المنقولة عندما يؤثر جسم بقوة على جسم آخر فيحركه مسافة معينة باتجاه هذه القوة.

[درس 1-6] سؤال اختباري: شخص يسحب جسماً بقوة 400 نيوتن مسافة 5 أمتار، ويبذل شغلاً مقداره 500 جول للتغلب على الاحتكاك. احسب الشغل الكلي المبذول والشغل المبذول ضد الجاذبية.
الإجابة الرسمية: الشغل الكلي المبذول بواسطة الشخص = القوة × المسافة = 400 × 5 = 2000 جول. الشغل المبذول ضد الجاذبية = الشغل الكلي − الشغل ضد الاحتكاك = 2000 − 500 = 1500 جول.

[درس 1-7] سؤال اختباري: ما المقصود بالضغط؟
الإجابة الرسمية: هو مقدار القوة العمودية المؤثرة على وحدة المساحة.

[درس 1-7] سؤال اختباري: قرص دائري نصف قطره 0.01م يؤثر بضغط مقداره 100000 باسكال على سطح. احسب مساحة القرص والقوة المؤثرة.
الإجابة الرسمية: مساحة القرص A = نق² × 4 (تقريب الشكل في السؤال) = 0.01×4 = 0.04 م². القوة F = الضغط × المساحة = 100000 × 0.04 = 4000 نيوتن.

[درس 1-7] سؤال اختباري: متزلج وزنه (550N) يقف ساكناً على مساحة مسطحة من الثلج، والمساحة الكلية لزلاجته الملامسة للأرض (0.015 m²). احسب الضغط الذي يؤثر به على الأرض. وما المقصود بالضغط؟
الإجابة الرسمية: الضغط = القوة ÷ المساحة = 550 ÷ 0.015 = 36666.7 باسكال تقريباً (Pa). الضغط: القوة العمودية المؤثرة على وحدة المساحة.

[درس 1-7] سؤال اختباري: جسمان (A) عجلة و(B) إصبع يضغط على مسمار، يبذلان نفس القوة على نفس السطح. أي الجسمين يبذل ضغطاً أكبر على السطح؟ فسّر إجابتك.
الإجابة الرسمية: الجسم (B) (طرف المسمار الحاد الذي يضغطه الإصبع)؛ لأن مساحة تلامسه بالسطح أصغر بكثير من مساحة تلامس العجلة، والضغط يتناسب عكسياً مع المساحة عند ثبات القوة.

[درس 1-8] سؤال اختباري: نويدة تحتوي على جسيمين نوعين X وY داخل النواة. صف نوع كل منهما.
الإجابة الرسمية: X: بروتونات (شحنة موجبة). Y: نيوترونات (متعادلة الشحنة).

[درس 1-8] سؤال اختباري: ما المقصود بمصطلح النويدة؟
الإجابة الرسمية: نوع محدد من الذرة (النواة) له عدد محدد من البروتونات وعدد محدد من النيوترونات.

[درس 1-8] سؤال اختباري: يوضح الشكل العدد الذري (Z) مقابل عدد النيوترونات (N) لخمسة أنوية ذرات مختلفة (A, B, C, D, E).
أ) اذكر رمز ذرتين تحتويان على نظائر لنفس العنصر.
ب) أي ذرة تتساوى فيها أعداد البروتونات والنيوترونات؟
الإجابة الرسمية: أ) الذرتان (C) و(D) — لهما نفس العدد الذري (Z=6) وبالتالي نفس عدد البروتونات، مما يعني أنهما نظيران لنفس العنصر رغم اختلاف عدد النيوترونات. ب) الذرة (A) — حيث العدد الذري (Z=2) يساوي عدد النيوترونات (N=2).

[درس 1-8] سؤال اختباري: ذرة (C) موضّحة في الشكل — ما عدد النيوكليونات (البروتونات + النيوترونات) لهذه الذرة؟ وأي الذرات (B) تُعدّ من نظائر الذرة (A)؟
الإجابة الرسمية: بحسب أعداد الجسيمات الموضحة في الشكل لكل ذرة (A وB وC): يُحسب عدد النيوكليونات للذرة C بجمع عدد بروتوناتها ونيوتروناتها. والذرة التي تُعدّ نظيراً لذرة أخرى هي التي تتساوى معها في عدد البروتونات (العدد الذري) وتختلف في عدد النيوترونات.

[درس 1-8] سؤال اختباري: عرّف كلاً من: أ) النويدة. ب) النظائر.
الإجابة الرسمية: أ) النويدة: نوع محدد من الذرة (النواة) له عدد محدد من البروتونات وعدد محدد من النيوترونات. ب) النظائر: ذرات للعنصر نفسه (لها نفس العدد الذري/عدد البروتونات) لكنها تختلف في عدد النيوترونات (وبالتالي العدد الكتلي).

[درس 1-8] سؤال اختباري: رسم تخطيطي لذرة البريليوم (Be₄⁹). أ) ماذا يمثل كل من (X) و(Y) في الرسم؟ ب) ما المقصود بالنويدة؟
الإجابة الرسمية: أ) (X) يمثل بروتوناً أو نيوتروناً داخل النواة (حسب موضعه في الرسم)، و(Y) يمثل إلكتروناً يدور في مدار حول النواة. ب) النويدة: نوع محدد من الذرة له عدد محدد من البروتونات وعدد محدد من النيوترونات.

[درس 1-8] سؤال اختباري: اكتب اثنين من مكونات النواة.
الإجابة الرسمية: البروتونات والنيوترونات.

[درس 1-8] سؤال اختباري: نواة ذرة السيزيوم بالرمز (Cs-133, Z=55). أ) كم عدد نيوكليونات هذه الذرة؟ ب) إذا فقدت نواة ذرة العنصر نيوتروناً، اكتب الرمز الجديد للذرة.
الإجابة الرسمية: أ) عدد النيوكليونات = العدد الكتلي = 133. ب) بعد فقد نيوترون واحد يصبح العدد الكتلي 132 بينما يبقى العدد الذري 55 (Z=55, A=132).

[درس 1-9] سؤال اختباري: أي مصادر الإشعاع الخلفي التالية يُعتبر مصدراً طبيعياً رئيسياً في الأماكن المرتفعة؟
الإجابة الرسمية: غاز الرادون (يتزايد التعرض له في بعض المناطق المرتفعة أو المغلقة).

[درس 1-9] سؤال اختباري: شخصان أحدهما يسكن قرب سطح الأرض والآخر في مكان مرتفع، أيهما يتعرض أكثر للإشعاع الكوني؟ ولماذا؟
الإجابة الرسمية: الشخص الذي يسكن في المكان الأعلى؛ لأنه كلما ارتفعنا عن سطح الأرض زاد تعرضنا للأشعة الكونية (الغلاف الجوي يمتص جزءاً أقل من الإشعاع في الارتفاعات العالية).

[درس 1-9] سؤال اختباري: اكتب اثنين من التأثيرات الضارة للإشعاعات على الإنسان.
الإجابة الرسمية: - تلف الحمض النووي (DNA) وحدوث طفرات جينية. - حدوث أورام سرطانية، أو حروق جلدية (يُقبل أي اثنين من هذه التأثيرات).

[درس 2-1] سؤال اختباري: طفل ينزلق على زحليقة بلاستيكية فيصبح شعره مشحوناً كهربائياً بعد الانزلاق. ما سبب ذلك؟
الإجابة الرسمية: بسبب الاحتكاك بين ملابس الطفل والزحليقة، أو بسبب انتقال الإلكترونات بين الطفل والزحليقة أثناء الاحتكاك.

[درس 2-1] سؤال اختباري: طفلة تنزلق إلى أسفل زحليقة بلاستيكية فيقف شعر رأسها. أ) اشرح السبب. ب) ما نوع القوة الكهربائية الموجودة على شعرها؟
الإجابة الرسمية: أ) بسبب الاحتكاك بين شعر الطفلة والزحليقة البلاستيكية أثناء الانزلاق، تنتقل الإلكترونات فيشحن الشعر والزحليقة بشحنتين مختلفتين. ب) قوة تنافر (خصلات الشعر تحمل نفس نوع الشحنة فتتنافر عن بعضها فتقف).

[درس 2-1] سؤال اختباري: كرة بلاستيكية مشحونة معلّقة بالقرب من ساق مشحونة بشحنة سالبة نتيجة دلكها بقطعة قماش. أ) ما نوع الشحنة على الكرة؟ ب) ما نوع القوة الكهربائية بين الكرة والساق؟ ج) كيف يتسبب الدلك في جعل الساق مشحونة بشحنة سالبة؟
الإجابة الرسمية: أ) سالبة (بدليل حدوث تنافر بينها وبين الساق السالبة، بحسب النتيجة في السؤال). ب) قوة تنافر. ج) عند الدلك تنتقل الإلكترونات من قطعة القماش إلى الساق، فتكتسب الساق إلكترونات زائدة وتصبح شحنتها سالبة.

[درس 2-10] سؤال اختباري: يوضّح تمثيل بياني عدد ذرات المادة المشعة المتبقية في عيّنة مع مرور الزمن (بدءاً من 400 ذرة). ب) كم عدد ذرات المادة المتبقية بعد مرور ثلاث فترات من عمر النصف؟ ج) كم من الزمن يلزم لانحلال (300) ذرة من هذه المادة المشعة (أي تبقّي 100 ذرة فقط)؟
الإجابة الرسمية: ب) 50 ذرة (400 → 200 → 100 → 50 بعد ثلاث فترات عمر نصف متتالية). ج) 10 دقائق (بافتراض أن عمر النصف الواحد يساوي 5 دقائق حسب الرسم البياني، فإن الوصول من 400 إلى 100 ذرة يستغرق فترتي عمر نصف = 10 دقائق).

[درس 2-10] سؤال اختباري: أكمل معادلة الاضمحلال الآتية: Am-243(95) → Np-239(93) + ... + طاقة. ثم عرّف عمر النصف.
الإجابة الرسمية: الجسيم الناتج المفقود هو جسيم ألفا: He-4(2) — أي أن الأمريسيوم-243 يضمحل بانبعاث جسيم ألفا لينتج نبتونيوم-239. عمر النصف: متوسط الزمن الذي يستغرقه اضمحلال نصف النوى في عينة من مادة مشعة.

[درس 2-2] سؤال اختباري: دائرة كهربائية تحتوي على ثلاث مقاومات موصولة تباعاً بحيث يمر فيها نفس التيار — ما نوع هذا التوصيل؟
الإجابة الرسمية: توصيل على التوالي.

[درس 2-2] سؤال اختباري: دائرة فيها مقاومتان بقيمة 2Ω وأخرى 4Ω موصولة على التوالي بمصدر جهد 4V، ثم أُعيد توصيلها على التوازي بنفس الجهد. قارن بين التيارين.
الإجابة الرسمية: على التوالي: المقاومة الكلية = 2+2+4 = 8Ω، والتيار I₁ = V/R = 4/8 = 0.5A. على التوازي: 1/R = 1/2+1/2+1/4 = 5/4، فتكون المقاومة الكلية = 0.8Ω، والتيار I₂ = 4/0.8 = 5A. إذن I₂ أكبر من I₁ (التيار في التوازي أكبر من التيار في التوالي).

[درس 2-2] سؤال اختباري: اذكر ميزتين لتوصيل مجموعة من المصابيح على التوازي في دائرة كهربائية.
الإجابة الرسمية: - يمكن إضاءة كل مصباح بشكل منفصل عن الآخر. - إذا تعطل أحد المصابيح، تبقى بقية المصابيح مضاءة (لا تنقطع الدائرة بالكامل). (كذلك: فرق الجهد على كل مصباح يساوي جهد المصدر نفسه).

[درس 2-2] سؤال اختباري: دائرة كهربائية تحتوي على ثلاث مقاومات قيمة كل منها (3Ω) موصولة على التوازي. ما المقاومة المكافئة لمجموعة المقاومات؟
الإجابة الرسمية: 1Ω (لأن 1/R = 1/3+1/3+1/3 = 1، إذن R = 1Ω).

[درس 2-2] سؤال اختباري: دائرة كهربائية تحتوي على مقاومتين (R1) و(R2) موصولتين بالتوالي مع مصدر جهد وأميتر. أ) ما نوع توصيل المقاومات؟ ب) ماذا سيحدث لقراءة الأميتر إذا أُضيفت مقاومة (R3) بين النقطتين (X, Y) (أي على التوالي أيضاً)؟
الإجابة الرسمية: أ) توصيل على التوالي. ب) تقلّ قراءة الأميتر (لأن إضافة مقاومة أخرى على التوالي تزيد المقاومة الكلية للدائرة، فيقلّ التيار المار فيها حسب قانون أوم).

[درس 2-2] سؤال اختباري: دائرة فيها ثلاثة مصابيح متماثلة قدرة كل منها (44W) ومنصهر يتحمل تياراً شدته (2A)، متصلة بمصدر جهد (220V). أ) ما طريقة توصيل المصابيح؟ ب) ما جهد المصباح الواحد؟ ج) ما وحدة قياس القدرة؟ د) احسب قيمة التيار المار في المنصهر. هـ) ماذا يحدث لشدة التيار عند إضافة مصباح رابع بنفس الطريقة؟ و) ما إجمالي عدد المصابيح التي يمكن توصيلها دون تلف المنصهر؟
الإجابة الرسمية: أ) توصيل على التوازي. ب) 220 فولت (جهد كل مصباح في التوازي يساوي جهد المصدر). ج) الواط (W). د) التيار الكلي = مجموع تيارات المصابيح = (44/220)×3 = 0.2×3 = 0.6 أمبير تقريباً (كل مصباح يسحب 0.2A). هـ) تزداد شدة التيار الكلي (يضاف تيار المصباح الرابع 0.2A إلى المجموع). و) يمكن توصيل حتى 10 مصابيح دون تلف المنصهر (10×0.2A = 2A، وهو الحد الأقصى الذي يتحمله المنصهر).

[درس 2-2] سؤال اختباري: اذكر ميزتين من مميزات طريقة توصيل المصابيح على التوازي.
الإجابة الرسمية: - يمكن تشغيل كل مصباح بشكل مستقل عن الآخر. - إذا تعطل أحد المصابيح تبقى بقية المصابيح تعمل. (كذلك: جهد كل مصباح يساوي جهد المصدر).

[درس 2-2] سؤال اختباري: دائرة كهربائية فيها مقاومتان (2Ω) و(4Ω)، وقراءة الأميتر (3A). ما قيمة التيار المار خلال المقاومة (4Ω)؟
الإجابة الرسمية: 3A (المقاومتان موصولتان على التوالي في هذا الفرع، فيمر نفس التيار خلال كل عناصر الفرع الواحد).

[درس 2-2] سؤال اختباري: دائرة كهربائية فيها مقاومتان (R1) و(R2)، إذا تمت إضافة مقاومة ثالثة على التوازي مع المقاومات الحالية، فماذا سيحدث لقراءة الفولتميتر؟
الإجابة الرسمية: لا تتغير قراءة الفولتميتر (جهد كل فرع في التوصيل على التوازي يبقى مساوياً لجهد المصدر نفسه، بغض النظر عن عدد الفروع المضافة).

[درس 2-3] سؤال اختباري: لماذا ينصهر سلك المنصهر ويقطع الدائرة الكهربائية في جهاز مثل مجفف الشعر؟
الإجابة الرسمية: إذا أصبحت شدة التيار المار في الدائرة كبيرة جداً، ينصهر السلك ويقطع الدائرة لحمايتها.

[درس 2-3] سؤال اختباري: جهاز قدرته الكهربائية 840 واط يعمل على فرق جهد 240 فولت. ما قيمة المنصهر المناسب له؟
الإجابة الرسمية: شدة التيار I = P/V = 840/240 = 3.5A. المنصهر المناسب الذي يليه هو منصهر بقيمة 5A.

[درس 2-3] سؤال اختباري: ما الغرض من استخدام المنصهر في الدائرة الكهربائية؟
الإجابة الرسمية: حماية الأجهزة الكهربائية من التلف الناتج عن زيادة شدة التيار.

[درس 2-3] سؤال اختباري: ما وظيفة المنصهر في الدائرة الكهربائية؟ ثم: مكنسة كهربائية قدرتها 3000 واط تعمل بجهد 240 فولت، احسب شدة التيار اللازم لتشغيلها الطبيعي، وحدد المنصهر المناسب لها من بين (3A، 9A، 13A).
الإجابة الرسمية: وظيفة المنصهر: حماية الأجهزة من التلف (ينصهر سلكه ليقطع التيار عند زيادته عن الحد الآمن). شدة التيار = القدرة ÷ الجهد = 3000 ÷ 240 = 12.5 أمبير. المنصهر المناسب: 13A (أقرب قيمة أعلى من 12.5A من الخيارات المتاحة).

[درس 2-3] سؤال اختباري: ما وظيفة المنصهر؟
الإجابة الرسمية: حماية الدائرة والأجهزة الكهربائية من التلف عن طريق قطع التيار إذا زادت شدته عن الحد الآمن.

[درس 2-3] سؤال اختباري: لماذا يُفضّل عدم استخدام مجفف الشعر في الحمام؟
الإجابة الرسمية: لخطورة تعرّض الجهاز الكهربائي للرطوبة أو الماء، مما قد يسبب صدمة كهربائية أو ماساً كهربائياً؛ لأن الماء موصل للكهرباء.

[درس 2-3] سؤال اختباري: مكنسة كهربائية قدرتها (2000W) تعمل بجهد (240V). أ) ما المنصهر المناسب لها من بين (13A، 30A)؟ ب) فسّر إجابتك.
الإجابة الرسمية: أ) 13A. ب) شدة التيار العادي للمكنسة = القدرة ÷ الجهد = 2000 ÷ 240 ≈ 8.3A. يجب اختيار منصهر أكبر قليلاً من هذه القيمة لكن ليس كبيراً جداً حتى يقطع التيار عند حدوث أي زيادة خطرة؛ لذا فإن 13A هو الأنسب (لأن 30A كبيرة جداً ولن تحمي الجهاز بفعالية).

[درس 2-4] سؤال اختباري: أ) أكمل الجدول الذي يتضمن قوى تؤثر على المركبة الفضائية أثناء إقلاعها: القوة التي معناها "تعمل صعوداً من سطح معين لدعم شيء ما" ما اسمها؟ والقوة الثانية (الاحتكاك) ما مفهومها؟ ب) حدد قوتين تسببان تغيرات في حجم الجسم الصلب وشكله.
الإجابة الرسمية: أ) القوة الأولى: قوة الدفع (Thrust) — وهي القوة التي تعمل صعوداً من سطح معين (محركات الصاروخ) لدعم ورفع المركبة. الاحتكاك: قوة تنشأ بين أي سطحي جسمين صلبين متلامسين لمقاومة الحركة. ب) قوتان من: قوى الضغط، قوى الشد، قوى اللي، قوى الثني (يُقبل ذكر أي اثنتين منها).

[درس 2-5] سؤال اختباري: قوة مقدارها 80 نيوتن تؤثر عمودياً على ذراع طوله 0.4 متر من محور الدوران. احسب عزم القوة.
الإجابة الرسمية: عزم القوة = القوة × المسافة العمودية من محور الدوران = 80 × 0.4 = 16 نيوتن.متر (N.m).

[درس 2-5] سؤال اختباري: عارضة (MN) ترتكز عند نقطة المنتصف (P)، ويُعلّق وزنان (W1) و(W2) بين طرفيها وتبقى متزنة. ما اتجاه القوة المحصلة على العارضة واتجاه العزم الناتج حول النقطة M؟
الإجابة الرسمية: القوة المحصلة على العارضة = صفر (متزنة انتقالياً)، والعزم الناتج حول النقطة M أيضاً = صفر (متزنة دورانياً، لأن مجموع العزوم مع عقارب الساعة يساوي مجموع العزوم عكسها).

[درس 2-5] سؤال اختباري: طالب يحمل وزناً قدره (50N) بذراعه، والمسافة من محور الكتف حتى نقطة تعليق الوزن (0.90m). احسب عزم القوة حول هذا المحور.
الإجابة الرسمية: عزم القوة = القوة × المسافة العمودية = 50 × 0.90 = 45 نيوتن.متر (N.m).

[درس 2-5] سؤال اختباري: عربة بها ثقل، يبلغ وزن العربة والثقل معاً (600N)، والمسافات من نقطة الارتكاز (70cm) للثقل و(50cm) لموضع رفع القوة (F). احسب مقدار القوة (F) اللازمة لرفع العربة.
الإجابة الرسمية: بتطبيق مبدأ اتزان العزوم حول نقطة الارتكاز (العجلة): 600×0.70 = F×1.20 (المسافة الكلية من العجلة إلى مقبض الرفع)، وبالتالي F = 420 ÷ 1.20 = 350 نيوتن.

[درس 2-6] سؤال اختباري: ما العلاقة بين الشغل الذي يُبذل على جسم والطاقة المنقولة إليه؟
الإجابة الرسمية: الطاقة المنقولة (التغيّر في الطاقة) تساوي مقدار الشغل المبذول على الجسم.

[درس 2-6] سؤال اختباري: أكمل المصطلح العلمي: أ) معدل نقل الطاقة. ب) الطاقة المنقولة بواسطة قوة عندما يتحرك الجسم مسافة ما باتجاه هذه القوة.
الإجابة الرسمية: أ) القدرة. ب) الشغل المبذول.

[درس 2-7] سؤال اختباري: احسب الضغط الذي تؤثر به قوة مقدارها (40 نيوتن) على سطح مساحته (2 متر مربع)، مبيّناً وحدة القياس.
الإجابة الرسمية: الضغط = القوة ÷ المساحة = 40 ÷ 2 = 20 باسكال (Pa).

[درس 2-7] سؤال اختباري: ما الوحدة الدولية لقياس الضغط؟ ثم: حجر وزنه (600N) على شكل متوازي مستطيلات أبعاده (2.5m × 0.80m × 2.0m). احسب مقدار الضغط الذي يبذله الحجر على الأرض.
الإجابة الرسمية: الوحدة الدولية للضغط: الباسكال (Pa). أصغر مساحة تلامس محتملة للحجر مع الأرض = 0.80 × 2.0 = 1.6 م² (لتعظيم الضغط يُفترض وضعه على أصغر وجه، أو حسب الوجه الملامس فعلياً في السؤال). الضغط = القوة ÷ المساحة = 600 ÷ 1.6 = 375 باسكال تقريباً.

[درس 2-9] سؤال اختباري: أي أنواع الإشعاع المؤيّن (ألفا، بيتا، جاما) يوصف بأنه "شديد التأين"؟
الإجابة الرسمية: إشعاع ألفا (α) هو الأشد تأيناً بين الأنواع الثلاثة، رغم أنه الأقل قدرة على الاختراق.

[درس 2-9] سؤال اختباري: إشعاعات تنبعث من مصدر مشع وتمر بين لوحين مشحونين (مجال كهربائي)، فينحرف أحد الشعاعين (أ) بشكل طفيف نحو اللوح السالب بينما يظل الآخر (ب) على مساره دون انحراف ملحوظ نسبياً. ما نوع كل من الإشعاعين (أ) و(ب)؟
الإجابة الرسمية: بحسب اتجاه ومقدار الانحراف الظاهر في الشكل: الإشعاع (أ) جسيمات ألفا (α)، والإشعاع (ب) أشعة جاما (γ) — إذ تنجذب جسيمات ألفا الموجبة نحو اللوح السالب بينما لا تتأثر أشعة جاما المتعادلة بالمجال الكهربائي.

[درس 2-9] سؤال اختباري: أي نوع من الإشعاع رصده المهندس أثناء تحديد موقع تسرب الماء تحت الأرض باستخدام مادة مشعة؟
الإجابة الرسمية: أشعة جاما (γ)؛ لأنها الأكثر قدرة على اختراق التربة وصولاً إلى سطح الأرض حيث يقف المهندس.

[درس 2-9] سؤال اختباري: باستخدام حاجز من الورق وآخر سميك من الألومنيوم للتعرف على نوع الإشعاع الصادر من مصدر مشع: أ) إذا وُضع كاشف في المنطقة (Y) خلف حاجز الورق فقط، فما نوع الإشعاعات التي سيرصدها؟ ب) ماذا سيحدث لقراءة الكاشف إذا وُضع في المنطقة (X) خلف حاجز الألومنيوم السميك أيضاً، مقارنة بقراءته في (Y)؟
الإجابة الرسمية: أ) يرصد الكاشف في المنطقة (Y) إشعاعي جاما وبيتا (حاجز الورق الرقيق يوقف جسيمات ألفا فقط ولا يوقف بيتا وجاما). ب) تقلّ القراءة في المنطقة (X)؛ لأن حاجز الألومنيوم السميك يوقف أيضاً جسيمات بيتا، فلا يمر خلاله إلا أشعة جاما.

[درس 2-9] سؤال اختباري: أي الخصائص الآتية صحيحة حول جسيمات ألفا؟ (تتكون من بروتونين وإلكترونين / أكثر أنواع الإشعاع اختراقاً / نوع من الإشعاع الكهرومغناطيسي / شديدة التأين)
الإجابة الرسمية: شديدة التأين (جسيمات ألفا تتكون فعلياً من بروتونين ونيوترونين فقط بلا إلكترونات، وهي الأقل اختراقاً والأكثر تأيناً بين أنواع الإشعاع الثلاثة).

[درس 2-9] سؤال اختباري: إشعاعات تنبعث من مصدر مشع وتدخل منطقة مجال كهربائي بين لوحين مشحونين، وينحرف الشعاعان بشكل مختلف. ما نوع الإشعاعين (أ) و(ب) المنبعثين من المصدر؟
الإجابة الرسمية: بحسب اتجاهي الانحراف: الإشعاع (أ) جسيمات ألفا (α)، والإشعاع (ب) جسيمات بيتا (β) (أو حسب مقدار واتجاه الانحراف الموضح في الشكل تحديداً).

[درس 2-9] سؤال اختباري: جدول مقارنة بين أشعة ألفا وأشعة جاما — أكمل بياناته: القدرة على التأيين (أكثر، أقل).
الإجابة الرسمية: ألفا (α): أكثر قدرة على التأيين. جاما (γ): أقل قدرة على التأيين (وأكثرها قدرة على الاختراق).

[درس 3-1] سؤال اختباري: ما اسم المنطقة المحيطة بالشحنة الكهربائية التي تتأثر فيها الشحنات الأخرى بقوة؟
الإجابة الرسمية: المجال الكهربائي.

[درس 3-1] سؤال اختباري: عند دلك قضيب أبونايت بقطعة قماش، ما نوع الشحنة التي يكتسبها القماش؟ ولماذا؟
الإجابة الرسمية: موجبة؛ لأن القماش يفقد إلكتروناته أثناء الدلك، وتنتقل هذه الإلكترونات من القماش إلى القضيب.

[درس 3-1] سؤال اختباري: عند توصيل نقطة على كرة فلزية مشحونة بسلك معدني متصل بالأرض، ما نوع الشحنة التي تمر عبر السلك؟ ولماذا؟
الإجابة الرسمية: سالبة؛ لأن الطرف الملاصق للسلك يحمل شحنات سالبة أكثر، بينما الأرض متعادلة كهربائياً، فتنتقل الشحنة السالبة نحو الأرض.

[درس 3-1] سؤال اختباري: عند دلك قضيب بلاستيكي بقطعة قماش من النايلون، ولاحظنا أنه يجذب قصاصات ورق صغيرة — فسّر ذلك. ثم قارن بحالة دلك قضيب نحاسي بقماش من الصوف وإمساكه باليد.
الإجابة الرسمية: عند دلك القضيب البلاستيكي بالنايلون: تنتقل الإلكترونات من القماش إلى القضيب، فيكتسب القضيب شحنة سالبة تمكّنه من جذب قصاصات الورق (مادة عازلة تحتفظ بالشحنة). أما عند دلك قضيب نحاسي (موصل) بقماش الصوف وإمساكه باليد: تنتقل الشحنات من الصوف إلى النحاس، لكن بما أن النحاس موصل وملامس لليد، فإن الشحنة تتسرب فوراً إلى اليد ثم الجسم ولا تبقى على القضيب.

[درس 3-1] سؤال اختباري: ما الاسم الذي يُطلق على المنطقة المحيطة بالكرة المشحونة التي تتأثر فيها الشحنات الأخرى بقوة؟
الإجابة الرسمية: المجال الكهربائي.

[درس 3-1] سؤال اختباري: ماذا سيحدث عند ملامسة الكرة الفلزية المشحونة بسلك نحاس متعادل كهربائياً؟
الإجابة الرسمية: تفقد الكرة شحنتها (تنتقل الشحنة من الكرة عبر السلك النحاسي الموصل إلى أن يصبح الجهد متعادلاً).

[درس 3-1] سؤال اختباري: كرة فلزية مشحونة موضوعة بالقرب من مجموعة نقاط (A)، (B)، (C)، (D) بمسافات مختلفة عنها. عند أي نقطة تكون شدة المجال الكهربائي أكبر؟
الإجابة الرسمية: عند النقطة الأقرب إلى الكرة المشحونة (شدة المجال الكهربائي تتناسب عكسياً مع مربع المسافة عن الشحنة، فتكون أكبر ما يمكن عند أقرب نقطة).

[درس 3-1] سؤال اختباري: ماذا تسمى المنطقة المحيطة بالساق المشحونة؟
الإجابة الرسمية: المجال الكهربائي.

[درس 3-1] سؤال اختباري: عند دلك قضيب بلاستيك بقماش من النايلون تنجذب قصاصات الورق للقضيب، بينما عند دلك قضيب نحاس بقماش من الصوف لا تنجذب قصاصات الورق لقضيب النحاس. اشرح ذلك.
الإجابة الرسمية: القضيب البلاستيكي عازل، فتبقى عليه الشحنة الناتجة عن الدلك ولا تتسرب، فيجذب قصاصات الورق الخفيفة. أما قضيب النحاس فموصل، وبما أنه ممسوك باليد (وجسم الإنسان موصل)، فإن أي شحنة تنتقل إليه أثناء الدلك تتسرب فوراً إلى الأرض عبر اليد والجسم، فلا تتراكم عليه شحنة تكفي لجذب الورق.

[درس 3-10] سؤال اختباري: ما المقصود بعمر النصف لنويدة مشعة؟
الإجابة الرسمية: هو متوسط الزمن الذي يستغرقه اضمحلال نصف عدد النوى المشعة الموجودة في عينة من مادة مشعة.

[درس 3-10] سؤال اختباري: عينة مشعة معدل عدّها ينخفض تباعاً: 60 ثم 30 ثم 15 ثم 7.5 ثم 3.75 عداً في الدقيقة، وكل عمر نصف يساوي يوماً واحداً. احسب الزمن الكلي اللازم للوصول إلى القيمة الأخيرة.
الإجابة الرسمية: عدد أعمار النصف التي مرّت = 4 (كل انخفاض إلى النصف = عمر نصف واحد). الزمن الكلي = عدد أعمار النصف × مدة عمر النصف الواحد = 4 × يوم واحد = 4 أيام.

[درس 3-10] سؤال اختباري: جدول يبيّن معدل النشاط الإشعاعي (عدد العد بالثانية) لمادة مشعة عند أزمنة مختلفة (0، 20، 40، 60، 80 ثانية). أ) ما مقدار عدد الذرات الأصلية (النشاط عند الزمن صفر)؟ ب) ما مقدار عمر النصف للعينة؟ ج) كم عدد الذرات المضمحلة عند الزمن (60s)؟ د) كم عدد الذرات المتبقية بعد مرور ثلاثة أنصاف أعمار؟ هـ) ما المقصود بعمر النصف؟
الإجابة الرسمية: أ) 300 (القيمة عند الزمن صفر). ب) عمر النصف ≈ 40 ثانية (الزمن اللازم لتناقص النشاط من 300 إلى 150). ج) عند الزمن 60s يكون النشاط المتبقي 100، فيكون عدد الذرات المضمحلة = 300 − 100 = 200 تقريباً (بحسب نفس النسبة). د) بعد ثلاثة أنصاف أعمار (120 ثانية تقريباً): 300 → 150 → 75 → 37.5 ذرة تقريباً. هـ) عمر النصف: متوسط الزمن الذي يستغرقه اضمحلال نصف عدد النوى المشعة في عينة من مادة مشعة.

[درس 3-10] سؤال اختباري: جدول يوضح عدد الإشعاعات الصادرة من عينة مادة مشعة لكل دقيقة عند أزمنة مختلفة (من 800 عند الزمن صفر إلى 100 عند الزمن 60 دقيقة). أ) ما مقدار عمر النصف للمادة المشعة؟ ب) كم عدد الإشعاعات الصادرة من العينة بعد مرور ثلاثة أعمار نصف؟
الإجابة الرسمية: أ) عمر النصف = 20 دقيقة (الزمن اللازم لتناقص القراءة من 800 إلى 400). ب) بعد ثلاثة أعمار نصف من القيمة الأصلية 800: 800 → 400 → 200 → 100 إشعاع/دقيقة (وهذا يتفق مع القيمة الموضحة في الجدول عند الزمن 60 دقيقة أي 3×20).

[درس 3-4] سؤال اختباري: أكمل الجدول: ما المصطلح الفيزيائي الذي تعريفه "القوة التي لها نفس تأثير قوتين أو أكثر مؤثرتين على جسم ما"؟
الإجابة الرسمية: محصّلة القوى (القوة المحصّلة).

[درس 3-5] سؤال اختباري: شكلان (C) و(D) لجسمين موضوعين على سطح مستوٍ، مع تحديد مركز كتلة كل منهما بنقطة. حدد أي الجسمين سيقع (أقل استقراراً).
الإجابة الرسمية: الجسم الذي يقع مركز كتلته خارج قاعدة استناده أو أقرب لحافتها هو الأقل استقراراً وسيقع (حسب الشكل المحدد في السؤال، وهو الجسم D في هذه الحالة نظراً لارتفاع موقع مركز كتلته وقرب سقوطه عن حدود القاعدة).

[درس 3-5] سؤال اختباري: ما المقصود بمركز الكتلة؟
الإجابة الرسمية: هي النقطة التي يمكن اعتبار كتلة الجسم بأكملها مركّزة فيها (تتوازن حولها جميع أجزاء الجسم).

[درس 3-5] سؤال اختباري: شكل يوضح جراراً زراعياً على منحدر، مع ثلاث نقاط محتملة (A، B، C) لمركز الكتلة. ما أفضل موقع لمركز كتلة الجرار لكي لا يقع؟
الإجابة الرسمية: النقطة (B)؛ لأنها الأقرب لقاعدة استناد الجرار والأكثر انخفاضاً، مما يزيد من ثبات الجرار ويقلل احتمال انقلابه على المنحدر.

[درس 3-6] سؤال اختباري: طالبان لهما نفس الكتلة يصعدان درجات السلم نفسها للوصول لنفس الطابق. وصل الأول خلال 15 ثانية، ووصل الثاني لنفس الموقع خلال 25 ثانية. أ) هل يبذل الطالب الأول شغلاً مساوياً لما يبذله الثاني؟ ب) أي الطالبين قدرته أكبر؟
الإجابة الرسمية: أ) نعم؛ لأنهما بذلا نفس مقدار الشغل (نفس الكتلة ونفس الارتفاع الرأسي المقطوع، بغض النظر عن الزمن). ب) الطالب الأول؛ لأنه بذل نفس الشغل خلال زمن أقل، والقدرة = الشغل ÷ الزمن، فكلما قلّ الزمن زادت القدرة.

[درس 3-6] سؤال اختباري: مجفف شعر قدرته (600 واط)، ما مقدار الشغل الذي ينجزه خلال دقيقة واحدة؟
الإجابة الرسمية: الشغل = القدرة × الزمن = 600 × 60 = 36000 جول.

[درس 3-6] سؤال اختباري: رافعة ترفع جذع شجرة وزنه (96000N) إلى ارتفاع (3.2m) خلال (25s). أ) احسب قدرة الرافعة عند رفع الجذع. ب) ما المقصود بالقدرة؟
الإجابة الرسمية: أ) القدرة = الشغل ÷ الزمن = (القوة × الارتفاع) ÷ الزمن = (96000 × 3.2) ÷ 25 = 307200 ÷ 25 = 12288 واط. ب) القدرة: معدل الشغل المبذول أو الطاقة المنقولة في وحدة الزمن.

[درس 3-6] سؤال اختباري: عاملان يرفعان صناديق باستخدام محرك. إذا تمت زيادة سرعة المحرك، فماذا سيحدث لكل من الشغل المبذول والقدرة التي يبذلها المحرك؟
الإجابة الرسمية: الشغل المبذول: لا يتغير (نفس الوزن ونفس الارتفاع، فالشغل ثابت بغض النظر عن السرعة). القدرة: تزداد (لأن نفس الشغل يتم إنجازه خلال زمن أقل، والقدرة = الشغل ÷ الزمن).

[درس 3-6] سؤال اختباري: جهاز كهربائي قدرته (6000W) يعمل لمدة (30 دقيقة). احسب الشغل الذي يبذله هذا الجهاز.
الإجابة الرسمية: الزمن بالثواني = 30 × 60 = 1800 ثانية. الشغل = القدرة × الزمن = 6000 × 1800 = 10800000 جول (10.8 مليون جول).

[درس 3-9] سؤال اختباري: ما اسم التقنية التي استخدمها المهندس (حقن مادة مشعة في أنبوب الماء لتحديد موقع التسرب برصد أكبر معدل إشعاع) لتحديد موقع تسرب الماء من الأنبوب المدفون تحت الأرض؟
الإجابة الرسمية: التتبع الإشعاعي (استخدام النظائر المشعّة كمتتبعات).

[درس 3-9] سؤال اختباري: طالب يجري تجربة لمعرفة نوع الإشعاع الصادر من مادة مشعة تصدر (95 إشعاع لكل دقيقة)، بوضع حواجز مختلفة (ورقة رقيقة، ثم ألومنيوم 5mm) وتسجيل قراءة الكاشف (70، ثم 59 عد/دقيقة على التوالي). أ) اكتب نوع الإشعاعات الصادرة من المادة المشعة. ب) ما التغيير الذي سيحدث لقراءة العداد إذا استخدم حاجزاً من الرصاص؟
الإجابة الرسمية: أ) بما أن الورقة الرقيقة خفّضت القراءة (من 95 إلى 70، أي أوقفت جزءاً من الإشعاع وهو ألفا)، واستمر انخفاض إضافي مع الألومنيوم (إلى 59، موقفةً جزءاً من بيتا)، فإن المادة تصدر خليطاً من الإشعاعات: ألفا وبيتا وجاما. ب) ستنخفض (تقل) قراءة الكاشف أكثر؛ لأن الرصاص يمتص أيضاً أشعة جاما التي تتخطى حاجزي الورق والألومنيوم.

[درس 4-1] سؤال اختباري: لماذا يجب حمل الكرة الفلزية بواسطة عازل عند التعامل مع الشحنات؟
الإجابة الرسمية: حتى لا يحدث تفريغ للشحنة الموجودة على الكرة، لأن العوازل لا تسمح بتدفق الشحنات من خلالها.

[درس 4-1] سؤال اختباري: ما المقصود بالموصل الكهربائي؟
الإجابة الرسمية: مادة تسمح بمرور (تدفق) التيار الكهربائي بسهولة.

[درس 4-1] سؤال اختباري: إحدى المواد الآتية تسمح بمرور التيار الكهربائي: النحاس، الزجاج، البلاستيك، الخشب. أيها؟
الإجابة الرسمية: النحاس (موصل كهربائي)؛ أما الزجاج والبلاستيك والخشب فهي مواد عازلة.

[درس 4-1] سؤال اختباري: ما فائدة القاعدة العازلة الموجودة أسفل الكرة الفلزية المشحونة؟
الإجابة الرسمية: للحفاظ على الشحنة الكهربائية للكرة (منع تسرّب الشحنة إلى الأرض عبر أي جسم موصل).

[درس 4-1] سؤال اختباري: لماذا يجب حمل الكرة الفلزية بواسطة عازل عند تقريب ساق مشحونة منها؟
الإجابة الرسمية: للحفاظ على الشحنة الكهربائية للكرة (منع تسرّبها إلى الأرض عبر أي مادة موصلة).

[درس 4-1] سؤال اختباري: قارن بين الموصل والعازل من حيث توصيل كل منهما للتيار الكهربائي.
الإجابة الرسمية: الموصل: مادة تسمح بمرور (توصيل) التيار الكهربائي بسهولة (مثل المعادن). العازل: مادة لا تسمح بمرور التيار الكهربائي أو تقاومه بشدة (مثل البلاستيك والزجاج).

[درس 4-1] سؤال اختباري: إحدى المواد الآتية لا توصل التيار الكهربائي: النحاس، الحديد، الفولاذ، الخشب. أيها؟
الإجابة الرسمية: الخشب (مادة عازلة)؛ أما النحاس والحديد والفولاذ فموصلات معدنية.

[درس 4-4] سؤال اختباري: ما المقصود باستطالة الزنبرك؟
الإجابة الرسمية: هي الزيادة في طول الزنبرك عن طوله الأصلي نتيجة تأثير حمولة (قوة شد) عليه.

[درس 4-4] سؤال اختباري: ما المقصود بحد التناسب للزنبرك؟
الإجابة الرسمية: هي النقطة التي لا يعود بعدها الزنبرك خاضعاً لقانون هوك (أي لا تعود العلاقة بين القوة المؤثرة والاستطالة علاقة خطية متناسبة).

[درس 4-4] سؤال اختباري: زنبرك طوله الأصلي بدون حمل موضّح في شكل، وطوله بعد تعليق كتلة (0.25kg) موضّح في شكل آخر. أ) ما طول الزنبرك الأصلي؟ ب) احسب استطالة الزنبرك عند تعليق الكتلة (0.25kg). ج) احسب طول الزنبرك عند استبدال الكتلة بأخرى مقدارها (0.75kg).
الإجابة الرسمية: أ) طول الزنبرك الأصلي = 12 سم (كما في الشكل الأول بدون حمل). ب) الاستطالة = الطول الجديد − الطول الأصلي = 13.4 − 12 = 1.4 سم. ج) بما أن الاستطالة تتناسب طردياً مع الحمل (قانون هوك): استطالة عند 0.75kg = 3 × 1.4 = 4.2 سم (لأن الكتلة تضاعفت 3 مرات)، فيكون الطول الجديد = 12 + 4.2 = 16.2 سم تقريباً.

[درس 4-4] سؤال اختباري: عرّف حد التناسب. ثم أكمل الجدول: وحدة قياس (القوة، التسارع، ثابت هوك) في النظام الدولي للوحدات (SI).
الإجابة الرسمية: حد التناسب: النقطة التي لا يعود بعدها الجسم (الزنبرك) خاضعاً لقانون هوك عند تأثير حمل عليه لاستطالته. وحدات القياس: القوة بوحدة النيوتن (N)، التسارع بوحدة متر/ثانية² (m/s²)، ثابت هوك بوحدة نيوتن/متر (N/m).

[درس 4-4] سؤال اختباري: جدول نتائج تجربة استطالة زنبرك (حمل من 0 إلى 5.0N، استطالة من 0 إلى 3.0mm). أ) حدد العامل المستقل والعامل التابع. ب) ارسم الخط البياني الذي يمثل العلاقة بين الحمل والاستطالة.
الإجابة الرسمية: أ) العامل المستقل: الحمل (N). العامل التابع: الاستطالة (mm). ب) العلاقة خطية طردية تمر من نقطة الأصل (خط مستقيم صاعد)، حيث تتناسب الاستطالة طردياً مع الحمل المؤثر (كل 1N يزيد الاستطالة بمقدار 0.6mm تقريباً).

[درس 5-4] سؤال اختباري: أكمل الجدول: ما المصطلح الفيزيائي لـ"النقطة التي لا يعود الجسم عندها خاضعاً لقانون هوك حين يؤثر عليه حمل لاستطالته"؟
الإجابة الرسمية: حدّ التناسب.

[درس 5-4] سؤال اختباري: رسم بياني يوضح العلاقة بين الحمل (N) واستطالة زنبرك آخر (cm). ضع علامة (x) على موضع حد التناسب للزنبرك في الرسم.
الإجابة الرسمية: حدّ التناسب هو النقطة التي يبدأ عندها المنحنى بالانحراف عن الخط المستقيم (الجزء الخطي)، وهي هنا عند حمل يبلغ تقريباً (6N) حيث يبدأ المنحنى بالانحناء الحاد نحو الأعلى.
`;

