const KB_12 = `[درس 1-1] سؤال تدريبي: أي الأوصاف التالية تمثل بشكل صحيح اتجاه خطوط مجال الجاذبية حول كوكب كروي متجانس الكثافة؟ (اختر الإجابة الصحيحة)
(أ) خطوط دائرية تحيط بالكوكب ولا تتقاطع معه أبدًا
(ب) خطوط تنطلق من مركز الكوكب إلى الخارج في جميع الاتجاهات
(ج) خطوط مستقيمة تتجه نحو مركز الكوكب من كل نقطة حوله
(د) خطوط متوازية في اتجاه واحد ثابت بصرف النظر عن الموقع من الكوكب
الإجابة النموذجية: شدة مجال الجاذبية عند أي نقطة تمثَّل بخط مجال يكون اتجاهه هو اتجاه القوة المؤثرة على كتلة اختبار صغيرة موجبة (كتلة نقطية) موضوعة في تلك النقطة.

بما أن قوة الجاذبية بين أي كتلتين قوة تجاذب دائمًا (وليست تنافرًا)، فإن الكتلة الاختبارية عند أي نقطة حول الكوكب تُجذب دائمًا نحو مركز الكوكب.

إذن خطوط المجال يجب أن تكون خطوطًا مستقيمة (شعاعية) تتجه من كل نقطة في الفراغ نحو مركز الكوكب، وتتقارب كلما اقتربنا من السطح.

الإجابة الصحيحة: (ج).

[درس 1-1] سؤال تدريبي: يوجد جسمان A و B حول كوكب كتلته M: يبعد A مسافة r عن مركز الكوكب، ويبعد B مسافة 3r عن المركز. استنتج، باستخدام العلاقة بين شدة مجال الجاذبية والمسافة من المركز، النسبة بين شدة المجال عند A وشدتها عند B (gA : gB).
الإجابة النموذجية: شدة مجال الجاذبية عند نقطة تبعد r عن مركز جسم كتلته M تُعطى بالعلاقة g = GM/r²، أي أن g تتناسب عكسيًا مع مربع المسافة r (g ∝ 1/r²)؛ وهذا ما تعبر عنه أيضًا كثافة خطوط المجال (تتقارب كلما قلّت r).

عند A: gA = GM/r²

عند B: gB = GM/(3r)² = GM/(9r²)

بقسمة المعادلتين: gA/gB = [GM/r²] ÷ [GM/(9r²)] = 9

إذن النسبة gA : gB = 9 : 1، أي أن شدة المجال (وكثافة خطوط المجال) عند A أكبر بتسع مرات منها عند B.

[درس 1-1] سؤال تدريبي: جسمان كتلتاهما 500 kg و 800 kg، تفصل بين مركزيهما مسافة 2.0 m. احسب مقدار قوة الجذب المتبادلة بينهما، مستخدمًا G = 6.67×10⁻¹¹ N m² kg⁻².
الإجابة النموذجية: وفق قانون نيوتن للجذب العام: F = G m₁ m₂ / r²

F = (6.67×10⁻¹¹ × 500 × 800) / (2.0)²

بسط البسط أولًا: 6.67×10⁻¹¹ × 500 = 3.335×10⁻⁸

3.335×10⁻⁸ × 800 = 2.668×10⁻⁵

ثم بالقسمة على المقام (2.0)² = 4.0:

F = 2.668×10⁻⁵ / 4.0 = 6.67×10⁻⁶ N

إذن قوة الجذب المتبادلة بين الجسمين تساوي تقريبًا 6.67×10⁻⁶ N (قوة ضئيلة جدًا مقارنة بالقوى التي نشعر بها يوميًا، لأن ثابت الجذب العام G صغير جدًا).

[درس 1-1] سؤال تدريبي: قمر صناعي كتلته 1200 kg يدور حول الأرض بحيث تبلغ المسافة بين مركزه ومركز الأرض 6.80×10⁶ m. احسب قوة جذب الأرض له. (كتلة الأرض M = 5.97×10²⁴ kg)
الإجابة النموذجية: باستخدام قانون نيوتن للجذب العام: F = G M m / r²

GM = 6.67×10⁻¹¹ × 5.97×10²⁴ = 3.982×10¹⁴ N m² kg⁻¹

GMm = 3.982×10¹⁴ × 1200 = 4.778×10¹⁷

r² = (6.80×10⁶)² = 4.624×10¹³ m²

F = 4.778×10¹⁷ / 4.624×10¹³ = 1.03×10⁴ N

إذن تجذب الأرض القمر الصناعي بقوة مقدارها تقريبًا 1.03×10⁴ N، وهذه القوة هي نفسها التي توفر القوة المركزية اللازمة لبقائه في مداره.

[درس 1-1] سؤال تدريبي: قارن بين قوة جذب الأرض للقمر وقوة جذب القمر للأرض من حيث المقدار والاتجاه، وفسّر إجابتك مستخدمًا قانون نيوتن الثالث للحركة.
الإجابة النموذجية: وفق قانون نيوتن للجذب العام، القوة التي تجذب بها الأرض القمر تساوي في المقدار القوة التي يجذب بها القمر الأرض؛ لأن كلتا القوتين تُحسب من نفس العلاقة F = G M_الأرض M_القمر / r²، وهي كمية واحدة تُطبَّق على كلا الجسمين بالتساوي (زوج قوى وفق قانون نيوتن الثالث للحركة: لكل فعل رد فعل مساوٍ له في المقدار ومضاد له في الاتجاه).

اتجاه القوتين: قوة الأرض على القمر تتجه من القمر نحو مركز الأرض، بينما قوة القمر على الأرض تتجه من الأرض نحو مركز القمر؛ أي أن القوتين متضادتان في الاتجاه ومؤثرتان على جسمين مختلفين (وليس على نفس الجسم)، لذا فهما لا يُلغيان بعضهما.

ملاحظة مهمة: رغم تساوي القوتين في المقدار، فإن التسارع الناتج عن كل منهما مختلف (a = F/m)، فالقمر أقل كتلة من الأرض بكثير، لذا يكتسب تسارعًا أكبر بكثير من التسارع الذي تكتسبه الأرض نتيجة نفس القوة.

[درس 1-1] سؤال تدريبي: جسمان كتلتاهما m₁ و m₂ يفصل بينهما مسافة r وتؤثر بينهما قوة جذب F. إذا أصبحت كتلة الجسم الأول 3m₁ (أي تضاعفت ثلاث مرات) وتضاعفت المسافة بينهما لتصبح 2r مع بقاء m₂ ثابتة، فإن القوة الجديدة تساوي: (اختر الإجابة الصحيحة)
(أ) 0.75 F
(ب) 1.5 F
(ج) 3 F
(د) 12 F
الإجابة النموذجية: القوة الأصلية: F = G m₁ m₂ / r²

القوة الجديدة: F' = G (3m₁) m₂ / (2r)² = 3 G m₁ m₂ / (4r²) = (3/4) × [G m₁ m₂ / r²] = 0.75 F

إذن القوة الجديدة تساوي 0.75 من القوة الأصلية (أي تقل رغم زيادة إحدى الكتلتين، بسبب التأثير الأقوى لتربيع المسافة في المقام).

الإجابة الصحيحة: (أ).

[درس 2-1] سؤال تدريبي: عرّف شدة مجال الجاذبية (g) عند نقطة في الفضاء، واكتب العلاقة بينها وبين القوة المؤثرة على جسم صغير الكتلة موضوع في تلك النقطة.
الإجابة النموذجية: شدة مجال الجاذبية (g) عند نقطة تُعرَّف بأنها مقدار قوة الجاذبية المؤثرة لكل وحدة كتلة على جسم صغير (كتلة اختبار) يوضع عند تلك النقطة، دون أن يؤثر هذا الجسم بدوره تأثيرًا محسوسًا على المجال الأصلي.

رياضيًا: g = F / m

حيث F مقدار القوة المؤثرة على الجسم (بالنيوتن)، و m كتلة الجسم الاختباري (بالكيلوجرام)، ووحدة g هي N kg⁻¹ (وهي مكافئة لوحدة التسارع m s⁻²).

g كمية متجهة، واتجاهها هو اتجاه القوة، أي نحو مركز الجسم المسبب للمجال دائمًا.

[درس 2-1] سؤال تدريبي: كوكب المريخ كتلته 6.42×10²³ kg ونصف قطره 3.39×10⁶ m. احسب شدة مجال الجاذبية عند سطح المريخ.
الإجابة النموذجية: g = G M / R²

GM = 6.67×10⁻¹¹ × 6.42×10²³ = 4.282×10¹³

R² = (3.39×10⁶)² = 1.149×10¹³ m²

g = 4.282×10¹³ / 1.149×10¹³ = 3.73 m s⁻²

إذن شدة مجال الجاذبية عند سطح المريخ تساوي تقريبًا 3.73 N kg⁻¹ (أو m s⁻²)، وهي أقل من قيمتها عند سطح الأرض (9.81 m s⁻²) بسبب صغر كتلة المريخ مقارنة بالأرض.

[درس 2-1] سؤال تدريبي: رائد فضاء كتلته 75 kg هبط على سطح المريخ حيث شدة مجال الجاذبية هناك تساوي 3.7 N kg⁻¹. احسب وزن رائد الفضاء على سطح المريخ.
الإجابة النموذجية: الوزن يُحسب من العلاقة: W = m g

W = 75 × 3.7 = 277.5 N

إذن وزن رائد الفضاء على سطح المريخ يساوي تقريبًا 2.8×10² N (280 N)، وهو أقل بكثير من وزنه على سطح الأرض (الذي يساوي تقريبًا 75×9.81 ≈ 736 N) رغم أن كتلته لم تتغير، لأن الكتلة كمية ثابتة بينما الوزن يعتمد على شدة مجال الجاذبية في الموقع.

[درس 2-1] سؤال تدريبي: قمر تابع لأحد الكواكب كتلته 7.35×10²² kg، وشدة مجال الجاذبية عند سطحه 1.6 N kg⁻¹. حدد نصف قطر هذا القمر.
الإجابة النموذجية: من العلاقة g = GM/R²، يمكن إعادة ترتيبها لإيجاد R²: R² = GM / g

GM = 6.67×10⁻¹¹ × 7.35×10²² = 4.902×10¹²

R² = 4.902×10¹² / 1.6 = 3.064×10¹²

R = √(3.064×10¹²) = 1.75×10⁶ m

إذن نصف قطر هذا القمر يساوي تقريبًا 1.75×10⁶ m (1750 km).

[درس 2-1] سؤال تدريبي: كوكب X له نفس كتلة الأرض تمامًا، لكن نصف قطره يساوي نصف نصف قطر الأرض فقط. إذا كانت شدة مجال الجاذبية عند سطح الأرض تساوي 9.81 N kg⁻¹، فإن شدة مجال الجاذبية عند سطح الكوكب X تساوي: (اختر الإجابة الصحيحة)
(أ) 2.45 N kg⁻¹
(ب) 4.91 N kg⁻¹
(ج) 19.6 N kg⁻¹
(د) 39.2 N kg⁻¹
الإجابة النموذجية: g = GM/R²، وبما أن الكتلة M ثابتة (نفس كتلة الأرض) بينما R_X = R_الأرض/2:

g_X = GM/(R_الأرض/2)² = GM/(R_الأرض²/4) = 4 × (GM/R_الأرض²) = 4 g_الأرض

g_X = 4 × 9.81 = 39.24 N kg⁻¹ ≈ 39.2 N kg⁻¹

إذن شدة المجال عند سطح الكوكب X أكبر أربع مرات منها عند سطح الأرض، بسبب صغر نصف القطر (زيادة القرب من مركز الكتلة) رغم تساوي الكتلتين.

الإجابة الصحيحة: (د).

[درس 2-1] سؤال تدريبي: احسب شدة مجال الجاذبية على ارتفاع 3200 km فوق سطح الأرض. (كتلة الأرض M = 5.97×10²⁴ kg، نصف قطر الأرض R = 6400 km)
الإجابة النموذجية: يجب أولًا حساب المسافة الكلية r من مركز الأرض: r = R + h = 6400 + 3200 = 9600 km = 9.6×10⁶ m

g = GM/r²

GM = 6.67×10⁻¹¹ × 5.97×10²⁴ = 3.982×10¹⁴

r² = (9.6×10⁶)² = 9.216×10¹³ m²

g = 3.982×10¹⁴ / 9.216×10¹³ = 4.32 m s⁻²

إذن شدة مجال الجاذبية على هذا الارتفاع تساوي تقريبًا 4.32 N kg⁻¹، وهي أقل من قيمتها عند سطح الأرض (9.81 N kg⁻¹) لأن r زادت (ابتعدنا عن مركز الأرض) وg تتناسب عكسيًا مع مربع r.

[درس 3-1] سؤال تدريبي: عرّف جهد الجاذبية (φ) عند نقطة في مجال جاذبية جسم كتلته M، واكتب العلاقة الرياضية له بدلالة الثابت G والمسافة r عن مركز الجسم.
الإجابة النموذجية: جهد الجاذبية (φ) عند نقطة ما يُعرَّف بأنه الشغل المبذول لكل وحدة كتلة لنقل كتلة نقطية صغيرة من اللانهاية (حيث φ = 0) إلى تلك النقطة.

φ = W / m

وبما أن قوة الجاذبية قوة تجاذب، فإن φ = −GM/r

حيث G ثابت الجذب العام، M كتلة الجسم المسبب للمجال، r المسافة من مركز ذلك الجسم إلى النقطة المعنية.

وحدة φ هي J kg⁻¹، وإشارتها سالبة دائمًا (باستثناء عند اللانهاية حيث تساوي صفرًا) لأن الشغل المبذول من قِبل قوة الجذب أثناء تقريب الكتلة من اللانهاية موجب، بينما جهد الجاذبية يُعرَّف بحيث يكون أعلى قيمة له (صفر) عند اللانهاية ويقل (يصبح أكثر سالبية) كلما اقتربنا من الجسم.

[درس 3-1] سؤال تدريبي: قمر صناعي كتلته 800 kg يدور حول الأرض على مسافة 7.2×10⁶ m من مركزها. احسب طاقة وضع الجاذبية لهذا القمر الصناعي. (كتلة الأرض M = 5.97×10²⁴ kg)
الإجابة النموذجية: Ep = − G M m / r

GM = 6.67×10⁻¹¹ × 5.97×10²⁴ = 3.982×10¹⁴

GMm = 3.982×10¹⁴ × 800 = 3.186×10¹⁷

Ep = − 3.186×10¹⁷ / 7.2×10⁶ = − 4.42×10¹⁰ J

إذن طاقة وضع الجاذبية للقمر الصناعي تساوي تقريبًا −4.42×10¹⁰ J. الإشارة السالبة تدل على أن القمر الصناعي في حالة ارتباط (مقيد) بمجال جاذبية الأرض، وأن طاقته أقل من طاقته عند اللانهاية (التي تساوي صفرًا).

[درس 3-1] سؤال تدريبي: ينتقل جسم كتلته 500 kg من نقطة تبعد 8.0×10⁶ m عن مركز الأرض إلى نقطة أخرى تبعد 1.2×10⁷ m عن مركز الأرض. احسب التغيّر في طاقة وضع الجاذبية للجسم. (كتلة الأرض M = 5.97×10²⁴ kg)
الإجابة النموذجية: GM = 6.67×10⁻¹¹ × 5.97×10²⁴ = 3.982×10¹⁴

GMm = 3.982×10¹⁴ × 500 = 1.991×10¹⁷

طاقة الوضع عند النقطة الأولى: Ep₁ = −1.991×10¹⁷ / 8.0×10⁶ = −2.489×10¹⁰ J

طاقة الوضع عند النقطة الثانية: Ep₂ = −1.991×10¹⁷ / 1.2×10⁷ = −1.659×10¹⁰ J

ΔEp = Ep₂ − Ep₁ = (−1.659×10¹⁰) − (−2.489×10¹⁰) = +8.30×10⁹ J

إذن طاقة وضع الجاذبية للجسم ازدادت بمقدار 8.30×10⁹ J (إشارة موجبة)، وهذا متوقع لأن الجسم ابتعد عن مركز الأرض، فيلزم بذل شغل موجب (من مصدر خارجي) ضد قوة الجذب لرفعه إلى مسافة أبعد.

[درس 3-1] سؤال تدريبي: فسّر لماذا تكون طاقة وضع الجاذبية لجسمين متجاذبين سالبة الإشارة دائمًا (باستثناء عند اللانهاية)، وبيّن ماذا يعني ازدياد قيمتها الجبرية (اقترابها من الصفر) عندما يبتعد الجسم عن مركز الجسم المسبب للمجال.
الإجابة النموذجية: يُختار الصفر المرجعي لطاقة وضع الجاذبية عند اللانهاية (حيث لا يوجد تأثير متبادل بين الجسمين). بما أن قوة الجاذبية قوة تجاذب، فإن تقريب جسم من اللانهاية نحو جسم آخر يجعل قوة الجذب تبذل شغلاً موجبًا على الجسم المتحرك، وهذا يعني أن طاقة الوضع تقل (تصبح أصغر من صفر، أي سالبة) كلما اقترب الجسمان من بعضهما.

لذلك فإن Ep = −GMm/r سالبة الإشارة عند أي مسافة منتهية r، وتقترب من الصفر (قيمتها الجبرية تزداد) فقط عندما تزداد r، أي كلما ابتعد الجسم عن مركز الجاذبية.

فيزيائيًا، هذا يعني أن الجسمين أكثر 'ارتباطًا' (bound) كلما كانت طاقة الوضع أكثر سلبية، ويحتاج فصلهما تمامًا (نقل الجسم إلى اللانهاية) إلى بذل شغل موجب من مصدر خارجي يساوي مقدار |Ep| الابتدائية.

[درس 3-1] سؤال تدريبي: جسمان كتلتاهما m₁ = 200 kg و m₂ = 600 kg يبعدان مسافة متساوية r = 5.0×10⁶ m عن مركز كوكب كتلته M = 4.0×10²⁴ kg. قارن كميًّا بين طاقتي وضع الجاذبية للجسمين.
الإجابة النموذجية: GM = 6.67×10⁻¹¹ × 4.0×10²⁴ = 2.668×10¹⁴

Ep₁ = −GMm₁/r = −(2.668×10¹⁴ × 200) / 5.0×10⁶ = −5.336×10¹⁶ / 5.0×10⁶ = −1.07×10¹⁰ J

Ep₂ = −GMm₂/r = −(2.668×10¹⁴ × 600) / 5.0×10⁶ = −1.601×10¹⁷ / 5.0×10⁶ = −3.20×10¹⁰ J

بما أن Ep تتناسب طرديًا مع الكتلة m عند ثبوت r و M، نجد أن Ep₂ / Ep₁ = 3، وهو نفس مقدار النسبة بين الكتلتين (m₂/m₁ = 3).

إذن طاقة وضع الجاذبية للجسم الثاني (m₂) أكبر مقدارًا (أكثر سالبية) بثلاث مرات من طاقة وضع الجاذبية للجسم الأول (m₁)، أي Ep₂ أصغر جبريًا (أكثر سالبية) من Ep₁.

[درس 3-1] سؤال تدريبي: عند رسم منحنى جهد الجاذبية φ بدلالة المسافة r من مركز كوكب (لقيم r خارج سطح الكوكب)، أي العبارات التالية تصف المنحنى بشكل صحيح؟ (اختر الإجابة الصحيحة)
(أ) φ سالبة دائمًا، وتزداد سالبيتها (تبتعد عن الصفر) كلما زادت r
(ب) φ سالبة دائمًا، وتقترب تدريجيًا من الصفر كلما زادت r، دون أن تصبح موجبة
(ج) φ موجبة دائمًا، وتتناقص قيمتها كلما زادت r
(د) φ لا تعتمد على r، بل تعتمد فقط على كتلة الكوكب M
الإجابة النموذجية: φ = −GM/r. بما أن G و M ثابتان وموجبان، فإن φ سالبة الإشارة عند كل قيم r المنتهية (لأن −GM سالبة ونقسمها على r الموجبة).

كلما زادت r (ابتعدنا عن مركز الكوكب)، يقل مقدار GM/r (لأن r في المقام)، وبالتالي تقترب φ (وهي سالبة) تدريجيًا من الصفر، لكنها لا تصل إلى الصفر إلا عند r = ∞ ولا تصبح موجبة أبدًا.

منحنى φ مقابل r يبدأ بقيمة سالبة كبيرة المقدار عند أصغر r (قرب السطح)، ثم يرتفع (يقترب من الصفر) بشكل تدريجي متناقص المعدل كلما زادت r.

الإجابة الصحيحة: (ب).

[درس 4-1] سؤال تدريبي: اشتقّ العلاقة بين السرعة المدارية v لجسم يدور في مدار دائري حول كوكب كتلته M ونصف قطر مداره r، وذلك بالمساواة بين قوة الجاذبية المؤثرة عليه والقوة المركزية اللازمة لحركته الدائرية.
الإجابة النموذجية: يدور الجسم (كتلته m) في مدار دائري نصف قطره r حول جسم مركزي كتلته M بسرعة مدارية v. القوة التي توفر القوة المركزية اللازمة لهذه الحركة الدائرية هي قوة الجاذبية بين الجسمين.

بمساواة قوة الجاذبية بالقوة المركزية:

G M m / r² = m v² / r

بقسمة الطرفين على m (الكتلة m تُختصر من المعادلة تمامًا)، ثم ضرب الطرفين في r:

G M / r = v²

وبأخذ الجذر التربيعي للطرفين:

v = √(GM/r)

هذه هي العلاقة المطلوبة بين السرعة المدارية ونصف قطر المدار، وتُظهر أن كتلة الجسم المداري m لا تظهر في الصيغة النهائية على الإطلاق.

[درس 4-1] سؤال تدريبي: قمر صناعي يدور حول الأرض في مدار دائري نصف قطره 7.00×10⁶ m. احسب سرعته المدارية. (كتلة الأرض M = 5.97×10²⁴ kg)
الإجابة النموذجية: v = √(GM/r)

GM = 6.67×10⁻¹¹ × 5.97×10²⁴ = 3.982×10¹⁴

GM/r = 3.982×10¹⁴ / 7.00×10⁶ = 5.689×10⁷

v = √(5.689×10⁷) = 7.54×10³ m s⁻¹

إذن السرعة المدارية لهذا القمر الصناعي تساوي تقريبًا 7.54×10³ m s⁻¹ (نحو 27 200 km/h).

[درس 4-1] سؤال تدريبي: قمر صناعي يدور حول الأرض في مدار دائري بزمن دوري T = 7200 s. حدد نصف قطر مداره، ثم احسب ارتفاعه عن سطح الأرض. (كتلة الأرض M = 5.97×10²⁴ kg، نصف قطر الأرض R = 6.40×10⁶ m)
الإجابة النموذجية: وفق قانون كبلر الثالث: T² = 4π² r³ / GM، ومنها: r³ = GM T² / 4π²

GM = 6.67×10⁻¹¹ × 5.97×10²⁴ = 3.982×10¹⁴

T² = (7200)² = 5.184×10⁷ s²

GM T² = 3.982×10¹⁴ × 5.184×10⁷ = 2.064×10²²

4π² ≈ 39.48

r³ = 2.064×10²² / 39.48 = 5.23×10²⁰ m³

r = (5.23×10²⁰)^(1/3) ≈ 8.06×10⁶ m

الارتفاع عن سطح الأرض: h = r − R = 8.06×10⁶ − 6.40×10⁶ = 1.66×10⁶ m

إذن نصف قطر المدار يساوي تقريبًا 8.06×10⁶ m، ويقابل ذلك ارتفاعًا عن سطح الأرض يساوي تقريبًا 1.66×10⁶ m (نحو 1660 km).

[درس 4-1] سؤال تدريبي: فسّر لماذا لا تعتمد كل من السرعة المدارية والزمن الدوري لقمر صناعي يدور حول الأرض على كتلة القمر الصناعي نفسه، بل تعتمدان فقط على كتلة الأرض ونصف قطر المدار.
الإجابة النموذجية: عند اشتقاق كل من v = √(GM/r) و T² = 4π²r³/GM، نبدأ بمساواة قوة الجاذبية (وهي G M m / r²، حيث m كتلة القمر الصناعي) بالقوة المركزية اللازمة للحركة الدائرية (وهي m v²/r، أو ما يعادلها بدلالة T).

في كلتا الحالتين تظهر كتلة القمر الصناعي m في الطرفين (طرف قوة الجاذبية وطرف القوة المركزية) بنفس القوة، وبالتالي تُختصر m تمامًا من المعادلة عند القسمة عليها.

النتيجة النهائية (سواء v أو T) تعتمد فقط على الكتلة المركزية M (كتلة الأرض، وهي مصدر المجال) وعلى نصف قطر المدار r، ولا تحتوي على m إطلاقًا. لذلك فإن أي قمر صناعي (مهما كانت كتلته: صغيرًا أو كبيرًا) يدور على نفس نصف القطر r حول الأرض سيكون له نفس السرعة المدارية ونفس الزمن الدوري بالضبط.

[درس 4-1] سؤال تدريبي: فسّر معنى مصطلح 'القمر الصناعي المتزامن مع الأرض' (Geostationary Satellite)، واذكر الشروط اللازم توفرها في مداره حتى يبقى هذا القمر الصناعي فوق نقطة ثابتة من سطح الأرض باستمرار.
الإجابة النموذجية: القمر الصناعي المتزامن مع الأرض هو قمر صناعي يبدو ثابتًا بالنسبة لمراقب على سطح الأرض، أي أنه يظل معلقًا فوق نفس النقطة على خط الاستواء طوال الوقت.

لتحقيق ذلك، يجب توفر الشروط التالية في مداره:

(1) أن يكون زمنه الدوري مساويًا تمامًا للزمن الدوري لدوران الأرض حول محورها (اليوم النجمي ≈ 24 ساعة)، بحيث يكمل القمر الصناعي دورة كاملة حول الأرض في نفس الوقت الذي تكمل فيه الأرض دورة كاملة حول محورها.

(2) أن يكون مداره دائريًا وواقعًا بالكامل في مستوى خط استواء الأرض (لا يميل عنه).

(3) أن تكون جهة دورانه حول الأرض هي نفس جهة دوران الأرض حول محورها (من الغرب إلى الشرق).

عند توفر هذه الشروط الثلاثة معًا، تبقى المسافة الزاوية بين القمر الصناعي ونقطة ثابتة على خط الاستواء صفرًا دائمًا، فيبدو القمر الصناعي ساكنًا في السماء بالنسبة لمراقب أرضي.

[درس 4-1] سؤال تدريبي: احسب نصف قطر مدار القمر الصناعي المتزامن مع الأرض، علمًا بأن زمنه الدوري يساوي الزمن الدوري لدوران الأرض حول محورها T = 24 h = 86400 s. (كتلة الأرض M = 5.97×10²⁴ kg، نصف قطر الأرض R = 6.40×10⁶ m)، ثم احسب ارتفاع هذا المدار عن سطح الأرض.
الإجابة النموذجية: من قانون كبلر الثالث: r³ = GM T² / 4π²

GM = 6.67×10⁻¹¹ × 5.97×10²⁴ = 3.982×10¹⁴

T² = (86400)² = 7.465×10⁹ s²

GM T² = 3.982×10¹⁴ × 7.465×10⁹ = 2.973×10²⁴

4π² ≈ 39.48

r³ = 2.973×10²⁴ / 39.48 = 7.53×10²² m³

r = (7.53×10²²)^(1/3) ≈ 4.22×10⁷ m

الارتفاع عن سطح الأرض: h = r − R = 4.22×10⁷ − 6.40×10⁶ = 3.58×10⁷ m

إذن نصف قطر مدار القمر الصناعي المتزامن مع الأرض يساوي تقريبًا 4.22×10⁷ m (42 200 km من مركز الأرض)، أي على ارتفاع 3.58×10⁷ m (نحو 35 800 km) فوق سطح الأرض، وهذه هي القيمة الحقيقية المعروفة تقريبًا لمدار الأقمار الصناعية الجيوستاسيونية.

[درس 1-2] سؤال تدريبي: صف نمط خطوط المجال الكهربائي الناشئة عن شحنة نقطية موجبة منفردة موضوعة في الفراغ، مبيّنًا كيف يتغيّر تباعد هذه الخطوط كلما ابتعدنا عن الشحنة، وما الذي يدل عليه هذا التباعد بخصوص مقدار شدة المجال.
الإجابة النموذجية: خطوط المجال الكهربائي الناشئة عن شحنة نقطية موجبة منفردة تكون خطوطًا مستقيمة تخرج شعاعيًا من الشحنة في جميع الاتجاهات (إلى الخارج)، لأن اتجاه المجال عند أي نقطة هو اتجاه القوة التي تؤثر بها الشحنة على شحنة اختبار موجبة موضوعة عند تلك النقطة، وهذه القوة تنافرية فتدفع الشحنة الموجبة بعيدًا عن مصدر المجال.

كلما ابتعدنا عن الشحنة يزداد التباعد بين الخطوط (أي تقل كثافتها لكل وحدة مساحة)، لأن نفس عدد الخطوط الخارجة من الشحنة يتوزع على مساحة سطح كروي أكبر (∝ r²) كلما زادت المسافة r.

وبما أن كثافة خطوط المجال عند نقطة معينة تمثل مقياسًا لشدة المجال هناك، فإن ازدياد التباعد بين الخطوط بعيدًا عن الشحنة يدل على أن شدة المجال الكهربائي تقل كلما زادت المسافة عن الشحنة، وهذا يتوافق مع العلاقة E = Q/(4πε₀r²) التي تبيّن أن E تتناسب عكسيًا مع مربع المسافة.

[درس 1-2] سؤال تدريبي: يُظهر أحد الأشكال التوضيحية خطوط مجال كهربائي بين نقطتين A وB، حيث تخرج جميع الخطوط من النقطة A وتدخل جميعها في النقطة B دون أن تتقاطع، مع ملاحظة أن كثافة الخطوط عند A أكبر بوضوح من كثافتها عند B. أي العبارات التالية صحيحة؟ (اختر الإجابة الصحيحة)
(أ) الشحنة عند A سالبة والشحنة عند B موجبة، ومقدارهما متساويان.
(ب) الشحنة عند A موجبة والشحنة عند B سالبة، ومقدار الشحنة عند A أكبر من مقدار الشحنة عند B.
(ج) الشحنتان عند A وB كلتاهما موجبتان.
(د) الشحنتان عند A وB كلتاهما سالبتان.
الإجابة النموذجية: خطوط المجال الكهربائي تخرج دائمًا من الشحنات الموجبة وتدخل في الشحنات السالبة. بما أن الخطوط تخرج من A فإن شحنة A موجبة، وبما أنها تدخل في B فإن شحنة B سالبة، وهذا يستبعد الخيارين (ج) و(د) مباشرة.

كما أن كثافة خطوط المجال عند شحنة معينة تتناسب مع مقدار تلك الشحنة (عدد الخطوط الخارجة أو الداخلة يتناسب مع |Q|)؛ وبما أن الكثافة عند A أكبر من كثافتها عند B، فإن مقدار الشحنة عند A أكبر من مقدار الشحنة عند B، وهذا يستبعد الخيار (أ) الذي يفترض تساوي المقدارين.

إذن الإجابة الصحيحة هي (ب): الشحنة عند A موجبة وأكبر مقدارًا من الشحنة السالبة عند B.

[درس 1-2] سؤال تدريبي: فسّر لماذا لا يمكن لخطي مجال كهربائي أن يتقاطعا عند أي نقطة في الفضاء المحيط بشحنة أو أكثر (باستثناء النقطة التي توجد بها الشحنة نفسها).
الإجابة النموذجية: اتجاه خط المجال الكهربائي عند أي نقطة يمثّل اتجاه المجال الكهربائي المحصّل عند تلك النقطة، والمجال الكهربائي عند نقطة معينة في الفضاء له اتجاه واحد ومحدد فقط (هو محصلة جميع الشحنات المؤثرة، وهي محصلة فريدة لا تتعدد قيمها).

لو تقاطع خطا مجال عند نقطة ما، لكان لهذه النقطة اتجاهان مختلفان للمجال الكهربائي في الوقت نفسه (اتجاه كل خط من الخطين)، وهذا يتناقض مع كون المجال عند أي نقطة له اتجاه واحد فقط.

لذلك فإن خطوط المجال الكهربائي لا تتقاطع أبدًا؛ فهذا يضمن أن كل نقطة في الفضاء (عدا موضع الشحنة نفسها حيث يكون المجال غير معرّف) يمرّ بها خط مجال واحد فقط يمثل الاتجاه الحقيقي والوحيد للمجال هناك.

[درس 1-2] سؤال تدريبي: قارن بين نمط خطوط المجال الكهربائي الناشئ بين شحنتين نقطيتين متساويتين في المقدار ومختلفتين في النوع (موجبة وسالبة متجاورتين)، ونمط خطوطه الناشئ بين شحنتين نقطيتين متساويتين في المقدار ومتشابهتين في النوع (موجبتين متجاورتين).
الإجابة النموذجية: في حالة الشحنتين المختلفتين في النوع (موجبة وسالبة): تخرج خطوط المجال من الشحنة الموجبة وتنحني لتدخل مباشرة في الشحنة السالبة المجاورة لها، فتكون الخطوط منحنية بين الشحنتين وتصل كل خطوط الشحنة الموجبة إلى الشحنة السالبة دون وجود أي نقطة يكون عندها المجال المحصل صفرًا على الخط الواصل بينهما؛ ويكون المجال على امتداد المستقيم الواصل بين الشحنتين موجهًا دائمًا من الموجبة نحو السالبة.

في حالة الشحنتين المتشابهتين في النوع (موجبتين): تخرج الخطوط من كلتا الشحنتين وتتنافر خطوط إحداهما مع خطوط الأخرى فتنحني بعيدًا عنها بدلًا من أن تتصل بها، ولا يوجد أي خط يصل مباشرة بين الشحنتين. ويوجد على الخط الواصل بينهما نقطة عند منتصف المسافة (بسبب تماثل الشحنتين) يكون عندها المجال الكهربائي المحصل مساويًا للصفر، لأن مساهمتي الشحنتين متساويتان في المقدار ومتعاكستان في الاتجاه عند تلك النقطة.

إذن الفرق الجوهري: خطوط الشحنتين المختلفتين تتصل مباشرة بينهما بلا نقطة صفر بينهما، بينما خطوط الشحنتين المتشابهتين تتنافر ولا تتصل، ويظهر بينهما نقطة مجال صفري.

[درس 1-2] سؤال تدريبي: أثناء عاصفة رعدية، تحمل قاعدة السحابة شحنة سالبة كلية، بينما يُستحث على سطح الأرض وقمة أي مبنى مرتفع تحتها شحنة موجبة. اقترح اتجاه خطوط المجال الكهربائي بين قمة مبنى مرتفع وقاعدة السحابة فوقه، وفسّر لماذا يزداد خطر وقوع الصواعق عند القمم الحادة والمرتفعة للمباني مقارنة بالأسطح المسطحة المنخفضة.
الإجابة النموذجية: بما أن خطوط المجال الكهربائي تخرج من الشحنة الموجبة وتدخل في الشحنة السالبة، وقمة المبنى مشحونة بشحنة موجبة مستحثة بينما قاعدة السحابة مشحونة بشحنة سالبة، فإن خطوط المجال بينهما تكون موجهة من قمة المبنى صعودًا نحو قاعدة السحابة.

كثافة الشحنة المستحثة (وبالتالي كثافة خطوط المجال وشدته) تكون أكبر ما يمكن عند النقاط الحادة والمدببة (مثل قمم الأبراج والمباني المرتفعة) مقارنة بالأسطح المسطحة الواسعة، لأن الشحنة تتركز عند مناطق انحناء السطح الأكبر (نصف القطر الأصغر).

ولأن شدة المجال الكهربائي عند القمم الحادة تصبح كبيرة جدًا ومركزة في منطقة صغيرة، فقد تتجاوز شدة المجال هناك القيمة الحرجة اللازمة لتأيّن الهواء المحيط (انهيار العزل الكهربائي للهواء)، مما يجعل هذه القمم أكثر عرضة لبدء مسار تفريغ كهربائي (صاعقة) بينها وبين السحابة مقارنة بالأسطح المنخفضة التي يكون المجال عندها أضعف وأكثر انتشارًا.

[درس 2-2] سؤال تدريبي: عرّف شدة المجال الكهربائي (E) عند نقطة في الفضاء، مبيّنًا العلاقة الرياضية التي تحدد هذا التعريف، ووحدتها في النظام الدولي.
الإجابة النموذجية: شدة المجال الكهربائي عند نقطة معينة تُعرَّف بأنها القوة الكهربائية المؤثرة على وحدة الشحنات الموجبة الموضوعة عند تلك النقطة.

رياضيًا: E = F/Q، حيث F هي القوة الكهربائية المؤثرة على شحنة اختبار موجبة صغيرة مقدارها Q موضوعة عند النقطة المطلوبة.

ووحدة شدة المجال الكهربائي في النظام الدولي هي نيوتن لكل كولوم (N C⁻¹)، وهي تكافئ فولت لكل متر (V m⁻¹).

[درس 2-2] سؤال تدريبي: يفصل بين لوحين متوازيين في مكثف مستوٍ مسافة d = 5.0 cm، ويُطبَّق بينهما فرق جهد كهربائي V = 250 V. احسب شدة المجال الكهربائي المنتظم بين اللوحين.
الإجابة النموذجية: المعطيات: V = 250 V، d = 5.0 cm = 5.0×10⁻² m.

باستخدام العلاقة الخاصة بالمجال المنتظم بين لوحين متوازيين:
E = V/d = 250 / (5.0×10⁻²) = 5000 V/m

إذن شدة المجال الكهربائي المنتظم بين اللوحين تساوي E = 5.0×10³ V m⁻¹ (أو 5.0×10³ N C⁻¹).

[درس 2-2] سؤال تدريبي: مكثف ذو لوحين متوازيين يفصل بينهما 8.0 mm، ويُطبَّق بينهما فرق جهد كهربائي مقداره 400 V.
(a) احسب شدة المجال الكهربائي المنتظم بين اللوحين.
(b) احسب مقدار القوة الكهربائية المؤثرة على شحنة نقطية مقدارها 3.2×10⁻¹⁹ C موضوعة بين اللوحين.
الإجابة النموذجية: (a) المعطيات: V = 400 V، d = 8.0 mm = 8.0×10⁻³ m.
E = V/d = 400 / (8.0×10⁻³) = 5.0×10⁴ V/m

(b) باستخدام العلاقة F = EQ لحساب القوة على الشحنة Q = 3.2×10⁻¹⁹ C:
F = EQ = (5.0×10⁴) × (3.2×10⁻¹⁹) = 1.6×10⁻¹⁴ N

إذن شدة المجال E = 5.0×10⁴ V m⁻¹، والقوة المؤثرة على الشحنة F = 1.6×10⁻¹⁴ N.

[درس 2-2] سؤال تدريبي: يتحرك إلكترون داخل مجال كهربائي منتظم بين لوحين متوازيين أفقيين، حيث يكون اللوح العلوي موجب الشحنة واللوح السفلي سالب الشحنة (أي أن اتجاه المجال الكهربائي بين اللوحين هو من الأعلى إلى الأسفل). في أي اتجاه تؤثر القوة الكهربائية على الإلكترون؟ (اختر الإجابة الصحيحة)
(أ) إلى الأسفل، في نفس اتجاه المجال الكهربائي.
(ب) إلى الأعلى، في عكس اتجاه المجال الكهربائي.
(ج) أفقيًا، موازية لسطحي اللوحين.
(د) القوة معدومة لأن الإلكترون شحنته صغيرة جدًا.
الإجابة النموذجية: القوة الكهربائية على شحنة نقطية تُعطى بالعلاقة F = EQ، وهي علاقة اتجاهية: إذا كانت الشحنة موجبة فإن اتجاه القوة عليها يكون في نفس اتجاه المجال E، أما إذا كانت الشحنة سالبة (كما في حالة الإلكترون) فإن اتجاه القوة عليها يكون معاكسًا تمامًا لاتجاه المجال E.

بما أن المجال E موجّه من الأعلى إلى الأسفل (من اللوح الموجب إلى اللوح السالب)، وشحنة الإلكترون سالبة، فإن القوة الكهربائية المؤثرة عليه تكون في الاتجاه المعاكس، أي إلى الأعلى.

إذن الإجابة الصحيحة هي (ب).

[درس 2-2] سؤال تدريبي: مجال كهربائي منتظم بين لوحين متوازيين شدته E = 1.2×10⁴ V/m، تؤثر بقوة مقدارها 4.8×10⁻¹⁵ N على شحنة نقطية موضوعة بينهما.
(a) حدد مقدار هذه الشحنة.
(b) احسب فرق الجهد الكهربائي بين اللوحين إذا كانت المسافة الفاصلة بينهما 1.5 cm.
الإجابة النموذجية: (a) من العلاقة F = EQ نحصل على:
Q = F/E = (4.8×10⁻¹⁵) / (1.2×10⁴) = 4.0×10⁻¹⁹ C

(b) باستخدام العلاقة E = V/d، حيث d = 1.5 cm = 1.5×10⁻² m:
V = E × d = (1.2×10⁴) × (1.5×10⁻²) = 180 V

إذن مقدار الشحنة Q = 4.0×10⁻¹⁹ C (وهي تساوي تقريبًا 2.5 e، أي مقدار شحنة مضاعف تقريبًا لشحنة الإلكترون الأساسية)، وفرق الجهد بين اللوحين V = 180 V.

[درس 2-2] سؤال تدريبي: يدخل إلكترون منطقة المجال الكهربائي المنتظم بين لوحين متوازيين رأسيين بسرعة أفقية ثابتة عند نقطة منتصف المسافة بين اللوحين. صف مسار حركة هذا الإلكترون من لحظة دخوله بين اللوحين حتى خروجه منهما.
الإجابة النموذجية: أثناء وجود الإلكترون بين اللوحين، تؤثر عليه قوة كهربائية ثابتة المقدار والاتجاه (لأن المجال بينهما منتظم)، وهذه القوة عمودية على اتجاه سرعته الأفقية الأولية (أي أنها موجهة نحو أحد اللوحين).

بما أن السرعة الأفقية للإلكترون لا تتأثر بهذه القوة العمودية عليها، فإنها تبقى ثابتة طوال الحركة بين اللوحين، بينما تكسبه القوة الكهربائية تسارعًا ثابتًا في الاتجاه العمودي (نحو اللوح الموجب، لأن شحنته سالبة)، فتزداد سرعته العمودية بانتظام مع الزمن.

ونتيجة لذلك يتحرك الإلكترون في مسار منحنٍ على شكل قطع مكافئ (parabola)، تمامًا كحركة مقذوف أفقي تحت تأثير الجاذبية الأرضية الثابتة؛ حيث يقابل التسارع الثابت نحو أحد اللوحين هنا دور تسارع الجاذبية g في حركة المقذوفات. وينحرف الإلكترون تدريجيًا نحو اللوح الموجب حتى يخرج من بين اللوحين (أو يصطدم بأحدهما إذا كانت المسافة أو زمن العبور كافيين).

[درس 3-2] سؤال تدريبي: يفصل بين لوحين متوازيين مسافة d = 4.0 cm، ويُطبَّق بينهما فرق جهد كهربائي V = 600 V. احسب مقدار القوة الكهربائية المؤثرة على إلكترون موضوع بين اللوحين، باستخدام العلاقة F = eV/d.
الإجابة النموذجية: المعطيات: V = 600 V، d = 4.0 cm = 4.0×10⁻² m، e = 1.6×10⁻¹⁹ C.

F = eV/d = (1.6×10⁻¹⁹ × 600) / (4.0×10⁻²)

نحسب البسط أولًا: 1.6×10⁻¹⁹ × 600 = 9.6×10⁻¹⁷

ثم نقسم على المقام: F = (9.6×10⁻¹⁷) / (4.0×10⁻²) = 2.4×10⁻¹⁵ N

إذن مقدار القوة الكهربائية المؤثرة على الإلكترون F = 2.4×10⁻¹⁵ N.

[درس 3-2] سؤال تدريبي: يوضع بروتون وإلكترون في اللحظة نفسها عند النقطة نفسها بين لوحين متوازيين، حيث يكون اللوح العلوي موجب الشحنة والسفلي سالب الشحنة. صف اتجاه القوة الكهربائية المؤثرة على كل من البروتون والإلكترون، وفسّر السبب.
الإجابة النموذجية: اتجاه المجال الكهربائي المنتظم بين اللوحين يكون من اللوح الموجب (العلوي) إلى اللوح السالب (السفلي)، أي أن E موجّه إلى الأسفل.

القوة الكهربائية المؤثرة على أي شحنة تُعطى بالعلاقة F = QE، وإشارة الشحنة Q هي التي تحدد اتجاه القوة بالنسبة لاتجاه المجال: فإذا كانت Q موجبة تكون القوة في نفس اتجاه E، وإذا كانت Q سالبة تكون القوة معاكسة تمامًا لاتجاه E.

البروتون شحنته موجبة (+e)، لذا فإن القوة المؤثرة عليه تكون في نفس اتجاه المجال، أي إلى الأسفل (نحو اللوح السالب).

الإلكترون شحنته سالبة (−e)، لذا فإن القوة المؤثرة عليه تكون معاكسة لاتجاه المجال، أي إلى الأعلى (نحو اللوح الموجب).

وبما أن مقدار شحنة كل منهما متساوٍ (e نفسها)، فإن مقدار القوة المؤثرة على كليهما متساوٍ أيضًا (F = eE)، والفرق بينهما هو الاتجاه فقط.

[درس 3-2] سؤال تدريبي: مكثف ذو لوحين متوازيين متصل بمصدر جهد كهربائي ثابت V. إذا قُرِّب اللوحان من بعضهما بحيث أصبحت المسافة بينهما نصف قيمتها الأصلية، مع بقاء فرق الجهد V ثابتًا، بيّن أثر ذلك على: (a) شدة المجال الكهربائي المنتظم بين اللوحين. (b) مقدار القوة المؤثرة على شحنة ثابتة Q موضوعة بين اللوحين. اذكر في كل حالة النسبة بين القيمة الجديدة والقيمة الأصلية.
الإجابة النموذجية: (a) شدة المجال بين لوحين متوازيين تُعطى بالعلاقة E = V/d. بما أن V ثابت والمسافة الجديدة d' = d/2:
E' = V/d' = V/(d/2) = 2V/d = 2E

إذن شدة المجال الجديدة تساوي ضعف شدة المجال الأصلية (النسبة = 2).

(b) القوة على الشحنة الثابتة Q تُعطى بالعلاقة F = EQ. بما أن Q ثابتة وE تضاعفت:
F' = E'Q = 2EQ = 2F

إذن القوة الجديدة تساوي ضعف القوة الأصلية أيضًا (النسبة = 2)، لأن تقريب اللوحين مع ثبات فرق الجهد يزيد شدة المجال (E = V/d)، وبالتالي تزداد القوة (F = EQ) بنفس النسبة.

[درس 3-2] سؤال تدريبي: لوحان متوازيان بينهما فرق جهد ثابت V ومسافة d، تُوضع بينهما شحنة نقطية Q فتتأثر بقوة كهربائية مقدارها F. إذا زادت المسافة بين اللوحين إلى الضعف (2d) مع بقاء فرق الجهد V ثابتًا وبقاء الشحنة Q كما هي، فإن القوة الجديدة المؤثرة على الشحنة تساوي: (اختر الإجابة الصحيحة)
(أ) 4F
(ب) 2F
(ج) F/2
(د) F/4
الإجابة النموذجية: شدة المجال بين اللوحين: E = V/d، والقوة على الشحنة: F = EQ = (V/d)Q = VQ/d.

بما أن V وQ ثابتان، فإن F تتناسب عكسيًا طرديًا مع d فقط: F ∝ 1/d.

عندما تتضاعف المسافة إلى d' = 2d:
F' = VQ/d' = VQ/(2d) = (1/2)(VQ/d) = F/2

إذن القوة الجديدة تساوي نصف القوة الأصلية، والإجابة الصحيحة هي (ج) F/2.

[درس 3-2] سؤال تدريبي: أثناء عاصفة رعدية، ينشأ بين قاعدة السحابة وسطح الأرض تحتها مجال كهربائي شبه منتظم شدته 1.5×10⁴ V/m موجّه نحو سطح الأرض. تحمل قطرة مطر داخل هذا المجال شحنة سالبة مقدارها 2.0×10⁻¹⁴ C اكتسبتها بسبب الاحتكاك بالهواء. احسب مقدار القوة الكهربائية المؤثرة على قطرة المطر، وصف اتجاهها بالنسبة لاتجاه المجال.
الإجابة النموذجية: المعطيات: E = 1.5×10⁴ V/m، Q = 2.0×10⁻¹⁴ C (سالبة).

مقدار القوة: F = EQ = (1.5×10⁴) × (2.0×10⁻¹⁴) = 3.0×10⁻¹⁰ N

بما أن شحنة قطرة المطر سالبة، فإن اتجاه القوة الكهربائية عليها يكون معاكسًا لاتجاه المجال الكهربائي؛ وبما أن المجال موجّه نحو سطح الأرض (إلى الأسفل)، فإن القوة الكهربائية على القطرة تكون موجهة إلى الأعلى (بعيدًا عن الأرض، نحو السحابة)، أي أنها تعمل على معاكسة سقوط القطرة الناتج عن الجاذبية الأرضية.

إذن مقدار القوة F = 3.0×10⁻¹⁰ N، واتجاهها إلى الأعلى نحو السحابة.

[درس 4-2] سؤال تدريبي: انص على قانون كولوم للقوة الكهربائية بين شحنتين نقطيتين، مبينًا صيغته الرياضية. ثم احسب مقدار القوة الكهربائية بين شحنتين نقطيتين Q₁ = +3.0×10⁻⁶ C وQ₂ = −2.0×10⁻⁶ C، تفصل بينهما مسافة 0.30 m في الفراغ، مبينًا نوع هذه القوة (تجاذب أم تنافر).
الإجابة النموذجية: ينص قانون كولوم على أن القوة الكهربائية المتبادلة بين شحنتين نقطيتين تتناسب طرديًا مع حاصل ضرب مقداري الشحنتين، وعكسيًا مع مربع المسافة بينهما، وتكون واقعة على الخط الواصل بينهما. صيغته الرياضية:
F = Q₁Q₂ / (4πε₀r²)

حيث ε₀ = 8.85×10⁻¹² F/m سماحية الفراغ.

نحسب أولًا الثابت k = 1/(4πε₀) = 1/(4π × 8.85×10⁻¹²) ≈ 8.99×10⁹ N·m²/C².

بالتعويض: F = k × |Q₁| × |Q₂| / r² = (8.99×10⁹) × (3.0×10⁻⁶) × (2.0×10⁻⁶) / (0.30)²

حاصل ضرب الشحنتين: 3.0×10⁻⁶ × 2.0×10⁻⁶ = 6.0×10⁻¹²

r² = 0.30² = 0.09 m²

F = (8.99×10⁹ × 6.0×10⁻¹²) / 0.09 ≈ (5.39×10⁻²) / 0.09 ≈ 0.60 N

إذن مقدار القوة الكهربائية F ≈ 0.60 N. وبما أن الشحنتين مختلفتان في النوع (إحداهما موجبة والأخرى سالبة)، فإن القوة بينهما قوة تجاذب.

[درس 4-2] سؤال تدريبي: شحنتان نقطيتان تفصل بينهما مسافة r، وتتنافران بقوة كهربائية مقدارها F. إذا تضاعف مقدار إحدى الشحنتين وتضاعفت المسافة بينهما في الوقت نفسه، أوجد القوة الكهربائية الجديدة بدلالة F.
الإجابة النموذجية: من قانون كولوم: F = Q₁Q₂ / (4πε₀r²)

لتكن الشحنة الجديدة 2Q₁ (تضاعف إحدى الشحنتين فقط، مع بقاء الأخرى Q₂ كما هي)، والمسافة الجديدة 2r.

F' = (2Q₁)(Q₂) / [4πε₀(2r)²] = 2Q₁Q₂ / (4πε₀ × 4r²) = (2/4) × [Q₁Q₂ / (4πε₀r²)] = (1/2) F

إذن القوة الجديدة F' = F/2، أي أنها تصبح نصف القوة الأصلية.

[درس 4-2] سؤال تدريبي: كرة موصلة صغيرة مشحونة بشحنة موجبة مقدارها +5.0×10⁻⁹ C. احسب شدة المجال الكهربائي والجهد الكهربائي الناشئين عنها عند نقطة تبعد 0.20 m عن مركزها (خارج الكرة).
الإجابة النموذجية: المعطيات: Q = 5.0×10⁻⁹ C، r = 0.20 m، k = 1/(4πε₀) ≈ 8.99×10⁹ N·m²/C².

شدة المجال الكهربائي:
E = Q/(4πε₀r²) = kQ/r² = (8.99×10⁹ × 5.0×10⁻⁹) / (0.20)²

البسط: 8.99×10⁹ × 5.0×10⁻⁹ = 44.95

r² = 0.04 m²

E = 44.95 / 0.04 ≈ 1.12×10³ N/C

الجهد الكهربائي:
V = Q/(4πε₀r) = kQ/r = 44.95 / 0.20 ≈ 2.25×10² V

إذن شدة المجال E ≈ 1.1×10³ N/C (أو V/m)، والجهد الكهربائي V ≈ 2.2×10² V ≈ 225 V، مع ملاحظة أن الكرة المشحونة (خارجها) تتصرف كأنها شحنة نقطية مركّزة عند مركزها.

[درس 4-2] سؤال تدريبي: توضع شحنتان نقطيتان موجبتان عند النقطتين A وB، وتوجد نقطة P بحيث تبعد عن A مسافة 0.30 m، وتبعد عن B مسافة 0.40 m، وتكون الزاوية APB بين الخطين PA وPB زاوية قائمة (90°). إذا كانت الشحنة عند A تساوي +2.0×10⁻⁹ C والشحنة عند B تساوي +3.0×10⁻⁹ C، احسب مقدار شدة المجال الكهربائي المحصلة عند النقطة P.
الإجابة النموذجية: نحسب أولًا شدة المجال الناتج عن كل شحنة عند P على حدة، باستخدام E = kQ/r² وk ≈ 8.99×10⁹ N·m²/C².

المجال الناتج عن الشحنة عند A (Q_A = 2.0×10⁻⁹ C، r_A = 0.30 m):
E_A = (8.99×10⁹ × 2.0×10⁻⁹) / (0.30)² = 17.98 / 0.09 ≈ 199.8 N/C

المجال الناتج عن الشحنة عند B (Q_B = 3.0×10⁻⁹ C، r_B = 0.40 m):
E_B = (8.99×10⁹ × 3.0×10⁻⁹) / (0.40)² = 26.97 / 0.16 ≈ 168.6 N/C

بما أن اتجاه E_A (على امتداد الخط من A إلى P) واتجاه E_B (على امتداد الخط من B إلى P) متعامدان (لأن الزاوية APB قائمة)، فإن محصلتهما تُحسب بنظرية فيثاغورس:

E_R = √(E_A² + E_B²) = √(199.8² + 168.6²) = √(39920 + 28426) = √68346 ≈ 261.4 N/C

إذن شدة المجال الكهربائي المحصلة عند النقطة P تساوي تقريبًا 2.6×10² N/C.

[درس 4-2] سؤال تدريبي: توجد شحنتان نقطيتان موجبتان على استقامة واحدة: Q₁ = +4.0×10⁻⁶ C وQ₂ = +1.0×10⁻⁶ C، تفصل بينهما مسافة 0.60 m. حدد موضع النقطة الواقعة على الخط المستقيم الواصل بين الشحنتين التي يكون عندها المجال الكهربائي المحصل مساويًا للصفر.
الإجابة النموذجية: بما أن الشحنتين متشابهتان في النوع (كلاهما موجبة)، فإن النقطة التي يتساوى عندها المجالان في المقدار ويتعاكسان في الاتجاه تقع بين الشحنتين، وتكون أقرب إلى الشحنة الأصغر مقدارًا (Q₂) لأن مجالها يجب أن يقوى بالاقتراب منها ليوازن مجال الشحنة الأكبر Q₁ من مسافة أبعد.

ليكن x بعد النقطة المطلوبة عن الشحنة Q₂، فيكون بعدها عن Q₁ يساوي (0.60 − x).

عند تساوي المجالين: kQ₁/(0.60−x)² = kQ₂/x²

الثابت k يُحذف من الطرفين:
Q₁/Q₂ = [(0.60−x)/x]²

4.0×10⁻⁶ / 1.0×10⁻⁶ = 4 = [(0.60−x)/x]²

بأخذ الجذر التربيعي لكلا الطرفين: (0.60−x)/x = 2

0.60 − x = 2x ⟹ 0.60 = 3x ⟹ x = 0.20 m

إذن النقطة الصفرية تبعد 0.20 m عن الشحنة Q₂ (الأصغر)، أي 0.40 m عن الشحنة Q₁ (الأكبر)، وتقع بين الشحنتين كما هو متوقع.

[درس 4-2] سؤال تدريبي: شحنتان نقطيتان مختلفتان في النوع (إحداهما موجبة والأخرى سالبة، ومختلفتان في المقدار) تفصل بينهما مسافة r على خط مستقيم. أين تقع النقطة (إن وجدت) التي يكون عندها المجال الكهربائي المحصل الناتج عن الشحنتين مساويًا للصفر على امتداد هذا الخط؟ (اختر الإجابة الصحيحة)
(أ) بين الشحنتين دائمًا، عند منتصف المسافة بينهما.
(ب) خارج نطاق الشحنتين، على الجانب الأقرب إلى الشحنة الأصغر مقدارًا.
(ج) خارج نطاق الشحنتين، على الجانب الأقرب إلى الشحنة الأكبر مقدارًا.
(د) لا توجد أي نقطة يكون عندها المجال صفرًا مهما بعدنا على امتداد الخط.
الإجابة النموذجية: بين شحنتين مختلفتين في النوع، يكون المجالان الناتجان عن الشحنتين في أي نقطة تقع بينهما في نفس الاتجاه تقريبًا (كلاهما موجه من الموجبة نحو السالبة على ذلك الجزء من الخط)، فيتجمعان ولا يتلاشيان أبدًا؛ لذلك لا توجد نقطة صفرية بين الشحنتين، وهذا يستبعد الخيار (أ).

أما خارج نطاق الشحنتين، فإن المجالين الناتجين عن الشحنتين يكونان متعاكسين في الاتجاه في تلك المنطقة، فيمكن أن يتساويا في المقدار عند نقطة معينة فيتلاشيا. ولإيجاد هذا التوازن، يجب أن تكون تلك النقطة أقرب إلى الشحنة الأصغر مقدارًا (حتى يتمكن مجالها الأضعف أساسًا من مجاراة مجال الشحنة الأكبر من مسافة أبعد نسبيًا)، أي على الجانب الخارجي المجاور للشحنة الأصغر مقدارًا.

إذن الإجابة الصحيحة هي (ب).

[درس 5-2] سؤال تدريبي: عرّف الجهد الكهربائي عند نقطة في مجال كهربائي. ثم احسب الجهد الكهربائي عند نقطة تبعد 0.15 m عن مركز كرة موصلة مشحونة بشحنة مقدارها +8.0×10⁻⁹ C.
الإجابة النموذجية: الجهد الكهربائي عند نقطة في مجال كهربائي يُعرَّف بأنه الشغل المبذول لنقل وحدة الشحنات الموجبة من اللانهاية (حيث الجهد يساوي صفرًا) إلى تلك النقطة، دون تغيير في طاقتها الحركية.

ويُحسب الجهد الناشئ عن شحنة نقطية أو كروية Q عند مسافة r عن مركزها بالعلاقة:
V = Q/(4πε₀r) = kQ/r، حيث k = 1/(4πε₀) ≈ 8.99×10⁹ N·m²/C²

بالتعويض بالمعطيات Q = 8.0×10⁻⁹ C وr = 0.15 m:

V = (8.99×10⁹ × 8.0×10⁻⁹) / 0.15

البسط: 8.99×10⁹ × 8.0×10⁻⁹ = 71.92

V = 71.92 / 0.15 ≈ 479.5 V

إذن الجهد الكهربائي عند تلك النقطة V ≈ 4.8×10² V.

[درس 5-2] سؤال تدريبي: شحنتان نقطيتان Q₁ = +2.0×10⁻⁶ C وQ₂ = −3.0×10⁻⁶ C تفصل بينهما مسافة 0.50 m. احسب طاقة الوضع الكهربائية لهذا النظام من الشحنتين، ثم احسب طاقة الوضع الجديدة إذا قُرِّبت الشحنتان حتى أصبحت المسافة بينهما 0.25 m، وبيّن كيف تغيرت طاقة الوضع بين الحالتين.
الإجابة النموذجية: طاقة الوضع الكهربائية لشحنتين نقطيتين تُعطى بالعلاقة: Ep = Q₁Q₂/(4πε₀r) = kQ₁Q₂/r، حيث k ≈ 8.99×10⁹ N·m²/C².

عند r₁ = 0.50 m:
Ep₁ = (8.99×10⁹) × (2.0×10⁻⁶) × (−3.0×10⁻⁶) / 0.50

حاصل ضرب الشحنتين: (2.0×10⁻⁶)×(−3.0×10⁻⁶) = −6.0×10⁻¹²

Ep₁ = (8.99×10⁹ × −6.0×10⁻¹²) / 0.50 = (−5.394×10⁻²) / 0.50 ≈ −0.108 J

عند r₂ = 0.25 m (نصف المسافة الأصلية):
Ep₂ = (8.99×10⁹ × −6.0×10⁻¹²) / 0.25 = (−5.394×10⁻²) / 0.25 ≈ −0.216 J

بما أن Ep تتناسب عكسيًا مع r (لشحنتين ثابتتين)، فإن تنصيف المسافة يضاعف القيمة المطلقة لطاقة الوضع. وبما أن الشحنتين مختلفتان في النوع فإن طاقة الوضع سالبة (نظام متجاذب ومستقر)، وقد ازدادت سلبيتها (أصبحت أكثر سالبية) من −0.108 J إلى −0.216 J تقريبًا، أي انخفضت طاقة الوضع (أصبحت أكثر سالبية بمقدار الضعف)، وهذا متوقع لأن تقريب شحنتين متجاذبتين يحرر طاقة إضافية من النظام.

[درس 5-2] سؤال تدريبي: شحنة نقطية ثابتة Q = +5.0×10⁻⁶ C موضوعة في الفراغ. تتحرك شحنة اختبار q = +2.0×10⁻⁹ C من نقطة تبعد 0.60 m عن Q إلى نقطة أخرى تبعد 0.20 m عن Q (أي تقترب منها). احسب الشغل المبذول لتحريك الشحنة q بين هاتين النقطتين، وفسّر إشارة هذا الشغل.
الإجابة النموذجية: نحسب أولًا الجهد الكهربائي الناشئ عن Q عند كل من النقطتين، باستخدام V = kQ/r وk ≈ 8.99×10⁹ N·m²/C².

عند r₁ = 0.60 m: V₁ = (8.99×10⁹ × 5.0×10⁻⁶) / 0.60 = (4.495×10⁴) / 0.60 ≈ 7.49×10⁴ V

عند r₂ = 0.20 m: V₂ = (8.99×10⁹ × 5.0×10⁻⁶) / 0.20 = (4.495×10⁴) / 0.20 ≈ 2.25×10⁵ V

فرق الجهد بين النقطتين: ΔV = V₂ − V₁ ≈ (2.25×10⁵) − (7.49×10⁴) ≈ 1.50×10⁵ V

الشغل المبذول (من قوة خارجية) لتحريك الشحنة q من النقطة الأولى إلى الثانية:
W = qΔV = (2.0×10⁻⁹) × (1.50×10⁵) ≈ 3.0×10⁻⁴ J

إشارة الشغل موجبة، وهذا متوقع فيزيائيًا: الشحنتان Q وq كلتاهما موجبتان، فتتنافران، وتقريب q من Q يتطلب بذل شغل موجب من قوة خارجية للتغلب على قوة التنافر (وهذا الشغل يساوي الزيادة في طاقة الوضع الكهربائية للنظام ΔEp). أما الشغل المبذول من القوة الكهربائية نفسها على q فيكون بنفس المقدار لكن بإشارة سالبة (−3.0×10⁻⁴ J)، لأن القوة الكهربائية (التنافرية) تعاكس اتجاه الحركة نحو الداخل.

[درس 5-2] سؤال تدريبي: جسم مشحون كروي الشكل، قيست قيمة الجهد الكهربائي الناتج عنه عند نقاط مختلفة تبعد عن مركزه بالمسافة r، فوُجد أن الجهد يتناسب عكسيًا مع المسافة (V ∝ 1/r)، بما يتوافق مع V = kQ/r. عند نقطة تبعد r = 0.10 m عن مركز الجسم، وُجد أن V = 900 V. استخدم هذه المعلومة لتحديد: (a) مقدار شحنة الجسم Q. (b) شدة المجال الكهربائي عند النقطة نفسها (r = 0.10 m).
الإجابة النموذجية: (a) من العلاقة V = kQ/r، يمكن إيجاد Q:
Q = Vr/k = (900 × 0.10) / (8.99×10⁹) = 90 / (8.99×10⁹) ≈ 1.0×10⁻⁸ C

(b) لإيجاد شدة المجال عند النقطة نفسها، نلاحظ أن E = kQ/r² = (kQ/r)/r = V/r (وهذه علاقة خاصة تصح عند حساب V وE عند المسافة نفسها r من شحنة نقطية أو كروية، وتختلف عن العلاقة E = V/d الخاصة بالمجال المنتظم بين لوحين متوازيين):

E = V/r = 900 / 0.10 = 9000 V/m

إذن مقدار شحنة الجسم Q ≈ 1.0×10⁻⁸ C، وشدة المجال الكهربائي عند تلك النقطة E = 9.0×10³ V/m (أو N/C).

[درس 5-2] سؤال تدريبي: توضع شحنة اختبار موجبة صغيرة بالقرب من اللوح الموجب لمكثف ذي لوحين متوازيين، ثم تُترك حرة فتتحرك بتأثير القوة الكهربائية نحو اللوح السالب. صف كيف يتغير كل من: (a) الجهد الكهربائي عند موضع الشحنة. (b) طاقة الوضع الكهربائية للشحنة، أثناء حركتها من اللوح الموجب نحو اللوح السالب.
الإجابة النموذجية: (a) الجهد الكهربائي بين لوحين متوازيين يتناقص خطيًا وبانتظام كلما ابتعدنا عن اللوح الموجب واقتربنا من اللوح السالب (لأن المجال منتظم، والجهد أعلى ما يمكن عند اللوح الموجب وأدنى ما يمكن — وقد يكون سالبًا نسبيًا — عند اللوح السالب). لذلك فإن الجهد الكهربائي عند موضع الشحنة الاختبارية يتناقص باستمرار أثناء حركتها من اللوح الموجب نحو السالب.

(b) طاقة الوضع الكهربائية للشحنة الموجبة تُعطى بالعلاقة Ep = qV؛ وبما أن q ثابتة (موجبة) وV يتناقص أثناء الحركة، فإن طاقة الوضع الكهربائية للشحنة تتناقص هي الأخرى باستمرار أثناء انتقالها من اللوح الموجب نحو اللوح السالب.

ويقابل هذا الانخفاض في طاقة الوضع زيادة مكافئة في الطاقة الحركية للشحنة (حسب مبدأ حفظ الطاقة)، إذ تقوم القوة الكهربائية بتسريع الشحنة الموجبة في اتجاه حركتها نحو اللوح السالب.

[درس 5-2] سؤال تدريبي: شحنتان نقطيتان متماثلتان في الإشارة (كلاهما سالبتان) تفصل بينهما مسافة r، ولهما طاقة وضع كهربائية Ep. إذا أُبعدت إحدى الشحنتين عن الأخرى حتى أصبحت المسافة بينهما 3r، فإن طاقة الوضع الكهربائية الجديدة للنظام تساوي: (اختر الإجابة الصحيحة)
(أ) تتضاعف 3 مرات فتصبح 3Ep.
(ب) تصبح ثلث قيمتها الأصلية Ep/3.
(ج) تصبح تُسع قيمتها الأصلية Ep/9.
(د) تبقى دون تغيير.
الإجابة النموذجية: طاقة الوضع الكهربائية بين شحنتين نقطيتين: Ep = Q₁Q₂/(4πε₀r)، وهي تتناسب عكسيًا طرديًا مع المسافة r فقط (وليس مع مربعها) لأن r تظهر بالقوة الأولى فقط في المقام.

عند مضاعفة المسافة إلى 3r:
Ep' = Q₁Q₂/(4πε₀ × 3r) = (1/3) × [Q₁Q₂/(4πε₀r)] = Ep/3

إذن طاقة الوضع الجديدة تساوي ثلث القيمة الأصلية، والإجابة الصحيحة هي (ب). (ملاحظة: بما أن الشحنتين متشابهتان في الإشارة، فإن حاصل ضربهما موجب وEp موجبة أصلًا، وتبقى موجبة بعد الإبعاد لكنها تقل إلى الثلث).

[درس 1-3] سؤال تدريبي: عرّف شدة التيار الكهربائي في موصل، واكتب العلاقة الرياضية التي تربط شدة التيار بالشحنة الكهربائية والزمن مع تحديد وحدة كل كمية.
الإجابة النموذجية: شدة التيار الكهربائي (I) تُعرَّف بأنها معدل تدفق الشحنة الكهربائية عبر مقطع عرضي لموصل (أو عبر أي نقطة في الدائرة الكهربائية) بالنسبة للزمن.

العلاقة الرياضية: I = ΔQ/Δt

حيث Q هي الشحنة الكهربائية المنقولة ووحدتها الكولوم (C)، وt هو الزمن ووحدته الثانية (s).

وحدة شدة التيار هي الأمبير (A)، وتُعرَّف بأن 1 A = 1 C s⁻¹.

[درس 1-3] سؤال تدريبي: يمر تيار كهربائي في سلك نحاسي مساحة مقطعه العرضي 1.5 × 10⁻⁶ m². إذا كانت الكثافة العددية لإلكترونات التوصيل الحرة في النحاس n = 8.5 × 10²⁸ m⁻³، والسرعة الانجرافية المتجهة للإلكترونات v = 2.0 × 10⁻⁴ m s⁻¹، احسب شدة التيار المار في السلك. (شحنة الإلكترون q = 1.6 × 10⁻¹⁹ C)
الإجابة النموذجية: نستخدم العلاقة: I = nAvq

بالتعويض: I = (8.5 × 10²⁸) × (1.5 × 10⁻⁶) × (2.0 × 10⁻⁴) × (1.6 × 10⁻¹⁹)

نحسب على خطوات:
8.5 × 10²⁸ × 1.5 × 10⁻⁶ = 1.275 × 10²³

1.275 × 10²³ × 2.0 × 10⁻⁴ = 2.55 × 10¹⁹

2.55 × 10¹⁹ × 1.6 × 10⁻¹⁹ = 4.08

إذن شدة التيار I ≈ 4.1 A

[درس 1-3] سؤال تدريبي: يمر تيار شدته 3.0 A في سلك نحاسي قطره 0.60 mm. إذا كانت الكثافة العددية لإلكترونات التوصيل الحرة في النحاس n = 8.5 × 10²⁸ m⁻³، احسب السرعة الانجرافية المتجهة للإلكترونات في هذا السلك. (شحنة الإلكترون q = 1.6 × 10⁻¹⁹ C)
الإجابة النموذجية: نجد نصف قطر السلك: r = القطر / 2 = 0.60 mm / 2 = 0.30 mm = 3.0 × 10⁻⁴ m

مساحة المقطع العرضي: A = πr² = π × (3.0 × 10⁻⁴)² = π × 9.0 × 10⁻⁸ = 2.83 × 10⁻⁷ m²

من العلاقة I = nAvq، نجد السرعة الانجرافية:
v = I / (nAq)

بالتعويض: v = 3.0 / [(8.5 × 10²⁸) × (2.83 × 10⁻⁷) × (1.6 × 10⁻¹⁹)]

نحسب المقام خطوة بخطوة:
8.5 × 10²⁸ × 2.83 × 10⁻⁷ = 2.41 × 10²²

2.41 × 10²² × 1.6 × 10⁻¹⁹ = 3.85 × 10³

إذن: v = 3.0 / (3.85 × 10³) = 7.8 × 10⁻⁴ m s⁻¹

[درس 1-3] سؤال تدريبي: سلك معدني واحد يتكوّن من جزأين متصلين على التوالي من المادة نفسها: الجزء (X) مساحة مقطعه العرضي 2.4 × 10⁻⁶ m²، والجزء (Y) مساحة مقطعه العرضي 0.8 × 10⁻⁶ m². يمر التيار نفسه I في الجزأين. إذا كانت السرعة الانجرافية المتجهة للإلكترونات في الجزء (X) تساوي 1.2 × 10⁻⁴ m s⁻¹، بيّن أن السرعة الانجرافية المتجهة في الجزء (Y) تساوي 3.6 × 10⁻⁴ m s⁻¹.
الإجابة النموذجية: بما أن الجزأين من المادة نفسها، فإن الكثافة العددية لحاملات الشحنة n واحدة في الجزأين (خاصية للمادة لا تتغير بتغيّر أبعاد السلك). كما أن شدة التيار I واحدة في الجزأين لأنهما متصلان على التوالي.

من العلاقة I = nAvq، وبما أن n وq وI ثابتة، فإن الجداء A×v يجب أن يبقى ثابتاً على طول السلك:
Aₓvₓ = Aᵧvᵧ

إذن: vᵧ = vₓ × (Aₓ/Aᵧ)

بالتعويض: vᵧ = 1.2 × 10⁻⁴ × (2.4 × 10⁻⁶ / 0.8 × 10⁻⁶) = 1.2 × 10⁻⁴ × 3 = 3.6 × 10⁻⁴ m s⁻¹

وهو المطلوب إثباته. فعندما تقل مساحة المقطع العرضي (من X إلى Y)، يجب أن تزداد السرعة الانجرافية لكي يبقى التيار نفسه مستمراً.

[درس 1-3] سؤال تدريبي: أي من الوحدات التالية تكافئ وحدة الأمبير (A)؟ (اختر الإجابة الصحيحة)
(أ) C s⁻¹
(ب) J s⁻¹
(ج) J C⁻¹
(د) C V⁻¹
الإجابة النموذجية: بما أن I = Q/t، فإن وحدة شدة التيار هي: كولوم لكل ثانية، أي C s⁻¹.

نفحص بقية الخيارات: J s⁻¹ هي وحدة القدرة (الواط)، وJ C⁻¹ هي وحدة فرق الجهد (الفولت)، وC V⁻¹ هي وحدة السعة الكهربائية (الفاراد). وكلها وحدات لكميات فيزيائية مختلفة عن التيار.

إذن الإجابة الصحيحة: (أ) C s⁻¹

[درس 2-3] سؤال تدريبي: عرّف فرق الجهد الكهربائي (V) بين نقطتين في دائرة كهربائية، واكتب العلاقة الرياضية التي تُستخدم لحسابه.
الإجابة النموذجية: فرق الجهد الكهربائي بين نقطتين في دائرة كهربائية هو الطاقة الكهربائية المحوَّلة (من صورة إلى أخرى) لكل وحدة شحنة تمر بين هاتين النقطتين.

العلاقة الرياضية: V = W/Q

حيث W هي الطاقة المحوَّلة (بالجول J)، وQ هي الشحنة المارة (بالكولوم C)، وV بوحدة الفولت (V)، حيث 1 V = 1 J C⁻¹.

[درس 2-3] سؤال تدريبي: يمر تيار شدته 2.5 A في مقاومة قدرها 8.0 Ω لمدة 3.0 دقائق. احسب: (i) فرق الجهد بين طرفي المقاومة، (ii) مقدار الشحنة الكهربائية التي تمر خلال هذه المدة، (iii) الطاقة الكهربائية المحوَّلة في المقاومة خلال هذه المدة.
الإجابة النموذجية: (i) فرق الجهد: V = I R = 2.5 × 8.0 = 20 V

(ii) الزمن بالثواني: t = 3.0 × 60 = 180 s
الشحنة: Q = I t = 2.5 × 180 = 450 C

(iii) الطاقة المحوَّلة: W = V Q = 20 × 450 = 9000 J = 9.0 × 10³ J

(يمكن التحقق بطريقة أخرى: W = I²Rt = (2.5)² × 8.0 × 180 = 6.25 × 8.0 × 180 = 9000 J، وهو نفس الناتج)

[درس 2-3] سؤال تدريبي: بطارية قوتها الدافعة الكهربائية E = 9.0 V ومقاومتها الداخلية r = 1.5 Ω متصلة بمقاومة خارجية R = 7.5 Ω. احسب فرق الجهد بين طرفي المقاومة الخارجية R، وفسّر لماذا يكون هذا الفرق أقل من القوة الدافعة الكهربائية للبطارية.
الإجابة النموذجية: شدة التيار في الدائرة: I = E / (R + r) = 9.0 / (7.5 + 1.5) = 9.0 / 9.0 = 1.0 A

فرق الجهد بين طرفي المقاومة الخارجية (وهو نفسه الجهد الطرفي للبطارية):
V = I R = 1.0 × 7.5 = 7.5 V

(يمكن التحقق: V = E − I r = 9.0 − (1.0 × 1.5) = 9.0 − 1.5 = 7.5 V، وهو نفس الناتج)

التفسير: جزء من الطاقة الكهربائية التي تولدها البطارية يُهدَر كحرارة داخل البطارية نفسها بسبب مقاومتها الداخلية r (فرق الجهد المفقود = I r = 1.5 V). لذلك فإن الجهد الطرفي المتاح للدائرة الخارجية (7.5 V) يكون أقل من القوة الدافعة الكهربائية الكلية (9.0 V) بمقدار الجهد المفقود داخل البطارية.

[درس 2-3] سؤال تدريبي: أي من العبارات التالية تمثل التعريف الصحيح لوحدة الفولت (V)؟ (اختر الإجابة الصحيحة)
(أ) 1 V = 1 J C⁻¹
(ب) 1 V = 1 C J⁻¹
(ج) 1 V = 1 A s
(د) 1 V = 1 J A⁻¹
الإجابة النموذجية: بما أن V = W/Q، فإن وحدة الفولت تُعرَّف بأنها جول لكل كولوم: 1 V = 1 J C⁻¹.

العبارة (ب) مقلوبة وتمثل كولوم لكل جول (وهي غير صحيحة كتعريف للفولت). العبارة (ج) تكافئ C s⁻¹ × s = C، وهي وحدة الشحنة لا الجهد. العبارة (د) لا تساوي الفولت أبعادياً.

إذن الإجابة الصحيحة: (أ) 1 V = 1 J C⁻¹

[درس 2-3] سؤال تدريبي: تمر شحنة كهربائية مقدارها 240 C خلال مقاومتين متصلتين على التوالي في دائرة كهربائية خلال 2.0 دقيقة. إذا كانت الطاقة المحوَّلة في المقاومة الأولى 960 J، والطاقة المحوَّلة في المقاومة الثانية 1440 J، حدد فرق الجهد بين طرفي كل مقاومة، ثم حدد القوة الدافعة الكهربائية الكلية للمصدر (بافتراض أن مقاومته الداخلية مهملة).
الإجابة النموذجية: فرق الجهد بين طرفي المقاومة الأولى: V₁ = W₁ / Q = 960 / 240 = 4.0 V

فرق الجهد بين طرفي المقاومة الثانية: V₂ = W₂ / Q = 1440 / 240 = 6.0 V

بما أن المقاومتين متصلتان على التوالي، فإن مجموع فرقي الجهد عبرهما يساوي القوة الدافعة الكهربائية الكلية للمصدر (بافتراض عدم وجود مقاومة داخلية):
E = V₁ + V₂ = 4.0 + 6.0 = 10.0 V

[درس 3-3] سؤال تدريبي: فسّر معنى المقاومة النوعية (ρ) لمادة موصل، موضحاً لماذا تُعدّ خاصية للمادة نفسها ولا تعتمد على طول الموصل أو مساحة مقطعه العرضي، على عكس المقاومة (R) التي تعتمد على هذه الأبعاد.
الإجابة النموذجية: المقاومة النوعية ρ هي خاصية فيزيائية للمادة نفسها تعتمد على تركيب المادة الداخلي (مثل كثافة حاملات الشحنة الحرة فيها ودرجة الحرارة) ولا تتغير بتغيّر أبعاد العينة المصنوعة من هذه المادة (لا الطول L ولا مساحة المقطع A).

بالمقابل، فإن المقاومة R لموصل معين تعتمد على أبعاده وفق العلاقة R = ρL/A: فزيادة طول الموصل L تزيد مقاومته (لأن الإلكترونات تصطدم بعدد أكبر من الأيونات على طول مسار أطول)، بينما زيادة مساحة المقطع A تقلل مقاومته (لأن مساحة أكبر تتيح مساراً أعرض لتدفق الشحنة).

لذلك فإن سلكين من المادة نفسها (نفس ρ) قد تكون مقاومتاهما مختلفتين تماماً إذا اختلف طولاهما أو مساحتا مقطعيهما، بينما يبقى ρ نفسه دائماً ثابتاً طالما بقيت المادة ودرجة الحرارة كما هما.

[درس 3-3] سؤال تدريبي: سلك نحاسي طوله 2.5 m وقطره 0.44 mm. إذا كانت المقاومة النوعية للنحاس ρ = 1.7 × 10⁻⁸ Ω m، احسب مقاومة هذا السلك.
الإجابة النموذجية: نصف قطر السلك: r = القطر / 2 = 0.44 mm / 2 = 0.22 mm = 2.2 × 10⁻⁴ m

مساحة المقطع العرضي: A = πr² = π × (2.2 × 10⁻⁴)² = π × 4.84 × 10⁻⁸ = 1.52 × 10⁻⁷ m²

من العلاقة R = ρL/A:
R = (1.7 × 10⁻⁸ × 2.5) / (1.52 × 10⁻⁷)

البسط: 1.7 × 10⁻⁸ × 2.5 = 4.25 × 10⁻⁸

R = 4.25 × 10⁻⁸ / 1.52 × 10⁻⁷ = 0.28 Ω

[درس 3-3] سؤال تدريبي: سلك من سبيكة النيكروم (Nichrome) مقاومته النوعية ρ = 1.10 × 10⁻⁶ Ω m، ومساحة مقطعه العرضي 0.20 mm². بيّن أن مقاومة سلك طوله 4.5 m من هذه السبيكة تساوي تقريباً 25 Ω.
الإجابة النموذجية: نحوّل مساحة المقطع إلى المتر المربع: A = 0.20 mm² = 0.20 × 10⁻⁶ m² = 2.0 × 10⁻⁷ m²

من العلاقة R = ρL/A:
R = (1.10 × 10⁻⁶ × 4.5) / (2.0 × 10⁻⁷)

البسط: 1.10 × 10⁻⁶ × 4.5 = 4.95 × 10⁻⁶

R = 4.95 × 10⁻⁶ / 2.0 × 10⁻⁷ = 24.75 Ω ≈ 25 Ω

وهذا يؤكد صحة القيمة المعطاة (تقريباً 25 Ω).

[درس 3-3] سؤال تدريبي: سلكان (A) و(B) مصنوعان من المادة نفسها (نفس المقاومة النوعية ρ). طول السلك (A) يساوي L ومساحة مقطعه A₀، بينما طول السلك (B) يساوي 3L ومساحة مقطعه 2A₀. قارن بين مقاومتي السلكين بإيجاد النسبة R_A : R_B.
الإجابة النموذجية: مقاومة السلك A: R_A = ρL / A₀

مقاومة السلك B: R_B = ρ(3L) / (2A₀) = (3/2) × (ρL/A₀) = 1.5 R_A

إذن النسبة: R_A : R_B = 1 : 1.5 = 2 : 3

أي أن مقاومة السلك B أكبر من مقاومة السلك A بمقدار 1.5 مرة، رغم أن مساحة مقطعه أكبر، وذلك لأن طوله (3 أضعاف) أثّر في المقاومة بشكل أكبر من تأثير زيادة مساحة المقطع (ضعفين) في تقليلها.

[درس 3-3] سؤال تدريبي: سلك معدني مقاومته R، تم سحبه (شدّه) بانتظام حتى تضاعف طوله، مع بقاء حجمه ثابتاً (أي لا تغيّر في كمية المادة). إذا بقيت المقاومة النوعية ρ ثابتة، فما مقدار المقاومة الجديدة للسلك بدلالة R؟ (اختر الإجابة الصحيحة)
(أ) R/4
(ب) R/2
(ج) 2R
(د) 4R
الإجابة النموذجية: بما أن الحجم ثابت: الحجم = L × A = ثابت. عندما يتضاعف الطول (L' = 2L)، يجب أن تنخفض مساحة المقطع إلى النصف حتى يبقى الحجم كما هو: A' = A/2.

المقاومة الجديدة: R' = ρL'/A' = ρ(2L)/(A/2) = 4 × (ρL/A) = 4R

إذن الإجابة الصحيحة: (د) 4R

[درس 4-3] سؤال تدريبي: انصّ على قانون كيرشوف الأول، ووضّح المبدأ الفيزيائي الذي يُعبّر عنه هذا القانون.
الإجابة النموذجية: قانون كيرشوف الأول: مجموع شدات التيارات الداخلة إلى أي نقطة تفرع (وصلة) في دائرة كهربائية يساوي مجموع شدات التيارات الخارجة من تلك النقطة.

رياضياً: Σ I_داخل = Σ I_خارج

هذا القانون هو تعبير مباشر عن مبدأ حفظ الشحنة الكهربائية: الشحنة لا تتولّد ولا تختفي عند نقطة التفرع، فكل الشحنة التي تدخل نقطة معينة خلال زمن معين لا بد أن تخرج منها بالكامل خلال الزمن نفسه (لا تتراكم شحنة عند النقطة).

[درس 4-3] سؤال تدريبي: انصّ على قانون كيرشوف الثاني، ووضّح المبدأ الفيزيائي الذي يُعبّر عنه هذا القانون.
الإجابة النموذجية: قانون كيرشوف الثاني: في أي مسار مغلق (حلقة) داخل دائرة كهربائية، يكون مجموع القوى الدافعة الكهربائية (E) في ذلك المسار مساوياً لمجموع فروق الجهد الكهربائية (IR) عبر جميع عناصر المسار نفسه.

رياضياً: Σ E = Σ IR

هذا القانون تعبير عن مبدأ حفظ الطاقة: الطاقة الكهربائية الممنوحة لكل وحدة شحنة من مصادر القوة الدافعة الكهربائية في المسار المغلق تُستهلك بالكامل (تتحوّل إلى صور أخرى من الطاقة) في عناصر الدائرة الأخرى على طول المسار نفسه، فلا يوجد فقد أو زيادة صافية في الطاقة بعد إتمام دورة كاملة حول المسار.

[درس 4-3] سؤال تدريبي: عند نقطة تفرّع في دائرة كهربائية تلتقي أربعة أسلاك: يدخل النقطة تياران شدتاهما I₁ = 2.0 A وI₂ = 1.5 A، ويخرج منها تياران شدتاهما I₃ = 0.8 A وI₄ (مجهول). باستخدام قانون كيرشوف الأول، احسب قيمة I₄.
الإجابة النموذجية: بحسب قانون كيرشوف الأول: مجموع التيارات الداخلة = مجموع التيارات الخارجة

I₁ + I₂ = I₃ + I₄

2.0 + 1.5 = 0.8 + I₄

3.5 = 0.8 + I₄

I₄ = 3.5 − 0.8 = 2.7 A

[درس 4-3] سؤال تدريبي: خلية قوتها الدافعة الكهربائية E = 12 V ومقاومتها الداخلية مهملة، متصلة على التوالي بمقاومتين R₁ = 4.0 Ω وR₂ = 8.0 Ω. باستخدام قانون كيرشوف الثاني، احسب شدة التيار في الدائرة وفرق الجهد بين طرفي كل مقاومة، وتحقق من أن مجموع فروق الجهد يساوي القوة الدافعة الكهربائية.
الإجابة النموذجية: بتطبيق قانون كيرشوف الثاني على الحلقة الوحيدة في الدائرة:
E = I R₁ + I R₂ = I(R₁ + R₂)

12 = I (4.0 + 8.0) = 12 I

I = 12 / 12 = 1.0 A

فرق الجهد بين طرفي R₁: V₁ = I R₁ = 1.0 × 4.0 = 4.0 V

فرق الجهد بين طرفي R₂: V₂ = I R₂ = 1.0 × 8.0 = 8.0 V

التحقق: V₁ + V₂ = 4.0 + 8.0 = 12.0 V = E ✓ (متطابق مع القوة الدافعة الكهربائية كما ينص قانون كيرشوف الثاني)

[درس 4-3] سؤال تدريبي: دائرة كهربائية تحتوي على بطاريتين متصلتين بالتوازي بين نقطتين A وB، مع مقاومة ثالثة مشتركة: تنطلق البطارية الأولى (قوتها الدافعة الكهربائية E₁ = 7.0 V، مقاومتها الداخلية مهملة) من A عبر مقاومة R₁ = 2.0 Ω إلى B، وتنطلق البطارية الثانية (قوتها الدافعة الكهربائية E₂ = 6.0 V، مقاومتها الداخلية مهملة) من A أيضاً عبر مقاومة R₂ = 3.0 Ω إلى B. ثم تتصل B بـ A عبر مقاومة ثالثة R₃ = 1.0 Ω. بافتراض أن التيارين I₁ (في فرع البطارية الأولى) وI₂ (في فرع البطارية الثانية) يتجهان من A إلى B، وأن التيار I₃ يتجه من B إلى A عبر R₃، استخدم قانوني كيرشوف لحساب قيم I₁ وI₂ وI₃.
الإجابة النموذجية: من قانون كيرشوف الأول عند النقطة B (التيارات الداخلة = التيارات الخارجة):
I₁ + I₂ = I₃ ... (1)

من قانون كيرشوف الثاني على الحلقة التي تحتوي البطارية الأولى (E₁, R₁) والمقاومة R₃:
E₁ = I₁R₁ + I₃R₃
7.0 = 2.0 I₁ + 1.0 I₃ ... (2)

من قانون كيرشوف الثاني على الحلقة التي تحتوي البطارية الثانية (E₂, R₂) والمقاومة R₃:
E₂ = I₂R₂ + I₃R₃
6.0 = 3.0 I₂ + 1.0 I₃ ... (3)

نعوّض المعادلة (1) في المعادلتين (2) و(3):

من (2): 7.0 = 2.0 I₁ + (I₁ + I₂) = 3.0 I₁ + I₂ ... (2')
من (3): 6.0 = 3.0 I₂ + (I₁ + I₂) = I₁ + 4.0 I₂ ... (3')

من (2'): I₂ = 7.0 − 3.0 I₁

نعوّض في (3'):
6.0 = I₁ + 4.0(7.0 − 3.0 I₁) = I₁ + 28.0 − 12.0 I₁ = 28.0 − 11.0 I₁

11.0 I₁ = 28.0 − 6.0 = 22.0

I₁ = 22.0 / 11.0 = 2.0 A

من (2'): I₂ = 7.0 − 3.0(2.0) = 7.0 − 6.0 = 1.0 A

من (1): I₃ = I₁ + I₂ = 2.0 + 1.0 = 3.0 A

للتحقق في المعادلة (3): 3.0(1.0) + 1.0(3.0) = 3.0 + 3.0 = 6.0 = E₂ ✓

إذن: I₁ = 2.0 A، I₂ = 1.0 A، I₃ = 3.0 A

[درس 5-3] سؤال تدريبي: بطارية قوتها الدافعة الكهربائية E = 6.0 V ومقاومتها الداخلية r = 0.50 Ω، متصلة بمقاومة متغيرة R = 2.5 Ω. احسب شدة التيار في الدائرة، والجهد الطرفي للبطارية، والقدرة المفقودة (المُبدَّدة) داخل البطارية نفسها. ثم فسّر ماذا يحدث للجهد الطرفي إذا قلّت قيمة R.
الإجابة النموذجية: شدة التيار: I = E / (R + r) = 6.0 / (2.5 + 0.50) = 6.0 / 3.0 = 2.0 A

الجهد الطرفي: V = E − I r = 6.0 − (2.0 × 0.50) = 6.0 − 1.0 = 5.0 V
(يمكن التحقق: V = IR = 2.0 × 2.5 = 5.0 V، وهو نفس الناتج)

القدرة المفقودة داخل البطارية: P = I²r = (2.0)² × 0.50 = 4.0 × 0.50 = 2.0 W

التفسير: عند تقليل قيمة R، تقل المقاومة الكلية للدائرة (R + r)، فتزداد شدة التيار I وفق العلاقة I = E/(R + r). وبما أن الجهد المفقود داخل البطارية يساوي Ir، فإن زيادة I تؤدي إلى زيادة الجهد المفقود داخلياً، وبالتالي ينخفض الجهد الطرفي المتاح للدائرة الخارجية (V = E − Ir) أكثر.

[درس 5-3] سؤال تدريبي: في دائرة مجزئ جهد، مصدر جهد Vin = 12 V متصل بمقاومتين على التوالي: R₁ = 8.0 Ω وR₂ = 4.0 Ω. ما قيمة الجهد الخارج Vout المأخوذ من طرفي R₂؟ (اختر الإجابة الصحيحة)
(أ) 2.0 V
(ب) 3.0 V
(ج) 4.0 V
(د) 8.0 V
الإجابة النموذجية: في دائرة مجزئ الجهد: Vout = [R₂ / (R₁ + R₂)] × Vin

Vout = [4.0 / (8.0 + 4.0)] × 12 = (4.0/12.0) × 12 = 4.0 V

إذن الإجابة الصحيحة: (ج) 4.0 V

[درس 5-3] سؤال تدريبي: دائرة مجزئ جهد مصدرها Vin = 9.0 V، تحتوي على مقاومتين على التوالي R₁ وR₂، حيث R₁ = 12 Ω. إذا كان المطلوب الحصول على جهد خارج Vout = 3.0 V من طرفي R₂، حدد قيمة R₂ اللازمة.
الإجابة النموذجية: من علاقة مجزئ الجهد: Vout = [R₂ / (R₁ + R₂)] × Vin

3.0 = [R₂ / (12 + R₂)] × 9.0

3.0 (12 + R₂) = 9.0 R₂

36 + 3.0 R₂ = 9.0 R₂

36 = 9.0 R₂ − 3.0 R₂ = 6.0 R₂

R₂ = 36 / 6.0 = 6.0 Ω

للتحقق: Vout = [6.0/(12+6.0)] × 9.0 = (6.0/18.0) × 9.0 = 3.0 V ✓

[درس 5-3] سؤال تدريبي: سلك مقياس الجهد (البوتنشيومتر) طوله 1.00 m ومنتظم القطر، متصل بطرفي خلية قائدة قوتها الدافعة الكهربائية 2.0 V (مقاومتها الداخلية مهملة). عند توصيل خلية أخرى مجهولة القوة الدافعة الكهربائية مع جلفانومتر، وُجدت نقطة الاتزان (حيث لا يمر تيار في فرع الجلفانومتر) عند مسافة 65.0 cm من الطرف الصفري للسلك. احسب القوة الدافعة الكهربائية للخلية المجهولة.
الإجابة النموذجية: بما أن السلك منتظم القطر، فإن فرق الجهد يتوزّع بانتظام على طوله (يتناسب طردياً مع المسافة من الطرف الصفري).

التدرج الجهدي لكل وحدة طول: (فرق الجهد الكلي على السلك) / (الطول الكلي) = 2.0 V / 1.00 m = 2.0 V m⁻¹

عند نقطة الاتزان، يكون فرق الجهد بين الطرف الصفري ونقطة الاتزان مساوياً تماماً للقوة الدافعة الكهربائية للخلية المجهولة (لأنه لا يمر تيار في فرعها عند الاتزان، فلا يوجد فرق جهد مفقود بسبب مقاومتها الداخلية):

E_مجهولة = التدرج الجهدي × مسافة الاتزان = 2.0 × 0.650 = 1.3 V

[درس 5-3] سؤال تدريبي: مقاومة قيمتها 500 Ω متصلة في دائرة، ويُراد قياس فرق الجهد بين طرفيها بواسطة فولتميتر مقاومته 1000 Ω. احسب المقاومة المكافئة للمقاومة والفولتميتر معاً (متصلين على التوازي)، ثم فسّر أثر توصيل الفولتميتر على قراءة فرق الجهد مقارنة بالحالة المثالية (فولتميتر مقاومته لا نهائية).
الإجابة النموذجية: عند توصيل الفولتميتر على التوازي مع المقاومة، تُحسب المقاومة المكافئة R_مكافئة من العلاقة:

1/R_مكافئة = 1/R + 1/R_فولتميتر = 1/500 + 1/1000

بصيغة موحدة: 1/R_مكافئة = 2/1000 + 1/1000 = 3/1000

R_مكافئة = 1000/3 ≈ 333 Ω

التفسير: بما أن مقاومة الفولتميتر (1000 Ω) ليست لا نهائية، فإن توصيله على التوازي مع المقاومة (500 Ω) يقلل المقاومة الكلية لهذا الفرع من الدائرة من 500 Ω إلى نحو 333 Ω (انخفاض بنسبة الثلث تقريباً). هذا يغيّر توزيع التيار والجهد في بقية الدائرة، فتكون قراءة الفولتميتر أقل قليلاً من فرق الجهد الفعلي الذي كان سيكون موجوداً لو لم يُوصَل الفولتميتر أصلاً. لذلك يُفضَّل أن تكون مقاومة الفولتميتر كبيرة جداً (تقترب من اللانهاية) حتى لا تؤثر عملياً على الدائرة التي يقيسها.

[درس 5-3] سؤال تدريبي: دائرة كهربائية تتكوّن من مصدر جهد قوته الدافعة الكهربائية E = 5.0 V (مقاومته الداخلية مهملة) متصل على التوالي بمقاومة R = 20 Ω وأميتر حقيقي مقاومته 2.0 Ω. احسب شدة التيار التي يسجلها الأميتر، ثم احسب شدة التيار التي كانت ستمر في الدائرة لو كان الأميتر مثالياً (مقاومته صفر)، وقارن بين القيمتين.
الإجابة النموذجية: شدة التيار الفعلية (مع مقاومة الأميتر الحقيقية):
I_فعلي = E / (R + R_أميتر) = 5.0 / (20 + 2.0) = 5.0 / 22 = 0.227 A (بثلاث منازل معنوية)

شدة التيار المثالية (لو كانت مقاومة الأميتر صفراً):
I_مثالي = E / R = 5.0 / 20 = 0.250 A

المقارنة: نسبة الفرق = (I_مثالي − I_فعلي) / I_مثالي × 100% = (0.250 − 0.227) / 0.250 × 100% ≈ 9.1%

إذن فإن وجود مقاومة للأميتر (2.0 Ω) يقلل التيار الفعلي في الدائرة بنحو 9% عن القيمة الحقيقية التي كانت ستُقاس لو كان الأميتر مثالياً، مما يبيّن أهمية أن تكون مقاومة الأميتر صغيرة جداً (تقترب من الصفر) حتى لا يؤثر توصيله في الدائرة على التيار الذي يقيسه.

[درس 1-4] سؤال تدريبي: العنصر الكهربائي الذي يُصمَّم أساسًا لتخزين الشحنة الكهربائية (وبالتالي الطاقة الكهربائية) بين لوحين موصلين يفصل بينهما عازل، يُسمى: (اختر الإجابة الصحيحة)
(أ) المقاوم
(ب) المكثّف
(ج) الملف (الحثّ)
(د) الثنائي (الديود)
الإجابة النموذجية: المقاوم يحوّل الطاقة الكهربائية إلى حرارة ولا يخزّن شحنة بشكل أساسي، والملف يخزّن طاقة في مجال مغناطيسي ناتج عن مرور تيار وليس شحنة ساكنة، والثنائي عنصر يسمح بمرور التيار في اتجاه واحد ولا يُصمَّم لتخزين الشحنة.

أما المكثّف فهو العنصر المصمَّم خصيصًا لتخزين الشحنة الكهربائية على لوحيه الموصلين (المتقابلين والمفصولين بعازل)، وبالتالي تخزين طاقة كهربائية في المجال الكهربائي بين اللوحين.

الإجابة الصحيحة: (ب) المكثّف.

[درس 1-4] سؤال تدريبي: شُحن مكثّف بشحنة مقدارها 450 μC عند توصيله بفرق جهد قدره 90 V بين لوحيه. احسب سعة هذا المكثّف بوحدة الفاراد.
الإجابة النموذجية: تُعرَّف السعة الكهربائية بأنها الشحنة المخزَّنة على لوحي المكثّف لكل وحدة فرق جهد بينهما: C = Q / V.

بالتعويض: Q = 450 μC = 450×10⁻⁶ C، V = 90 V.

C = (450×10⁻⁶) / 90 = 5×10⁻⁶ F.

إذن سعة المكثّف C = 5×10⁻⁶ F = 5 μF.

[درس 1-4] سؤال تدريبي: عند رسم العلاقة بين فرق الجهد V المطبَّق على مكثّف والشحنة Q المخزَّنة عليه، ينتج خط مستقيم يمر بنقطة الأصل. إذا كانت النقطة (V = 10 V، Q = 300 μC) تقع على هذا الخط المستقيم، حدد سعة المكثّف.
الإجابة النموذجية: بما أن العلاقة بين Q و V خطية ومارّة بنقطة الأصل (Q = CV)، فإن ميل الخط المستقيم في تمثيل Q مقابل V يساوي السعة C.

C = Q / V = (300×10⁻⁶ C) / (10 V) = 30×10⁻⁶ F.

إذن سعة المكثّف C = 30×10⁻⁶ F = 30 μF.

[درس 1-4] سؤال تدريبي: شُحن مكثّف سعته C1 = 20 μF حتى بلغ فرق الجهد بين لوحيه 12 V، ثم فُصل عن مصدر الجهد وتم توصيله على التوازي مع مكثّف آخر غير مشحون سعته C2 = 30 μF (بحيث تتصل اللوحتان ذواتا الشحنة نفس الإشارة ببعضهما). حدد فرق الجهد المشترك النهائي بين لوحي المكثّفين، والشحنة على كل منهما بعد الاتصال.
الإجابة النموذجية: الشحنة الابتدائية المخزَّنة على C1 قبل الفصل (وهي الشحنة الكلية في المنظومة المعزولة بعد الفصل عن المصدر، حسب مبدأ حفظ الشحنة):
Q0 = C1 × V0 = 20×10⁻⁶ × 12 = 240×10⁻⁶ C = 240 μC.

بعد التوصيل على التوازي، تتوزع هذه الشحنة الكلية (المحفوظة) بين المكثّفين، وتصبح السعة المكافئة:
CT = C1 + C2 = 20 + 30 = 50 μF.

بما أن الشحنة الكلية محفوظة ولم تتغير (لا يوجد مسار لتسرّب الشحنة خارج المنظومة المعزولة):
V = Q0 / CT = (240×10⁻⁶) / (50×10⁻⁶) = 4.8 V.

الشحنة على كل مكثّف عند فرق الجهد المشترك الجديد:
Q1 = C1 × V = 20×10⁻⁶ × 4.8 = 96×10⁻⁶ C = 96 μC.
Q2 = C2 × V = 30×10⁻⁶ × 4.8 = 144×10⁻⁶ C = 144 μC.

للتحقق: Q1 + Q2 = 96 + 144 = 240 μC = Q0، وهذا يؤكد تحقق مبدأ حفظ الشحنة.

إذن فرق الجهد المشترك = 4.8 V، والشحنة على C1 = 96 μC، والشحنة على C2 = 144 μC.

[درس 1-4] سؤال تدريبي: فسّر لماذا يُعَدّ الفاراد (F) وحدة كبيرة جدًا من الناحية العملية، ولماذا تُستخدم في أغلب المكثّفات التجارية مضاعفات صغرى مثل الميكروفاراد (μF) أو النانوفاراد (nF) أو البيكوفاراد (pF) بدلًا من الفاراد نفسه؟
الإجابة النموذجية: الفاراد الواحد يعني أن المكثّف يخزّن شحنة مقدارها كولوم واحد مقابل كل فولت واحد من فرق الجهد بين لوحيه (C = Q/V)، وهذه كمية شحنة هائلة عمليًا لعنصر بحجم معقول.

فمثلًا، لو تخيّلنا مكثّفًا سعته 1 F مشحونًا عند فرق جهد معقول مثل 100 V، فإن الشحنة المخزَّنة عليه تكون:
Q = C × V = 1 × 100 = 100 C،
وهذه شحنة كبيرة جدًا مقارنة بالشحن التي تتعامل معها الدوائر الإلكترونية العادية (عادةً في حدود الميكروكولوم أو أقل).

كذلك فإن الطاقة المخزَّنة تصبح كبيرة جدًا: W = ½CV² = ½ × 1 × 100² = 5000 J، وهي طاقة كبيرة لعنصر إلكتروني صغير.

لتحقيق سعة قريبة من الفاراد الواحد فعليًا يحتاج المكثّف إلى لوحين بمساحة كبيرة جدًا أو مسافة فصل صغيرة جدًا بينهما (أو عازل ذي ثابت عزل كبير جدًا)، وهو أمر غير عملي في معظم التطبيقات الإلكترونية الصغيرة.

لذلك تُصنَّع أغلب المكثّفات التجارية بسعات أصغر بكثير من الفاراد، وتُقاس عادة بالميكروفاراد (10⁻⁶ F) أو النانوفاراد (10⁻⁹ F) أو حتى البيكوفاراد (10⁻¹² F)، وهي قيم تناسب الأحجام والتطبيقات العملية للدوائر الإلكترونية.

[درس 1-4] سؤال تدريبي: شُحن مكثّف C1 = 15 μF حتى بلغ فرق الجهد بين لوحيه 20 V، وشُحن مكثّف آخر C2 = 25 μF بشكل منفصل حتى بلغ فرق الجهد بين لوحيه 8 V. فُصل المكثّفان عن مصدريهما، ثم وُصلا معًا على التوازي بحيث تتلامس اللوحة الموجبة لأحدهما مع اللوحة السالبة للآخر (أي بقطبية متعاكسة). حدد فرق الجهد المشترك النهائي بين لوحي المكثّفين بعد الاتصال.
الإجابة النموذجية: الشحنة الابتدائية على كل مكثّف قبل الفصل:
Q1 = C1 × V1 = 15×10⁻⁶ × 20 = 300×10⁻⁶ C = 300 μC.
Q2 = C2 × V2 = 25×10⁻⁶ × 8 = 200×10⁻⁶ C = 200 μC.

بما أن التوصيل تم بقطبية متعاكسة (اللوحة الموجبة لأحدهما مقابل اللوحة السالبة للآخر)، فإن الشحنتين تتعاكسان في الإشارة عند حساب الشحنة الكلية الصافية بعد الاتصال. وبتطبيق مبدأ حفظ الشحنة على المنظومة المعزولة، تكون الشحنة الكلية الصافية بعد الاتصال:
Q_net = Q1 − Q2 = 300 − 200 = 100 μC.

السعة المكافئة للمكثّفين المتوازيين:
CT = C1 + C2 = 15 + 25 = 40 μF.

فرق الجهد المشترك النهائي:
V = Q_net / CT = (100×10⁻⁶) / (40×10⁻⁶) = 2.5 V.

وللتحقق: الشحنة على كل مكثّف بعد الاتصال تكون Q1' = C1×V = 15×10⁻⁶×2.5 = 37.5 μC، و Q2' = C2×V = 25×10⁻⁶×2.5 = 62.5 μC، ومجموعهما 37.5 + 62.5 = 100 μC = Q_net، وهذا يؤكد صحة الحل.

إذن فرق الجهد المشترك النهائي بين لوحي المكثّفين = 2.5 V.

[درس 2-4] سؤال تدريبي: فسّر لماذا تُساوي الطاقة المخزَّنة في مكثّف نصف حاصل ضرب الشحنة النهائية في فرق الجهد النهائي (W = ½QV)، وليس حاصل ضربهما مباشرة (QV)، مستعينًا بمنحنى العلاقة بين فرق الجهد V والشحنة Q أثناء عملية الشحن.
الإجابة النموذجية: أثناء شحن المكثّف، لا يبقى فرق الجهد بين لوحيه ثابتًا عند قيمته النهائية طوال عملية الشحن، بل يتزايد تدريجيًا وخطيًا من الصفر (عندما يكون المكثّف فارغًا من الشحنة) إلى القيمة النهائية V عندما تصل الشحنة إلى قيمتها النهائية Q (لأن V = Q/C، والعلاقة بين V و Q خطية).

الشغل المبذول لنقل عنصر صغير من الشحنة dQ عند فرق جهد لحظي v هو dW = v dQ، والطاقة الكلية المخزَّنة تساوي المساحة الكلية تحت منحنى V مقابل Q من الصفر حتى Q.

بما أن هذا المنحنى خط مستقيم يمر من نقطة الأصل (0,0) إلى النقطة (Q, V)، فإن هذه المساحة هي مساحة مثلث قائم الزاوية طوله Q وارتفاعه V، أي:
W = ½ × Q × V.

أما لو استخدمنا QV مباشرة، فهذا يكافئ افتراض أن فرق الجهد كان ثابتًا عند قيمته النهائية V طوال عملية الشحن، وهو غير صحيح؛ ولذلك فإن QV يمثّل ضعف الطاقة الفعلية المخزَّنة تقريبًا (مساحة المستطيل الكامل المحيط بالمثلث)، والقيمة الصحيحة هي نصف هذا المقدار: W = ½QV.

[درس 2-4] سؤال تدريبي: مكثّف سعته 470 μF شُحن حتى بلغ فرق الجهد بين لوحيه 25 V. احسب الطاقة المخزَّنة في المكثّف.
الإجابة النموذجية: تُستخدم العلاقة: W = ½CV².

بالتعويض: C = 470×10⁻⁶ F، V = 25 V.

W = ½ × 470×10⁻⁶ × 25² = ½ × 470×10⁻⁶ × 625.

470×10⁻⁶ × 625 = 293750×10⁻⁶ = 0.29375 J.

W = ½ × 0.29375 = 0.146875 J.

إذن الطاقة المخزَّنة W ≈ 0.147 J (أي حوالي 147 mJ).

[درس 2-4] سؤال تدريبي: يُمثَّل منحنى فرق الجهد V مقابل الشحنة Q لمكثّف يُشحَن تدريجيًا بخط مستقيم يمر من نقطة الأصل حتى النقطة (Q = 300 μC، V = 150 V). بيّن أن الطاقة المخزَّنة في المكثّف عند هذه الحالة تساوي 22.5 mJ، مستخدمًا مساحة المنطقة تحت المنحنى.
الإجابة النموذجية: الطاقة المخزَّنة في المكثّف تساوي المساحة تحت منحنى V مقابل Q، وهذا المنحنى خط مستقيم من نقطة الأصل إلى النقطة (300 μC، 150 V)، أي أن المساحة تحته هي مساحة مثلث قائم الزاوية قاعدته Q = 300×10⁻⁶ C وارتفاعه V = 150 V.

W = ½ × قاعدة × ارتفاع = ½ × Q × V = ½ × (300×10⁻⁶) × 150.

300×10⁻⁶ × 150 = 45000×10⁻⁶ = 0.045 J.

W = ½ × 0.045 = 0.0225 J = 22.5×10⁻³ J = 22.5 mJ.

وهذا يطابق القيمة المطلوب إثباتها: W = 22.5 mJ. ∎

[درس 2-4] سؤال تدريبي: يخزّن مكثّف طاقة مقدارها 8.0×10⁻³ J عندما يكون فرق الجهد بين لوحيه 40 V. حدد سعة هذا المكثّف.
الإجابة النموذجية: تُستخدم العلاقة: W = ½CV²، ومنها: C = 2W / V².

بالتعويض: W = 8.0×10⁻³ J، V = 40 V، V² = 1600 V².

C = (2 × 8.0×10⁻³) / 1600 = (16×10⁻³) / 1600 = 1.0×10⁻⁵ F.

إذن سعة المكثّف C = 1.0×10⁻⁵ F = 10 μF.

[درس 2-4] سؤال تدريبي: يحمل مكثّف سعته 100 μF شحنة مقدارها 2.0 mC. احسب الطاقة المخزَّنة في المكثّف مستخدمًا العلاقة W = Q²/2C.
الإجابة النموذجية: تُستخدم العلاقة: W = Q² / (2C).

بالتعويض: Q = 2.0×10⁻³ C، C = 100×10⁻⁶ F.

Q² = (2.0×10⁻³)² = 4.0×10⁻⁶ C².

2C = 2 × 100×10⁻⁶ = 2.0×10⁻⁴ F.

W = (4.0×10⁻⁶) / (2.0×10⁻⁴) = 2.0×10⁻² J.

إذن الطاقة المخزَّنة W = 2.0×10⁻² J = 20 mJ.

[درس 2-4] سؤال تدريبي: شبكة من المكثّفات لها سعة مكافئة CT = 15 μF، وُصلت بمصدر قوة دافعة كهربائية قدره 12 V حتى تم شحنها بالكامل. احسب الطاقة الكلية المخزَّنة في هذه الشبكة.
الإجابة النموذجية: عند اكتمال الشحن يكون فرق الجهد بين طرفي الشبكة مساوياً للقوة الدافعة الكهربائية للمصدر (بافتراض إهمال أي مقاومة داخلية عند الحالة المستقرة النهائية): V = 12 V.

تُستخدم العلاقة: W = ½ CT V².

W = ½ × 15×10⁻⁶ × 12² = ½ × 15×10⁻⁶ × 144.

15×10⁻⁶ × 144 = 2160×10⁻⁶ = 2.16×10⁻³ J.

W = ½ × 2.16×10⁻³ = 1.08×10⁻³ J.

إذن الطاقة الكلية المخزَّنة في الشبكة W = 1.08×10⁻³ J = 1.08 mJ.

[درس 3-4] سؤال تدريبي: عند توصيل عدة مكثّفات على التوازي بين نفس النقطتين في الدائرة، فإن: (اختر الإجابة الصحيحة)
(أ) الشحنة على كل مكثّف متساوية، وفرق الجهد يتوزّع بينها
(ب) فرق الجهد بين لوحي كل مكثّف يساوي فرق الجهد الكلي بين النقطتين، بينما تتوزّع الشحنة الكلية بين المكثّفات
(ج) السعة المكافئة أصغر من أصغر سعة فردية في المجموعة
(د) التيار اللحظي المار في كل فرع متساوٍ دائمًا بغض النظر عن قيمة سعة المكثّف
الإجابة النموذجية: في التوصيل على التوازي، تكون جميع المكثّفات موصولة بين نفس النقطتين (نفس العقدتين) في الدائرة، وبما أن فرق الجهد بين أي نقطتين في الدائرة له قيمة واحدة محددة، فإن فرق الجهد بين لوحي كل مكثّف من المكثّفات المتوازية يساوي فرق الجهد الكلي V بين تلك النقطتين.

أما الشحنة الكلية القادمة من المصدر فتتوزّع بين المكثّفات بنسب تتناسب مع سعة كل منها (Q = CV لكل مكثّف على حدة، وبسعات مختلفة تكون الشحن مختلفة عند نفس V).

الخيار (أ) خطأ لأن الشحنة ليست متساوية بل فرق الجهد هو المتساوي. الخيار (ج) خطأ لأن السعة المكافئة للتوازي أكبر من أكبر سعة فردية (CT = C1+C2+…)، لا أصغر. الخيار (د) خطأ لأن التيار في كل فرع يتناسب مع سعة ذلك الفرع وليس متساويًا بالضرورة.

الإجابة الصحيحة: (ب).

[درس 3-4] سؤال تدريبي: وُصلت ثلاثة مكثّفات سعاتها 2 μF و4 μF و6 μF على التوازي، ثم وُصلت مجموعة المكثّفات بمصدر جهد ثابت قدره 9 V. احسب: (أ) السعة المكافئة للمجموعة، (ب) الشحنة الكلية المسحوبة من المصدر، (ج) الشحنة المخزَّنة على كل مكثّف على حدة.
الإجابة النموذجية: (أ) في التوصيل على التوازي: CT = C1 + C2 + C3 = 2 + 4 + 6 = 12 μF.

(ب) الشحنة الكلية: Q_total = CT × V = 12×10⁻⁶ × 9 = 108×10⁻⁶ C = 108 μC.

(ج) فرق الجهد على كل مكثّف في التوازي يساوي فرق الجهد الكلي V = 9 V، لذا:
Q1 = C1 × V = 2×10⁻⁶ × 9 = 18×10⁻⁶ C = 18 μC.
Q2 = C2 × V = 4×10⁻⁶ × 9 = 36×10⁻⁶ C = 36 μC.
Q3 = C3 × V = 6×10⁻⁶ × 9 = 54×10⁻⁶ C = 54 μC.

للتحقق: Q1+Q2+Q3 = 18+36+54 = 108 μC = Q_total، وهذا يتفق مع الإجابة في الفقرة (ب).

[درس 3-4] سؤال تدريبي: مكثّفان سعتاهما C1 و C2 موصولان على التوازي بين نقطتين فرق الجهد بينهما V. استنتج، انطلاقًا من مبدأ حفظ الشحنة وتعريف السعة، العلاقة CT = C1 + C2 لسعة المكثّفين المكافئة.
الإجابة النموذجية: في التوصيل على التوازي، يكون فرق الجهد بين لوحي كل مكثّف مساويًا لفرق الجهد الكلي V بين النقطتين (لأن كلا المكثّفين موصول مباشرة بين نفس النقطتين).

الشحنة على كل مكثّف: Q1 = C1 V، Q2 = C2 V.

الشحنة الكلية المسحوبة من المصدر هي مجموع الشحنتين (بما أن الشحنة كمية إضافية/محفوظة، ولا يوجد مسار آخر لتخزينها):
Q_total = Q1 + Q2 = C1V + C2V = (C1 + C2) V.

من ناحية أخرى، يمكن التعبير عن الشحنة الكلية بدلالة سعة مكافئة واحدة CT توصَل بنفس فرق الجهد V وتخزّن نفس الشحنة الكلية:
Q_total = CT V.

بمساواة الطرفين: CT V = (C1 + C2) V، وبما أن V ≠ 0 يمكن قسمة الطرفين عليها:
CT = C1 + C2. ∎

[درس 3-4] سؤال تدريبي: مكثّفان سعتاهما 6 μF و3 μF موصولان على التوالي، وهذه المجموعة السلسلة موصولة بدورها على التوازي مع مكثّف ثالث سعته 5 μF. حدد السعة المكافئة للشبكة الكلية.
الإجابة النموذجية: أولًا نوجد السعة المكافئة لفرع التوالي المكوَّن من 6 μF و3 μF:

1/Cs = 1/6 + 1/3 = 1/6 + 2/6 = 3/6 = 1/2.

Cs = 2 μF.

الآن هذا الفرع (Cs = 2 μF) موصول على التوازي مع المكثّف الثالث C3 = 5 μF، فتكون السعة المكافئة الكلية:

CT = Cs + C3 = 2 + 5 = 7 μF.

إذن السعة المكافئة للشبكة الكلية CT = 7 μF.

[درس 3-4] سؤال تدريبي: مكثّفان موصولان على التوازي، سعة أحدهما 8 μF، والسعة المكافئة لمجموعهما 20 μF. احسب سعة المكثّف الآخر، ثم احسب الشحنة المخزَّنة عليه عند توصيل المجموعة بفرق جهد قدره 15 V.
الإجابة النموذجية: في التوصيل على التوازي: CT = C1 + C2.

C2 = CT − C1 = 20 − 8 = 12 μF.

الشحنة على المكثّف الثاني عند فرق جهد V = 15 V (وهو نفس فرق الجهد الكلي، لأنه توصيل توازٍ):

Q2 = C2 × V = 12×10⁻⁶ × 15 = 180×10⁻⁶ C = 180 μC.

إذن سعة المكثّف الآخر = 12 μF، والشحنة المخزَّنة عليه = 180 μC.

[درس 3-4] سؤال تدريبي: وُصلت ثلاثة مكثّفات متطابقة سعة كل منها 10 μF على التوازي. السعة المكافئة لهذه المجموعة تساوي: (اختر الإجابة الصحيحة)
(أ) 3.33 μF
(ب) 10 μF
(ج) 20 μF
(د) 30 μF
الإجابة النموذجية: في التوصيل على التوازي تُجمع السعات مباشرة: CT = C1 + C2 + C3 = 10 + 10 + 10 = 30 μF.

الخيار (أ) 3.33 μF ينتج عن الخلط مع قانون التوالي (1/CT = 1/10+1/10+1/10 = 3/10 → CT=3.33μF) وهو خطأ لأن التوصيل هنا توازٍ. الخيار (ب) يتجاهل وجود ثلاثة مكثّفات ويكرر قيمة واحدة فقط. الخيار (ج) ناتج عن جمع مكثّفين فقط من أصل ثلاثة.

الإجابة الصحيحة: (د) 30 μF.

[درس 4-4] سؤال تدريبي: عند توصيل مكثّفين على التوالي وشحنهما من مصدر جهد ثابت، يكون: (اختر الإجابة الصحيحة)
(أ) فرق الجهد على كل مكثّف متساويًا، والشحنة تتوزّع بينهما
(ب) الشحنة على كل مكثّف متساوية، بينما يتوزّع فرق الجهد الكلي بين المكثّفين
(ج) السعة المكافئة أكبر من أكبر سعة فردية في المجموعة
(د) الشحنة الكلية على المجموعة تساوي مجموع شحنتي المكثّفين
الإجابة النموذجية: في التوصيل على التوالي، يكون المكثّفان موصولين في مسار واحد، واللوحة الوسطى المشتركة بينهما (المتصلة كهربائيًا ببعضها فقط، دون اتصال مباشر بالمصدر) تكتسب شحنة مستحثة تساوي في المقدار شحنة اللوحتين الخارجيتين، لذا يحمل المكثّفان نفس مقدار الشحنة Q.

أما فرق الجهد الكلي للمصدر فيتوزّع بين المكثّفين (V = V1 + V2)، وليس متساويًا على كل منهما إلا في الحالة الخاصة حيث تكون السعتان متساويتين.

الخيار (أ) و(د) خطأ للأسباب أعلاه، والخيار (ج) خطأ لأن السعة المكافئة للتوالي دائمًا أصغر من أصغر سعة فردية في المجموعة، وليست أكبر.

الإجابة الصحيحة: (ب).

[درس 4-4] سؤال تدريبي: مكثّفان سعتاهما 12 μF و4 μF موصولان على التوالي، ووُصلت المجموعة بمصدر جهد ثابت قدره 20 V. احسب: (أ) السعة المكافئة، (ب) الشحنة المخزَّنة على كل مكثّف، (ج) فرق الجهد بين لوحي كل مكثّف على حدة.
الإجابة النموذجية: (أ) في التوصيل على التوالي: 1/CT = 1/C1 + 1/C2 = 1/12 + 1/4 = 1/12 + 3/12 = 4/12 = 1/3.

CT = 3 μF.

(ب) الشحنة على كل مكثّف في التوالي متساوية وتساوي شحنة السعة المكافئة نفسها:
Q = CT × V = 3×10⁻⁶ × 20 = 60×10⁻⁶ C = 60 μC (على كل من المكثّفين).

(ج) فرق الجهد على كل مكثّف: V1 = Q/C1 = (60×10⁻⁶)/(12×10⁻⁶) = 5 V.
V2 = Q/C2 = (60×10⁻⁶)/(4×10⁻⁶) = 15 V.

للتحقق: V1 + V2 = 5 + 15 = 20 V، وهو فرق الجهد الكلي للمصدر، مما يؤكد صحة الحل.

[درس 4-4] سؤال تدريبي: بيّن أن السعة المكافئة لمكثّفين سعتاهما 6 μF و3 μF موصولين على التوالي تساوي 2 μF.
الإجابة النموذجية: في التوصيل على التوالي: 1/CT = 1/C1 + 1/C2.

1/CT = 1/6 + 1/3 = 1/6 + 2/6 = 3/6 = 1/2.

CT = 1/(1/2) = 2 μF.

وهذا يطابق القيمة المطلوب إثباتها: CT = 2 μF. ∎

[درس 4-4] سؤال تدريبي: فسّر لماذا يؤدي توصيل مكثّف إضافي على التوالي مع مكثّف موجود دائمًا إلى تقليل السعة المكافئة للمجموعة إلى قيمة أصغر من سعة أصغر مكثّف في المجموعة، وذلك دون استخدام أرقام.
الإجابة النموذجية: في التوصيل على التوالي، الشحنة Q على جميع المكثّفات المتوالية واحدة (نفس المقدار)، بينما يتوزّع فرق الجهد الكلي V بين المكثّفات: V = V1 + V2 + …

بما أن فرق الجهد الكلي هو مجموع فروق الجهد الفردية، فإن فرق الجهد الكلي اللازم لدفع نفس مقدار الشحنة Q عبر المجموعة يكون أكبر من فرق الجهد اللازم لأي مكثّف منفرد بمفرده عند نفس الشحنة Q (لأن كل مكثّف إضافي يضيف حصته الخاصة من فرق الجهد V = Q/C فوق ما هو موجود).

وبما أن السعة المكافئة تُعرَّف بـ CT = Q/V، فإن زيادة V (المقام) عند ثبات Q (البسط) تعني بالضرورة نقصان CT.

ولذلك فإن إضافة أي مكثّف جديد على التوالي (بغض النظر عن قيمته) تزيد فرق الجهد اللازم لكل وحدة شحنة، فتقل السعة المكافئة للمجموعة عن سعة أي مكثّف فردي فيها، بما في ذلك أصغرها.

[درس 4-4] سؤال تدريبي: مكثّفان موصولان على التوالي، السعة المكافئة لهما 2.4 μF، وسعة أحدهما 4 μF. حدد سعة المكثّف الآخر.
الإجابة النموذجية: في التوصيل على التوالي: 1/CT = 1/C1 + 1/C2، ومنها: 1/C2 = 1/CT − 1/C1.

بالتعويض: 1/CT = 1/2.4، و1/C1 = 1/4.

لتسهيل الحساب نكتب الكسور بمقام مشترك؛ بما أن 2.4 = 12/5 فإن 1/2.4 = 5/12، و1/4 = 3/12.

1/C2 = 5/12 − 3/12 = 2/12 = 1/6.

C2 = 6 μF.

للتحقق: 1/4 + 1/6 = 3/12 + 2/12 = 5/12 = 1/2.4، أي CT = 2.4 μF، وهذا يطابق المعطى. إذن سعة المكثّف الآخر = 6 μF.

[درس 4-4] سؤال تدريبي: لديك مكثّفان سعتاهما 5 μF و20 μF. قارن بين السعة المكافئة الناتجة عند توصيلهما على التوالي والسعة المكافئة الناتجة عند توصيلهما على التوازي، بحساب كلتا القيمتين.
الإجابة النموذجية: عند التوصيل على التوازي: CT(توازي) = C1 + C2 = 5 + 20 = 25 μF.

عند التوصيل على التوالي: 1/CT(توالي) = 1/C1 + 1/C2 = 1/5 + 1/20 = 4/20 + 1/20 = 5/20 = 1/4.

CT(توالي) = 4 μF.

المقارنة: السعة المكافئة في حالة التوازي (25 μF) أكبر من أكبر سعة فردية في المجموعة (20 μF)، بينما السعة المكافئة في حالة التوالي (4 μF) أصغر من أصغر سعة فردية في المجموعة (5 μF). أي أن التوصيل على التوازي يزيد السعة الكلية، بينما التوصيل على التوالي يُنقصها دائمًا.

[درس 5-4] سؤال تدريبي: عند تحليل شبكة مركّبة من المكثّفات تحتوي على مجموعات متوالية ومتوازية معًا لإيجاد سعتها المكافئة، فإن الأسلوب الصحيح هو: (اختر الإجابة الصحيحة)
(أ) جمع كل السعات مباشرة بغض النظر عن طريقة توصيلها
(ب) البدء بتبسيط أصغر المجموعات الفرعية (المتوالية أو المتوازية بوضوح) إلى سعة مكافئة واحدة، ثم تكرار العملية تدريجيًا حتى تبقى سعة مكافئة واحدة للشبكة كاملة
(ج) استخدام قانون التوالي فقط بغض النظر عن طريقة التوصيل الفعلية
(د) حساب متوسط جميع السعات الفردية في الشبكة
الإجابة النموذجية: الشبكات المركّبة (التي تجمع توصيلات متوالية ومتوازية معًا) تُحلَّل بتحديد أصغر مجموعة فرعية واضحة التوصيل (توالٍ خالص أو توازٍ خالص) أولًا، وإيجاد سعتها المكافئة باستخدام القانون المناسب لها، ثم معاملة هذه السعة المكافئة كمكثّف واحد ضمن بقية الشبكة، وتكرار هذه الخطوات تدريجيًا (من الداخل إلى الخارج) حتى تختزل الشبكة بأكملها إلى سعة مكافئة واحدة.

الخيار (أ) خطأ لأن الجمع المباشر يصح فقط للتوازي وليس لكل الحالات. الخيار (ج) خطأ لنفس السبب مع التوالي. الخيار (د) لا أساس فيزيائيًا له إطلاقًا.

الإجابة الصحيحة: (ب).

[درس 5-4] سؤال تدريبي: في شبكة مكثّفات، مكثّفان C1 = 4 μF و C2 = 12 μF موصولان على التوالي في فرع واحد، وهذا الفرع موصول على التوازي مع مكثّف ثالث C3 = 6 μF. وُصلت الشبكة كاملة بمصدر جهد ثابت قدره 24 V. احسب: (أ) السعة المكافئة للشبكة، (ب) الشحنة الكلية المسحوبة من المصدر، (ج) الشحنة المخزَّنة على المكثّف C3، (د) الشحنة المخزَّنة على كل من C1 و C2.
الإجابة النموذجية: (أ) أولًا نوجد السعة المكافئة لفرع التوالي (C1 مع C2):
1/Cs = 1/C1 + 1/C2 = 1/4 + 1/12 = 3/12 + 1/12 = 4/12 = 1/3.
Cs = 3 μF.

هذا الفرع (Cs = 3 μF) موصول على التوازي مع C3 = 6 μF، فتكون السعة المكافئة الكلية للشبكة:
CT = Cs + C3 = 3 + 6 = 9 μF.

(ب) الشحنة الكلية المسحوبة من المصدر:
Q_total = CT × V = 9×10⁻⁶ × 24 = 216×10⁻⁶ C = 216 μC.

(ج) فرع C3 موصول مباشرة بين طرفي المصدر (توازٍ)، لذا فرق الجهد عليه يساوي 24 V كاملة:
Q3 = C3 × V = 6×10⁻⁶ × 24 = 144×10⁻⁶ C = 144 μC.

(د) فرع التوالي (C1 مع C2) يأخذ الشحنة المتبقية، وبما أنه فرع توازٍ آخر موصول أيضًا عند نفس فرق الجهد 24 V:
Qs = Cs × V = 3×10⁻⁶ × 24 = 72×10⁻⁶ C = 72 μC.

وبما أن C1 و C2 موصولان على التوالي، فإن الشحنة عليهما متساوية وتساوي شحنة الفرع نفسه:
Q1 = Q2 = 72 μC.

للتحقق: Q3 + Qs = 144 + 72 = 216 μC = Q_total، وهذا يتفق مع الإجابة في الفقرة (ب)، مما يؤكد صحة توزيع الشحنة وفق مبدأ حفظ الشحنة.

[درس 5-4] سؤال تدريبي: شبكة مكثّفات موصولة بمصدر قوة دافعة كهربائية قدره 15 V، وتتكوّن من فرعين متوازيين: الفرع A عبارة عن مكثّف واحد سعته 8 μF، والفرع B عبارة عن مكثّفين سعة كل منهما 4 μF موصولين على التوالي. بيّن أن السعة المكافئة للشبكة كاملة تساوي 10 μF، ثم احسب الشحنة الكلية المسحوبة من المصدر.
الإجابة النموذجية: أولًا نوجد السعة المكافئة للفرع B (مكثّفان متطابقان سعة كل منهما 4 μF موصولان على التوالي):
1/Cb = 1/4 + 1/4 = 2/4 = 1/2.
Cb = 2 μF.

الفرعان A (8 μF) وB (Cb = 2 μF) موصولان على التوازي بين نفس طرفي المصدر، لذا:
CT = CA + Cb = 8 + 2 = 10 μF.

وهذا يطابق القيمة المطلوب إثباتها: CT = 10 μF. ∎

الشحنة الكلية المسحوبة من المصدر:
Q_total = CT × V = 10×10⁻⁶ × 15 = 150×10⁻⁶ C = 150 μC.

[درس 5-4] سؤال تدريبي: بالنسبة لشبكة المكثّفات الموصوفة في السؤال السابق (CT = 10 μF، الفرع A سعته 8 μF، مصدر جهد 15 V)، حدد الطاقة الكلية المخزَّنة في الشبكة، ثم حدد الطاقة المخزَّنة في الفرع A وحده.
الإجابة النموذجية: الطاقة الكلية المخزَّنة في الشبكة كاملة باستخدام السعة المكافئة:
W_total = ½ CT V² = ½ × 10×10⁻⁶ × 15² = ½ × 10×10⁻⁶ × 225 = ½ × 2250×10⁻⁶ = 1125×10⁻⁶ J = 1.125×10⁻³ J = 1.125 mJ.

الفرع A موصول مباشرة بين طرفي المصدر (فرع توازٍ)، لذا فرق الجهد عليه أيضًا 15 V كاملة، والطاقة المخزَّنة فيه:
W_A = ½ CA V² = ½ × 8×10⁻⁶ × 225 = ½ × 1800×10⁻⁶ = 900×10⁻⁶ J = 0.9×10⁻³ J = 0.9 mJ.

للتحقق: طاقة الفرع B تكون W_B = W_total − W_A = 1.125 − 0.9 = 0.225 mJ، وهذا يطابق الحساب المباشر W_B = ½ Cb V² = ½ × 2×10⁻⁶ × 225 = 225×10⁻⁶ J = 0.225 mJ، مما يؤكد اتساق النتائج.

إذن الطاقة الكلية في الشبكة = 1.125 mJ، والطاقة في الفرع A وحده = 0.9 mJ.

[درس 5-4] سؤال تدريبي: استنتج العلاقة بين السعة المكافئة لشبكة مكثّفات والطاقة الكلية المخزَّنة فيها: إذا تمت مضاعفة السعة المكافئة CT لشبكة مكثّفات (بإعادة توصيلها) مع بقاء فرق الجهد الكلي V المطبَّق عليها ثابتًا، كيف تتغير الطاقة الكلية المخزَّنة؟ فسّر إجابتك.
الإجابة النموذجية: الطاقة الكلية المخزَّنة في شبكة مكثّفات تُعطى بالعلاقة: W = ½ CT V².

عند ثبات فرق الجهد الكلي V، تكون العلاقة بين W وCT علاقة طردية خطية (W تتناسب طرديًا مع CT مباشرة، بما أن V² يبقى ثابتًا ولا يتغير).

فإذا تضاعفت السعة المكافئة (أصبحت 2CT مع بقاء V ثابتًا):
W' = ½ (2CT) V² = 2 × (½ CT V²) = 2W.

أي أن الطاقة الكلية المخزَّنة تتضاعف هي الأخرى (تصبح ضعف قيمتها الأصلية).

السبب فيزيائيًا: زيادة السعة المكافئة (عند ثبات V) تعني قدرة أكبر على تخزين شحنة أكبر عند نفس فرق الجهد (بما أن Q = CT V)، وبالتالي تُخزَّن طاقة أكبر في المجال الكهربائي بين لوحات الشبكة.

[درس 5-4] سؤال تدريبي: في شبكة مكثّفات، مكثّفان C1 = 2 μF و C2 = 3 μF موصولان على التوازي، وهذه المجموعة المتوازية موصولة على التوالي مع مكثّف ثالث C3 = 5 μF. السعة المكافئة للشبكة كاملة تساوي: (اختر الإجابة الصحيحة)
(أ) 10 μF
(ب) 5 μF
(ج) 2.5 μF
(د) 0.4 μF
الإجابة النموذجية: أولًا نوجد سعة المجموعة المتوازية (C1 مع C2):
Cp = C1 + C2 = 2 + 3 = 5 μF.

الآن Cp (= 5 μF) موصولة على التوالي مع C3 = 5 μF:
1/CT = 1/Cp + 1/C3 = 1/5 + 1/5 = 2/5.

CT = 5/2 = 2.5 μF.

الخيار (أ) 10 μF ينتج عن جمع الثلاث سعات مباشرة وكأنها كلها متوازية، وهو خطأ لأن C3 موصولة على التوالي مع المجموعة. الخيار (ب) 5 μF يتجاهل وجود C3 تمامًا في الحساب النهائي. الخيار (د) 0.4 μF ينتج عن خطأ في عكس البسط والمقام عند حساب CT من المقلوب 2/5.

الإجابة الصحيحة: (ج) 2.5 μF.

[درس 6-4] سؤال تدريبي: ثابت الزمن τ لدائرة تفريغ مكثّف عبر مقاومة (τ = RC) يمثّل: (اختر الإجابة الصحيحة)
(أ) الزمن اللازم لتفريغ المكثّف بالكامل تمامًا (حتى تصبح شحنته صفرًا)
(ب) الزمن اللازم لتناقص الشحنة (أو فرق الجهد) على المكثّف إلى نحو 37% (أي 1/e) من قيمتها الابتدائية
(ج) الزمن اللازم لمضاعفة الشحنة على المكثّف
(د) مقلوب معدل تناقص الشحنة عند بداية التفريغ مباشرة فقط
الإجابة النموذجية: من العلاقة الأسّية للتفريغ: Q = Q0 e^(−t/RC). عندما يكون الزمن المنقضي t مساويًا لثابت الزمن τ = RC بالضبط، فإن:

Q/Q0 = e^(−τ/τ) = e^(−1) ≈ 0.368 ≈ 37%.

أي أن τ هو الزمن اللازم لتناقص الشحنة (وكذلك فرق الجهد، لأن V يتناسب طرديًا مع Q عند سعة ثابتة) إلى نحو 37% من قيمتها الابتدائية، وليس إلى الصفر تمامًا (نظريًا لا تصل الدالة الأسّية للصفر في زمن منتهٍ)، وليس هو زمن مضاعفة الشحنة (فالشحنة تتناقص لا تتضاعف أثناء التفريغ).

الإجابة الصحيحة: (ب).

[درس 6-4] سؤال تدريبي: يُفرَّغ مكثّف سعته 470 μF عبر مقاومة قدرها 2.2 kΩ. احسب ثابت الزمن τ لدائرة التفريغ هذه.
الإجابة النموذجية: ثابت الزمن يُعطى بالعلاقة: τ = RC.

بالتعويض: R = 2.2×10³ Ω، C = 470×10⁻⁶ F.

τ = 2.2×10³ × 470×10⁻⁶ = 2200 × 0.00047.

2200 × 0.00047 = 1.034 s.

إذن ثابت الزمن τ ≈ 1.03 s.

[درس 6-4] سؤال تدريبي: شُحن مكثّف حتى بلغ فرق الجهد بين لوحيه 9.0 V، ثم بدأ يتفرّغ عبر مقاومة بحيث كان ثابت الزمن لدائرة التفريغ τ = 4.0 s. احسب الزمن اللازم حتى يتناقص فرق الجهد بين لوحي المكثّف إلى 3.0 V.
الإجابة النموذجية: تُستخدم العلاقة الأسّية للتفريغ: V = V0 e^(−t/τ).

بالتعويض: V0 = 9.0 V، V = 3.0 V.

3.0 = 9.0 × e^(−t/4.0).

e^(−t/4.0) = 3.0/9.0 = 1/3.

بأخذ اللوغاريتم الطبيعي للطرفين:
−t/4.0 = ln(1/3) = −ln(3) = −1.0986.

t = 4.0 × 1.0986 = 4.394 s.

إذن الزمن اللازم ≈ 4.4 s.

[درس 6-4] سؤال تدريبي: مكثّف سعته 100 μF يُفرَّغ عبر مقاومة R. وُجد أن الشحنة عليه تناقصت إلى نصف قيمتها الابتدائية بعد مرور 3.5 s من بدء التفريغ. حدد قيمة المقاومة R.
الإجابة النموذجية: تُستخدم العلاقة الأسّية للتفريغ: Q = Q0 e^(−t/RC).

عند t = 3.5 s تكون Q = Q0/2، أي Q/Q0 = 0.5.

0.5 = e^(−3.5/RC).

بأخذ اللوغاريتم الطبيعي للطرفين:
ln(0.5) = −3.5/RC → −0.6931 = −3.5/RC.

RC = 3.5/0.6931 = 5.05 s.

R = (RC)/C = 5.05/(100×10⁻⁶) = 5.05×10⁴ Ω.

إذن مقاومة المقاومة R ≈ 5.05×10⁴ Ω = 50.5 kΩ.

[درس 6-4] سؤال تدريبي: فسّر، باستخدام العلاقة τ = RC والمنحنى الأسّي لتناقص الشحنة مع الزمن أثناء تفريغ مكثّف، أثر مضاعفة قيمة المقاومة R (مع بقاء سعة المكثّف C ثابتة) على معدل تفريغ المكثّف والزمن اللازم لتفريغه إلى نسبة معينة من شحنته الابتدائية.
الإجابة النموذجية: ثابت الزمن يُعطى بالعلاقة τ = RC. فإذا تضاعفت قيمة المقاومة R مع بقاء C ثابتة، فإن ثابت الزمن الجديد τ' = (2R)C = 2τ، أي يتضاعف هو الآخر.

فيزيائيًا، زيادة المقاومة R تحدّ من مقدار التيار اللحظي الذي يمكن أن يتدفق من المكثّف عند أي فرق جهد لحظي معيّن (I = V/R)، وبما أن التيار هو معدل تدفق الشحنة (I = −dQ/dt)، فإن تيارًا أصغر عند كل لحظة يعني أن الشحنة تتناقص بمعدل أبطأ.

على المنحنى الأسّي لـ Q مقابل الزمن t، يظهر هذا كمنحنى أكثر تسطّحًا (أقل انحدارًا في بدايته) يستغرق زمنًا أطول ليصل إلى نفس النسبة من الشحنة الابتدائية (مثلًا 37% عند τ، أو 50% عند نحو 0.693τ). فبما أن τ تضاعف، فإن الزمن اللازم لبلوغ أي نسبة معيّنة من Q0 يتضاعف أيضًا (لأن t = τ × ln(Q0/Q) لأي نسبة ثابتة).

باختصار: مضاعفة R تُبطئ عملية التفريغ وتُضاعف الزمن اللازم للوصول إلى أي نسبة معيّنة من الشحنة الابتدائية، دون أن تُغيّر شكل المنحنى الأسّي من حيث طبيعته (يبقى أسّيًا تناقصيًا)، بل تُمدّده أفقيًا على محور الزمن.

[درس 6-4] سؤال تدريبي: مكثّف يتفرّغ عبر مقاومة بثابت زمن τ. أقل عدد صحيح من أضعاف ثابت الزمن τ يلزم مروره حتى تصبح الشحنة المتبقية على المكثّف أقل من 10% من شحنته الابتدائية هو: (اختر الإجابة الصحيحة)
(أ) 1
(ب) 2
(ج) 3
(د) 5
الإجابة النموذجية: النسبة المتبقية من الشحنة بعد مرور n من أضعاف ثابت الزمن (t = nτ) تُعطى بالعلاقة: Q/Q0 = e^(−n).

عند n = 2: Q/Q0 = e^(−2) = 0.135 = 13.5%، وهذه القيمة أكبر من 10%، أي لم تصل النسبة المطلوبة بعد.

عند n = 3: Q/Q0 = e^(−3) = 0.0498 ≈ 5.0%، وهذه القيمة أقل من 10%.

إذن أقل عدد صحيح من أضعاف τ تصبح عنده النسبة المتبقية أقل من 10% هو 3 (لأنها كانت لا تزال أكبر من 10% عند n = 2، وأصبحت أقل من 10% عند n = 3).

الإجابة الصحيحة: (ج) 3.

[درس 1-5] سؤال تدريبي: صف نمط خطوط المجال المغناطيسي الناتج حول سلك مستقيم طويل يحمل تيارًا كهربائيًا ثابتًا، مبينًا في وصفك: (1) شكل خطوط المجال بالنسبة للسلك، (2) كيف يتغيّر تباعد هذه الخطوط كلما ابتعدنا عن السلك، وماذا يدل ذلك على كثافة الفيض المغناطيسي.
الإجابة النموذجية: خطوط المجال المغناطيسي حول سلك مستقيم طويل يحمل تيارًا كهربائيًا تكون على هيئة دوائر متحدة المركز (circles)، مركزها على السلك نفسه، وتقع كل دائرة منها في مستوٍ عمودي على اتجاه السلك (عمودي على اتجاه سريان التيار).

اتجاه هذه الدوائر يُحدَّد بقاعدة قبضة اليد اليمنى: إذا أمسكت السلك بيدك اليمنى بحيث يشير الإبهام الممدود إلى اتجاه سريان التيار الاصطلاحي، فإن بقية أصابع اليد المنحنية حول السلك تشير إلى اتجاه دوران خطوط المجال المغناطيسي حوله.

كلما ابتعدنا عن السلك يزداد التباعد بين الدوائر المتتالية (أي تقل كثافة الخطوط لكل وحدة مساحة)، وهذا يدل على أن كثافة الفيض المغناطيسي B تقل تدريجيًا كلما زادت المسافة عن السلك، وتكون أكبر ما يمكن عند نقاط قريبة جدًا من سطح السلك.

[درس 1-5] سؤال تدريبي: يحمل سلك مستقيم طويل تيارًا كهربائيًا يخرج عموديًا من صفحة الورقة باتجاه القارئ (⊙). حدد اتجاه المجال المغناطيسي الناتج عن هذا التيار عند نقطة تقع مباشرة إلى يمين السلك، وفي نفس مستوى صفحة الورقة. (اختر الإجابة الصحيحة)
(أ) نحو الأسفل، داخل مستوى الصفحة
(ب) نحو الأعلى، داخل مستوى الصفحة
(ج) بعيدًا عن السلك (نحو اليمين)
(د) نحو السلك (نحو اليسار)
الإجابة النموذجية: بتطبيق قاعدة قبضة اليد اليمنى: نوجّه إبهام اليد اليمنى نحو القارئ (خارج الصفحة، وهو اتجاه التيار المعطى)، فتنحني بقية الأصابع حول السلك في اتجاه عكس عقارب الساعة كما يراها القارئ.

عند نقطة تقع مباشرة إلى يمين السلك، فإن اتجاه الدائرة المماسة لخط المجال عند تلك النقطة (وفق الدوران عكس عقارب الساعة) يكون متجهًا إلى الأعلى داخل مستوى الصفحة.

الإجابة الصحيحة: (ب) نحو الأعلى، داخل مستوى الصفحة.

[درس 1-5] سؤال تدريبي: يمر تيار كهربائي في لفات سولينويد (ملف حلزوني). عند النظر إلى أحد طرفي السولينويد من الخارج (أي والناظر يواجه ذلك الطرف مباشرة)، يبدو أن التيار في اللفات يسري في اتجاه عقارب الساعة. حدد نوع القطب المغناطيسي (شمالي N أم جنوبي S) الذي يتكوّن عند هذا الطرف من السولينويد، مبررًا إجابتك باستخدام قاعدة قبضة اليد اليمنى.
الإجابة النموذجية: نطبّق قاعدة قبضة اليد اليمنى على لفات السولينويد: تُلَفّ أصابع اليد اليمنى في اتجاه سريان التيار في اللفات (هنا: اتجاه عقارب الساعة كما يراها الناظر عند هذا الطرف)، فيشير الإبهام الممدود إلى اتجاه المجال المغناطيسي الداخلي للسولينويد على طول محوره.

عند لفّ الأصابع في اتجاه عقارب الساعة (كما يراها الناظر الواقف عند هذا الطرف ومواجهًا له)، يشير إبهام اليد اليمنى مبتعدًا عن الناظر، أي إلى داخل السولينويد (بعيدًا عن هذا الطرف). وهذا يعني أن المجال المغناطيسي الداخلي يتجه من هذا الطرف نحو الطرف الآخر، أي أن خطوط المجال "تدخل" السولينويد من عند هذا الطرف.

بما أن خطوط المجال المغناطيسي تخرج دائمًا من القطب الشمالي (N) وتدخل عند القطب الجنوبي (S)، فإن الطرف الذي يبدو عنده التيار في اتجاه عقارب الساعة هو القطب الجنوبي (S).

[درس 1-5] سؤال تدريبي: بالنسبة للسولينويد الموصوف في السؤال السابق، إذا عُكس اتجاه سريان التيار في لفاته (مع إبقاء شدة التيار وعدد اللفات ثابتين)، صف ماذا يحدث لكلٍّ من: (1) نوعي القطبين المتكوّنين عند طرفي السولينويد، (2) اتجاه خطوط المجال المغناطيسي داخل السولينويد وخارجه.
الإجابة النموذجية: عند عكس اتجاه سريان التيار في لفات السولينويد، تنعكس أيضًا نتيجة تطبيق قاعدة قبضة اليد اليمنى بالكامل:

1) يتبادل القطبان أماكنهما: الطرف الذي كان قطبًا جنوبيًا (S) يصبح قطبًا شماليًا (N)، والطرف الذي كان قطبًا شماليًا (N) يصبح قطبًا جنوبيًا (S).

2) يعكس المجال المغناطيسي اتجاهه بالكامل: فداخل السولينويد يصبح المجال متجهًا في الاتجاه المعاكس تمامًا لاتجاهه السابق على طول المحور، وخارجه (حيث تخرج الخطوط من القطب N الجديد وتعود لتدخل عند القطب S الجديد) يعكس اتجاهه أيضًا بالتبعية.

أما شكل نمط خطوط المجال (توزّعها وكثافتها) فلا يتغيّر، لأن شدة التيار وعدد اللفات لم يتغيّرا؛ يتغيّر الاتجاه فقط وليس الشكل ولا المقدار.

[درس 1-5] سؤال تدريبي: قارن بين نمط خطوط المجال المغناطيسي حول سلك مستقيم طويل يحمل تيارًا كهربائيًا، ونمط خطوط المجال المغناطيسي حول ملف دائري (لفة واحدة) يحمل نفس شدة التيار، من حيث: (1) شكل الخطوط، (2) كثافة الفيض عند مركز كل منهما.
الإجابة النموذجية: التشابه: في كلتا الحالتين تكون خطوط المجال المغناطيسي عبارة عن حلقات مغلقة تحيط بالموصل الحامل للتيار، ويُحدَّد اتجاهها في الحالتين بقاعدة قبضة اليد اليمنى بالنسبة لاتجاه التيار المحلي في السلك.

الاختلاف في الشكل: حول السلك المستقيم، تكون خطوط المجال دوائر متحدة المركز منتظمة تمامًا، محورها هو السلك نفسه. أما حول الملف الدائري، فبالقرب من سلك الملف نفسه تشبه الخطوط محليًا تلك الخاصة بسلك مستقيم (دوائر صغيرة حول السلك)، لكنها عند الاقتراب من مركز الحلقة تندمج تدريجيًا لتصبح خطوطًا شبه مستقيمة ومتوازية تقريبًا وعمودية على مستوى الحلقة عند المركز تمامًا.

الاختلاف في كثافة الفيض عند المركز: عند مركز الملف الدائري، تتجمّع إسهامات جميع أجزاء السلك الدائري لتُنتج مجالًا مغناطيسيًا أقوى (أكبر كثافة فيض) في اتجاه واحد محدد عمودي على مستوى الحلقة، مقارنة بنقطة تبعد عن سلك مستقيم بنفس المسافة (نصف قطر الحلقة)، حيث يكون إسهام السلك المستقيم عند تلك النقطة ناتجًا عن جزء واحد بعيد نسبيًا من التيار فقط. لذلك تكون كثافة الفيض عند مركز الملف الدائري أكبر من كثافة الفيض عند نقطة تبعد نفس المسافة عن سلك مستقيم يحمل نفس التيار.

[درس 2-5] سؤال تدريبي: سلك مستقيم أفقي يحمل تيارًا كهربائيًا يسري نحو اليمين، وهو موضوع داخل مجال مغناطيسي منتظم يتجه إلى داخل الصفحة (بعيدًا عن الناظر، ⊗)، والسلك عمودي على اتجاه المجال. باستخدام قاعدة اليد اليمنى، حدد اتجاه القوة المغناطيسية المؤثرة على السلك. (اختر الإجابة الصحيحة)
(أ) إلى الأعلى، داخل مستوى الصفحة
(ب) إلى الأسفل، داخل مستوى الصفحة
(ج) إلى داخل الصفحة (بنفس اتجاه المجال)
(د) إلى خارج الصفحة (نحو الناظر)
الإجابة النموذجية: التيار يسري نحو اليمين، والمجال المغناطيسي يتجه إلى داخل الصفحة، والسلك عمودي على المجال، لذا تُوجَد قوة مغناطيسية مؤثرة على السلك اتجاهها عمودي على كل من اتجاه التيار واتجاه المجال معًا.

بتطبيق قاعدة اليد اليمنى (بحيث تمثّل الأصابع اتجاه المجال المغناطيسي، ويمثّل الإبهام اتجاه التيار، فيشير دفع راحة الكف إلى اتجاه القوة)، نجد أن اتجاه القوة الناتجة يكون إلى الأعلى داخل مستوى الصفحة.

الإجابة الصحيحة: (أ) إلى الأعلى، داخل مستوى الصفحة.

[درس 2-5] سؤال تدريبي: فسّر، بالاعتماد على قاعدة اليد اليمنى ومفهوم تعامد الاتجاهات: (1) لماذا تنعدم القوة المغناطيسية المؤثرة على سلك مستقيم يحمل تيارًا كهربائيًا عندما يكون هذا السلك موازيًا تمامًا لاتجاه المجال المغناطيسي المحيط به، (2) لماذا تكون هذه القوة في أقصى مقدار لها عندما يكون السلك عموديًا (بزاوية قائمة) على اتجاه المجال.
الإجابة النموذجية: (1) عندما يكون السلك موازيًا تمامًا لخطوط المجال المغناطيسي، فإن اتجاه سريان التيار واتجاه المجال المغناطيسي يصبحان على استقامة واحدة (زاوية بينهما = صفر). قاعدة اليد اليمنى تعتمد أساسًا على وجود مكوّن للتيار عمودي على المجال لإنتاج قوة محدَّدة الاتجاه؛ فإذا لم يوجد أي مكوّن عمودي (لأن التيار كله موازٍ للمجال)، فلا تنشأ أي قوة مغناطيسية محصّلة على السلك، أي تنعدم القوة تمامًا.

(2) عندما يكون السلك عموديًا (بزاوية قائمة) على المجال المغناطيسي، فإن التيار بأكمله يمثّل مكوّنًا عموديًا كاملًا على اتجاه المجال، وهذا هو الوضع الذي يُنتج فيه تفاعل التيار مع المجال أكبر قوة ممكنة على السلك، ولذلك تكون القوة المغناطيسية في هذه الحالة في قيمتها العظمى.

[درس 2-5] سؤال تدريبي: يحمل سلك مستقيم طوله 0.30 m تيارًا كهربائيًا شدته 2.0 A، وهو موضوع بزاوية قائمة (عموديًا) على مجال مغناطيسي منتظم كثافة فيضه 0.50 T. احسب مقدار القوة المغناطيسية المؤثرة على هذا السلك.
الإجابة النموذجية: بما أن السلك عمودي على المجال المغناطيسي (θ = 90°)، تُستخدم العلاقة: F = B I L

F = 0.50 × 2.0 × 0.30

F = 0.30 N

إذن مقدار القوة المغناطيسية المؤثرة على السلك يساوي 0.30 N.

[درس 2-5] سؤال تدريبي: بالنسبة للسلك الموصوف في السؤال السابق (L = 0.30 m، I = 2.0 A، B = 0.50 T، عمودي على المجال)، إذا عُكس اتجاه سريان التيار في السلك مع بقاء المجال المغناطيسي ثابتًا في مقداره واتجاهه، صف كيف يتغيّر: (1) مقدار القوة المغناطيسية المؤثرة على السلك، (2) اتجاه هذه القوة.
الإجابة النموذجية: (1) المقدار: لا يتغيّر مقدار القوة، لأن العلاقة F = BIL تعتمد على مقادير B وI وL فقط، وهذه المقادير لم تتغيّر (لم تتغيّر إلا وجهة سريان التيار، وليس شدته). لذلك يبقى مقدار القوة كما هو: F = 0.30 N.

(2) الاتجاه: يعكس اتجاه القوة المغناطيسية تمامًا (ينقلب 180°) ليصبح في الاتجاه المضاد تمامًا لاتجاهه الأصلي. والسبب أن قاعدة اليد اليمنى تربط اتجاه القوة باتجاه التيار مباشرة؛ فعكس اتجاه التيار (مع بقاء المجال كما هو) يعكس اتجاه القوة الناتجة، دون أن يغيّر من مقدارها.

[درس 2-5] سؤال تدريبي: سلك مستقيم رأسي يحمل تيارًا كهربائيًا يسري إلى الأسفل، وهو موضوع داخل مجال مغناطيسي منتظم يتجه أفقيًا نحو اليمين (داخل مستوى الصفحة نفسه)، والسلك عمودي على اتجاه المجال. باستخدام قاعدة اليد اليمنى، حدد اتجاه القوة المغناطيسية المؤثرة على السلك. (اختر الإجابة الصحيحة)
(أ) إلى خارج الصفحة (نحو الناظر)
(ب) إلى داخل الصفحة (بعيدًا عن الناظر)
(ج) إلى الأعلى، داخل مستوى الصفحة
(د) إلى الأسفل، داخل مستوى الصفحة
الإجابة النموذجية: اتجاه التيار إلى الأسفل، واتجاه المجال المغناطيسي أفقي نحو اليمين، والسلك عمودي على المجال، لذا تنشأ قوة مغناطيسية عمودية على كليهما معًا (أي عمودية على مستوى الصفحة نفسه).

بتطبيق قاعدة اليد اليمنى (الأصابع باتجاه المجال نحو اليمين، والإبهام باتجاه التيار إلى الأسفل)، يكون دفع راحة الكف — أي اتجاه القوة — إلى خارج الصفحة، نحو الناظر.

الإجابة الصحيحة: (أ) إلى خارج الصفحة (نحو الناظر).

[درس 3-5] سؤال تدريبي: عرّف كثافة الفيض المغناطيسي (B) عند نقطة معينة، مبينًا العلاقة الرياضية التي يُشتق منها هذا التعريف انطلاقًا من العلاقة العامة F = BIL sinθ.
الإجابة النموذجية: كثافة الفيض المغناطيسي (B) عند نقطة هي القوة المغناطيسية المؤثرة لكل وحدة تيار كهربائي لكل وحدة طول على موصل مستقيم موضوع بزاوية قائمة (عموديًا) على اتجاه المجال المغناطيسي عند تلك النقطة.

تُشتق هذه العلاقة من F = BIL sinθ عند الوضع الخاص θ = 90° (أي عندما يكون السلك عموديًا على المجال، فتكون sinθ = 1):

B = F / (I L)

ووحدة كثافة الفيض المغناطيسي هي التسلا (T)، حيث 1 T = 1 N A⁻¹ m⁻¹.

[درس 3-5] سؤال تدريبي: سلك مستقيم طوله 0.25 m يحمل تيارًا كهربائيًا شدته 3.0 A، وهو موضوع بزاوية 90° مع اتجاه مجال مغناطيسي منتظم كثافة فيضه 0.40 T. احسب مقدار القوة المغناطيسية المؤثرة على السلك.
الإجابة النموذجية: نستخدم العلاقة: F = B I L sinθ

F = 0.40 × 3.0 × 0.25 × sin90°

F = 0.40 × 3.0 × 0.25 × 1

F = 0.30 N

إذن مقدار القوة المغناطيسية المؤثرة على السلك يساوي 0.30 N.

[درس 3-5] سؤال تدريبي: يحمل سلك مستقيم طوله 0.12 m تيارًا كهربائيًا شدته 5.0 A، وهو موضوع بزاوية قائمة على مجال مغناطيسي منتظم، فيتعرض لقوة مغناطيسية مقدارها 0.18 N. حدد كثافة الفيض المغناطيسي B لهذا المجال.
الإجابة النموذجية: بما أن السلك عمودي على المجال (θ = 90°، sinθ = 1)، نعيد ترتيب العلاقة F = BIL sinθ لإيجاد B:

B = F / (I L sinθ)

B = 0.18 / (5.0 × 0.12 × 1)

B = 0.18 / 0.60

B = 0.30 T

إذن كثافة الفيض المغناطيسي تساوي 0.30 T.

[درس 3-5] سؤال تدريبي: سلك مستقيم طوله 0.40 m يحمل تيارًا كهربائيًا شدته 2.5 A، وهو موضوع بحيث تصنع محور السلك زاوية 30° مع اتجاه مجال مغناطيسي منتظم كثافة فيضه 0.20 T. احسب مقدار القوة المغناطيسية المؤثرة على السلك.
الإجابة النموذجية: نستخدم العلاقة العامة: F = B I L sinθ

F = 0.20 × 2.5 × 0.40 × sin30°

F = 0.20 × 2.5 × 0.40 × 0.50

F = 0.20 N × 0.50 (بعد حساب 0.20 × 2.5 × 0.40 = 0.20)

F = 0.10 N

إذن مقدار القوة المغناطيسية المؤثرة على السلك يساوي 0.10 N، وهي أصغر من القوة التي كانت ستنتج لو كان السلك عموديًا على المجال (θ = 90°) بنفس القيم الأخرى، لأن sin30° < sin90°.

[درس 3-5] سؤال تدريبي: ملف دائري مكوَّن من 250 لفة، مساحة كل لفة منه 8.0×10⁻³ m²، موضوع بحيث يكون مستوى الملف عموديًا تمامًا على اتجاه مجال مغناطيسي منتظم كثافة فيضه 0.15 T (أي أن الناظم على مستوى الملف يوازي اتجاه المجال تمامًا، θ = 0°). احسب الفيض المغناطيسي الكلي (الفيض المتداخل) Nφ المرتبط بهذا الملف.
الإجابة النموذجية: نستخدم العلاقة: Nφ = N A B cosθ

بما أن الناظم على مستوى الملف يوازي المجال تمامًا، فإن θ = 0° وcosθ = 1.

Nφ = 250 × 8.0×10⁻³ × 0.15 × 1

Nφ = 250 × 8.0×10⁻³ = 2.0

Nφ = 2.0 × 0.15

Nφ = 0.30 Wb

إذن الفيض المغناطيسي الكلي المرتبط بالملف يساوي 0.30 Wb (فيبر-لفة).

[درس 3-5] سؤال تدريبي: في تجربة "ميزان القطبين" (current balance) لقياس القوة المغناطيسية، يمر تيار كهربائي شدته 1.5 A في سلك أفقي طوله 0.12 m، موضوع بزاوية قائمة على مجال مغناطيسي منتظم كثافة فيضه B₁ = 0.25 T بين قطبي مغناطيس دائم.
(1) احسب الكتلة m₁ اللازم إضافتها على الطرف الآخر من الميزان لموازنة القوة المغناطيسية المؤثرة على السلك (خذ g = 9.81 m s⁻²، واعتبر mg = F عند حالة الاتزان).
(2) إذا استُبدل المغناطيس بآخر كثافة فيضه B₂ = 0.50 T (أي ضعف الأول)، مع بقاء التيار وطول السلك كما هما، حدد الكتلة الجديدة m₂ اللازمة للموازنة، وفسّر العلاقة بين m₁ وm₂.
الإجابة النموذجية: (1) القوة المغناطيسية على السلك (θ = 90°): F₁ = B₁ I L

F₁ = 0.25 × 1.5 × 0.12

F₁ = 0.045 N

عند الاتزان: m₁ g = F₁

m₁ = F₁ / g = 0.045 / 9.81

m₁ ≈ 4.6×10⁻³ kg = 4.6 g

(2) بمضاعفة كثافة الفيض إلى B₂ = 0.50 T مع بقاء I وL ثابتين:

F₂ = B₂ I L = 0.50 × 1.5 × 0.12 = 0.090 N

m₂ = F₂ / g = 0.090 / 9.81 ≈ 9.2×10⁻³ kg = 9.2 g

نلاحظ أن m₂ ≈ 2 × m₁ (9.2 g ≈ 2 × 4.6 g). هذا متوقع لأن F = BIL طردية مع B عند ثبات I وL، فمضاعفة كثافة الفيض المغناطيسي تُضاعف القوة المغناطيسية المؤثرة على السلك، وبالتالي تُضاعف الكتلة اللازمة لموازنتها.

[درس 4-5] سؤال تدريبي: سلك مستقيم طوله 0.20 m يحمل تيارًا كهربائيًا شدته 4.0 A، موضوع داخل مجال مغناطيسي منتظم كثافة فيضه 0.60 T. احسب مقدار القوة المغناطيسية المؤثرة على السلك: (1) عندما يكون السلك عموديًا على المجال (θ = 90°)، (2) عندما تصنع محور السلك زاوية 60° مع اتجاه المجال. ثم قارن بين القيمتين.
الإجابة النموذجية: (1) عند θ = 90°: F₉₀ = B I L sinθ = 0.60 × 4.0 × 0.20 × sin90°

F₉₀ = 0.60 × 4.0 × 0.20 × 1 = 0.48 N

(2) عند θ = 60°: F₆₀ = B I L sinθ = 0.60 × 4.0 × 0.20 × sin60°

F₆₀ = 0.48 × 0.866 ≈ 0.42 N

المقارنة: القوة عند θ = 60° (تساوي تقريبًا 0.42 N) أصغر من القوة عند θ = 90° (تساوي 0.48 N)، لأن sin60° (≈ 0.87) أصغر من sin90° (=1)؛ أي أن القوة تبلغ عند θ = 60° نحو 87% فقط من قيمتها القصوى عند θ = 90°، رغم أن B وI وL لم تتغيّر.

[درس 4-5] سؤال تدريبي: بيّن أن القوة المغناطيسية المؤثرة على سلك مستقيم يحمل تيارًا كهربائيًا تنعدم تمامًا (F = 0) عندما يكون السلك موازيًا تمامًا لاتجاه المجال المغناطيسي (θ = 0°)، مهما كانت قيم B وI وL، مستخدمًا العلاقة F = BIL sinθ.
الإجابة النموذجية: من العلاقة العامة: F = B I L sinθ

عندما يكون السلك موازيًا تمامًا لاتجاه المجال المغناطيسي، تكون الزاوية بين السلك والمجال θ = 0°.

sin0° = 0

إذن: F = B × I × L × 0 = 0 N

وهذا يثبت أن القوة تنعدم تمامًا عند θ = 0°، بصرف النظر عن قيم B وI وL (طالما أنها منتهية)، لأن العامل sinθ هو الذي يحدد ما إذا كان هناك مكوّن فعّال من التيار عمودي على المجال، وعند التوازي التام لا يوجد أي مكوّن عمودي، فلا تنشأ قوة محصّلة.

[درس 4-5] سؤال تدريبي: ملف مستطيل مكوَّن من 50 لفة، يحتوي على ضلعين فعّالين (متعامدين على المجال) طول كل منهما 4.0 cm، ويحمل تيارًا كهربائيًا شدته 0.60 A. وُضع الملف بحيث يكون هذان الضلعان عموديين تمامًا (θ = 90°) على مجال مغناطيسي منتظم كثافة فيضه 0.25 T، كما في محرك كهربائي بسيط. احسب مقدار القوة المغناطيسية الكلية المؤثرة على كل ضلع من الضلعين الفعّالين (مع الأخذ بعين الاعتبار جميع اللفات الخمسين).
الإجابة النموذجية: القوة على السلك الواحد (لفة واحدة) عند θ = 90°: F₁ = B I L

L = 4.0 cm = 0.040 m

F₁ = 0.25 × 0.60 × 0.040

F₁ = 0.0060 N (لكل لفة واحدة)

بما أن الملف يتكوّن من 50 لفة، وكل لفة تسهم بنفس القوة على ذلك الضلع (لأن التيار نفسه يمر في جميع اللفات المتراصة عند نفس موضع الضلع)، فإن القوة الكلية على الضلع الواحد:

F_الكلية = N × F₁ = 50 × 0.0060

F_الكلية = 0.30 N

إذن مقدار القوة المغناطيسية الكلية المؤثرة على كل ضلع فعّال من ضلعي الملف يساوي 0.30 N (وتكون القوتان على الضلعين المتقابلين متساويتين في المقدار ومتعاكستين في الاتجاه، مما يُنتج عزم دوران على الملف).

[درس 4-5] سؤال تدريبي: في تجربة معملية لقياس كثافة الفيض المغناطيسي، يمر سلك مستقيم طوله 0.080 m عموديًا خلال مجال مغناطيسي منتظم بين قطبي مغناطيس موضوع فوق ميزان إلكتروني (بحيث يكون السلك عموديًا تمامًا على المجال). عند تمرير تيار كهربائي شدته 2.5 A في السلك، لوحظ أن قراءة الميزان تزداد بمقدار 4.2 g (بسبب قوة رد الفعل المؤثرة على المغناطيس وفق قانون نيوتن الثالث). حدد كثافة الفيض المغناطيسي B بين قطبي المغناطيس. (خذ g = 9.81 m s⁻²)
الإجابة النموذجية: زيادة قراءة الميزان تعني أن هناك قوة إضافية مقدارها F = Δm × g مؤثرة على المغناطيس (وبالتساوي وبالاتجاه المعاكس على السلك، وفق قانون نيوتن الثالث)، وهذه القوة هي نفسها القوة المغناطيسية المؤثرة على السلك.

Δm = 4.2 g = 4.2×10⁻³ kg

F = Δm × g = 4.2×10⁻³ × 9.81

F ≈ 0.0412 N

بما أن السلك عمودي على المجال (θ = 90°): F = B I L

B = F / (I L) = 0.0412 / (2.5 × 0.080)

B = 0.0412 / 0.20

B ≈ 0.21 T

إذن كثافة الفيض المغناطيسي بين قطبي المغناطيس تساوي تقريبًا 0.21 T.

[درس 4-5] سؤال تدريبي: يحمل قضيب موصل مستقيم تيارًا كهربائيًا ثابت الشدة، وهو موضوع داخل مجال مغناطيسي منتظم ثابت المقدار. إذا تم تدوير القضيب تدريجيًا من وضع موازٍ تمامًا لخطوط المجال (θ = 0°) إلى وضع عمودي تمامًا عليها (θ = 90°)، فكيف يتغيّر مقدار القوة المغناطيسية المؤثرة عليه خلال هذا التدوير؟ (اختر الإجابة الصحيحة)
(أ) يبقى ثابتًا طوال عملية التدوير
(ب) يزداد تدريجيًا من الصفر عند θ=0° إلى قيمته العظمى عند θ=90°
(ج) يبدأ من قيمته العظمى ثم يقل تدريجيًا حتى ينعدم
(د) يبقى صفرًا طوال عملية التدوير
الإجابة النموذجية: بما أن F = BIL sinθ، وB وI وL ثابتة أثناء التدوير، فإن التغيّر في القوة يعتمد فقط على قيمة sinθ.

عند θ = 0°: sinθ = 0، إذن F = 0 (لا توجد قوة).

كلما زادت الزاوية θ من 0° إلى 90°، تزداد قيمة sinθ تدريجيًا وباستمرار من 0 إلى 1، وبالتالي تزداد القوة F تدريجيًا معها.

عند θ = 90°: sinθ = 1، إذن تبلغ القوة قيمتها العظمى Fmax = BIL.

الإجابة الصحيحة: (ب) يزداد تدريجيًا من الصفر عند θ=0° إلى قيمته العظمى عند θ=90°.

[درس 4-5] سؤال تدريبي: يوضع سلك مستقيم طوله 0.15 m داخل مجال مغناطيسي منتظم كثافة فيضه 0.45 T، بحيث تصنع محور السلك زاوية 40° مع اتجاه المجال. إذا كان مقدار القوة المغناطيسية المؤثرة على السلك يساوي 0.15 N، حدد شدة التيار الكهربائي المار في السلك.
الإجابة النموذجية: من العلاقة: F = B I L sinθ

نعيد ترتيبها لإيجاد I:

I = F / (B L sinθ)

sin40° ≈ 0.643

B L sinθ = 0.45 × 0.15 × 0.643 ≈ 0.0434

I = 0.15 / 0.0434

I ≈ 3.5 A

إذن شدة التيار الكهربائي المار في السلك تساوي تقريبًا 3.5 A.

[درس 5-5] سؤال تدريبي: صف قاعدة اليد اليمنى لفلمنج (Fleming's right-hand rule)، موضحًا ماذا يمثّل كل إصبع من الأصابع الثلاثة المستخدمة فيها (الإبهام والسبابة والوسطى) عند تحديد اتجاه التيار (القوة الدافعة الكهربائية) المستحث في موصل يتحرك داخل مجال مغناطيسي.
الإجابة النموذجية: قاعدة اليد اليمنى لفلمنج تُستخدم لتحديد اتجاه التيار (أو القوة الدافعة الكهربائية) المستحث في موصل متحرك داخل مجال مغناطيسي (ظاهرة الحث الكهرومغناطيسي، أي "تأثير المولّد").

تُمَدّ أصابع اليد اليمنى الثلاثة (الإبهام، والسبابة، والوسطى) بحيث تكون متعامدة على بعضها البعض تمامًا (كل إصبع عمودي على الإصبعين الآخرين)، ويمثّل كل منها:

- الإبهام (Thumb): اتجاه حركة الموصل (السرعة، Motion).

- السبابة (First finger): اتجاه المجال المغناطيسي (Field).

- الإصبع الوسطى (seCond finger): اتجاه التيار المستحث، أي اتجاه القوة الدافعة الكهربائية (Current/EMF).

وبمجرد توجيه الإبهام والسبابة وفق اتجاهي حركة الموصل والمجال المغناطيسي فعليًا، يشير الإصبع الوسطى مباشرة إلى اتجاه التيار المستحث في الموصل.

[درس 5-5] سؤال تدريبي: قضيب موصل أفقي يتحرك بسرعة ثابتة نحو اليمين، داخل مجال مغناطيسي منتظم يتجه إلى داخل الصفحة (⊗)، والقضيب رأسي وعمودي على كل من اتجاه حركته واتجاه المجال. باستخدام قاعدة اليد اليمنى لفلمنج، حدد اتجاه سريان التيار (الاصطلاحي) المستحث داخل القضيب (من الطرف العلوي إلى السفلي أو العكس)، وحدد أي طرفي القضيب يصبح ذا الجهد الأعلى (القطب الموجب).
الإجابة النموذجية: بتطبيق قاعدة اليد اليمنى لفلمنج: الإبهام يشير إلى اتجاه حركة القضيب (نحو اليمين)، والسبابة تشير إلى اتجاه المجال المغناطيسي (إلى داخل الصفحة)، فتشير الإصبع الوسطى إلى اتجاه التيار المستحث.

ينتج عن ذلك أن التيار الاصطلاحي المستحث داخل القضيب يسري من الطرف السفلي إلى الطرف العلوي (إلى الأعلى داخل القضيب).

بما أن القضيب يعمل كمصدر للقوة الدافعة الكهربائية، فإن الشحنة الموجبة تتراكم عند الطرف الذي يتجه إليه التيار داخل المصدر، أي عند الطرف العلوي؛ لذلك يصبح الطرف العلوي هو القطب ذو الجهد الأعلى (الموجب)، بينما يصبح الطرف السفلي ذا الجهد الأدنى (السالب).

[درس 5-5] سؤال تدريبي: يتحرك قضيب موصل مستقيم طوله 0.30 m بسرعة ثابتة مقدارها 4.0 m/s، عموديًا على مجال مغناطيسي منتظم كثافة فيضه 0.25 T، وعموديًا أيضًا على طول القضيب نفسه. خلال فترة زمنية مقدارها 0.10 s: (1) احسب المساحة التي يمسحها القضيب، (2) احسب مقدار التغيّر في الفيض المغناطيسي خلال هذه المساحة، (3) احسب مقدار القوة الدافعة الكهربائية المستحثة ε باستخدام ε = ΔNφ/Δt.
الإجابة النموذجية: (1) المساحة الممسوحة: ΔA = L × v × Δt

ΔA = 0.30 × 4.0 × 0.10

ΔA = 0.12 m²

(2) التغيّر في الفيض المغناطيسي: ΔΦ = B × ΔA

ΔΦ = 0.25 × 0.12

ΔΦ = 0.030 Wb

(3) القوة الدافعة الكهربائية المستحثة (لموصل واحد، أي N = 1):

ε = ΔΦ / Δt = 0.030 / 0.10

ε = 0.30 V

إذن القوة الدافعة الكهربائية المستحثة في القضيب تساوي 0.30 V.

[درس 5-5] سؤال تدريبي: ملف من 300 لفة، مساحة كل لفة منه 0.015 m²، موضوع بحيث يكون مستواه عموديًا تمامًا على مجال مغناطيسي منتظم كثافة فيضه 0.20 T (θ = 0°). أُوقف المجال المغناطيسي فجأة وانخفض بانتظام من قيمته إلى الصفر خلال 0.050 s. احسب مقدار القوة الدافعة الكهربائية المستحثة في الملف خلال هذه الفترة.
الإجابة النموذجية: الفيض المتداخل (الكلي) الابتدائي: Nφ₁ = N A B cosθ = 300 × 0.015 × 0.20 × cos0°

Nφ₁ = 300 × 0.015 × 0.20 × 1

Nφ₁ = 0.90 Wb

بما أن المجال ينخفض إلى الصفر، فإن الفيض المتداخل النهائي: Nφ₂ = 0

مقدار التغيّر في الفيض المتداخل: ΔNφ = Nφ₁ − Nφ₂ = 0.90 − 0 = 0.90 Wb

مقدار القوة الدافعة الكهربائية المستحثة:

ε = ΔNφ / Δt = 0.90 / 0.050

ε = 18 V

إذن مقدار القوة الدافعة الكهربائية المستحثة في الملف خلال فترة إيقاف المجال يساوي 18 V.

[درس 5-5] سؤال تدريبي: فسّر أثر كل من العوامل التالية على مقدار القوة الدافعة الكهربائية المستحثة (ε) في ملف يدور داخل مجال مغناطيسي منتظم، مستخدمًا العلاقة ε = ΔNφ/Δt: (1) زيادة معدل دوران الملف (أي تقليل الزمن اللازم لدورة واحدة)، (2) زيادة كثافة الفيض المغناطيسي B، (3) زيادة عدد لفات الملف N.
الإجابة النموذجية: (1) زيادة معدل الدوران: عند زيادة معدل دوران الملف، يحدث نفس مقدار التغيّر في الفيض المتداخل ΔNφ (بين وضعي الفيض الأقصى والأدنى) خلال زمن Δt أقصر. وبما أن ε = ΔNφ/Δt، فإن تقليل Δt (مع بقاء ΔNφ كما هو تقريبًا) يزيد من قيمة ε، أي تزداد القوة الدافعة الكهربائية المستحثة.

(2) زيادة كثافة الفيض B: الفيض المتداخل الأقصى للملف يساوي NAB (عند θ=0°)، فزيادة B تزيد من مقدار الفيض المتداخل الأقصى، وبالتالي تزيد من مقدار التغيّر في الفيض ΔNφ الحادث خلال كل دورة (لنفس Δt)، مما يزيد من مقدار ε.

(3) زيادة عدد اللفات N: بما أن Nφ يتناسب طرديًا مباشرة مع N (لكل لفة إسهام مساوٍ تقريبًا في الفيض)، فإن زيادة عدد اللفات تزيد من مقدار التغيّر الكلي في الفيض المتداخل ΔNφ لكل دورة بنفس النسبة، وبالتالي تزيد من مقدار ε طرديًا مع N.

[درس 5-5] سؤال تدريبي: في تجربة كلاسيكية للحث الكهرومغناطيسي، يُسقَط مغناطيس قضيبي (بقطبه الشمالي N للأسفل) رأسيًا خلال ملف سلكي ثابت متصل بجلفانومتر حساس. صف وفسّر ما يلاحظه المجرّب على الجلفانومتر أثناء اقتراب المغناطيس من الملف، وأثناء ابتعاده عنه بعد عبوره، مستندًا إلى مفهوم معدّل تغيّر الفيض المتداخل Nφ.
الإجابة النموذجية: أثناء اقتراب المغناطيس من الملف (قبل الدخول وأثناءه): يتزايد الفيض المتداخل Nφ المرتبط بالملف بسرعة (خصوصًا كلما اقترب المغناطيس واشتد المجال عند الملف)، فيُحدث ذلك معدل تغيّر كبير للفيض، فيسجّل الجلفانومتر انحرافًا واضحًا في اتجاه معيّن، يزداد كلما زادت سرعة سقوط المغناطيس (لأن معدل تغيّر الفيض يكبر مع السرعة، وε = ΔNφ/Δt).

أثناء ابتعاد المغناطيس عن الملف بعد عبوره بالكامل: يتناقص الفيض المتداخل بسرعة أيضًا (باتجاه معاكس للحالة الأولى)، فيسجّل الجلفانومتر انحرافًا واضحًا لكن في الاتجاه المعاكس لاتجاه الانحراف الأول.

في اللحظة التي يكون فيها المغناطيس ثابتًا تمامًا (لو أُوقف) داخل الملف أو بعيدًا جدًا عنه (حيث لا يتغيّر الفيض عمليًا)، لا يُسجَّل الجلفانومتر أي انحراف، لأن معدل تغيّر الفيض يكون تقريبًا صفرًا.

هذا يوضّح أن القوة الدافعة الكهربائية المستحثة (وبالتالي التيار المستحث الذي يقيسه الجلفانومتر) لا تعتمد على وجود فيض مغناطيسي بحد ذاته، بل على معدّل تغيّر هذا الفيض المتداخل عبر الملف فقط.

[درس 6-5] سؤال تدريبي: ملف سلكي (لفة واحدة) مساحته 0.020 m²، موضوع بحيث يصنع الناظم على مستوى الملف زاوية 40° مع اتجاه مجال مغناطيسي منتظم كثافة فيضه 0.60 T. احسب مقدار الفيض المغناطيسي Φ المار خلال الملف.
الإجابة النموذجية: نستخدم العلاقة: Φ = B A cosθ

cos40° ≈ 0.766

Φ = 0.60 × 0.020 × 0.766

Φ = 0.012 × 0.766

Φ ≈ 9.2×10⁻³ Wb

إذن مقدار الفيض المغناطيسي المار خلال الملف يساوي تقريبًا 9.2×10⁻³ Wb.

[درس 6-5] سؤال تدريبي: ملف مستطيل من 120 لفة، مساحة كل لفة منه 1.5×10⁻³ m²، يُدفع بسرعة منتظمة ليدخل بالكامل داخل منطقة مجال مغناطيسي منتظم كثافة فيضه 0.80 T (بحيث يصبح مستوى الملف عموديًا تمامًا على المجال، θ = 0°)، ويستغرق دخوله بالكامل زمنًا مقداره 0.25 s. احسب متوسط القوة الدافعة الكهربائية المستحثة في الملف خلال دخوله المجال، مستخدمًا قانون فاراداي ε = NΔΦ/Δt.
الإجابة النموذجية: الفيض المغناطيسي المار خلال لفة واحدة بعد دخول الملف بالكامل (θ = 0°، cosθ = 1):

ΔΦ = B A = 0.80 × 1.5×10⁻³

ΔΦ = 1.2×10⁻³ Wb

(قبل الدخول كان الفيض المار خلال الملف صفرًا، لذا هذا هو مقدار التغيّر في الفيض لكل لفة)

مقدار التغيّر في الفيض المتداخل الكلي:

N ΔΦ = 120 × 1.2×10⁻³ = 0.144 Wb

متوسط القوة الدافعة الكهربائية المستحثة:

ε = N ΔΦ / Δt = 0.144 / 0.25

ε ≈ 0.58 V

إذن متوسط القوة الدافعة الكهربائية المستحثة في الملف أثناء دخوله المجال يساوي تقريبًا 0.58 V.

[درس 6-5] سؤال تدريبي: ملف من 200 لفة، مساحة كل لفة منه 0.010 m²، يدور داخل مجال مغناطيسي منتظم كثافة فيضه 0.15 T. عند لحظة البدء، يكون مستوى الملف عموديًا تمامًا على المجال (θ = 0° بين الناظم والمجال، أي الفيض في قيمته العظمى)، ثم يدور الملف ربع دورة (90°) خلال زمن مقداره 0.020 s، بحيث يصبح مستوى الملف موازيًا للمجال (θ = 90°، أي الفيض يساوي صفرًا). احسب متوسط القوة الدافعة الكهربائية المستحثة خلال هذا الربع من الدورة.
الإجابة النموذجية: الفيض المتداخل عند البداية (θ = 0°، cosθ = 1):

NΦ_ابتدائي = N A B cosθ = 200 × 0.010 × 0.15 × 1 = 0.30 Wb

الفيض المتداخل عند النهاية (θ = 90°، cosθ = 0):

NΦ_نهائي = 200 × 0.010 × 0.15 × 0 = 0

مقدار التغيّر في الفيض المتداخل:

Δ(NΦ) = 0.30 − 0 = 0.30 Wb

متوسط القوة الدافعة الكهربائية المستحثة:

ε = Δ(NΦ) / Δt = 0.30 / 0.020

ε = 15 V

إذن متوسط القوة الدافعة الكهربائية المستحثة في الملف خلال هذا الربع من الدورة يساوي 15 V.

[درس 6-5] سؤال تدريبي: يتحرك قضيب موصل مستقيم طوله 0.45 m بسرعة ثابتة مقدارها 6.0 m/s، عموديًا على مجال مغناطيسي منتظم كثافة فيضه 0.35 T، وعموديًا أيضًا على طوله. احسب مقدار القوة الدافعة الكهربائية المستحثة بين طرفي القضيب.
الإجابة النموذجية: بما أن حركة القضيب عمودية على كل من المجال المغناطيسي وعلى طول القضيب نفسه، نستخدم العلاقة: ε = B L v

ε = 0.35 × 0.45 × 6.0

ε = 0.35 × 0.45 = 0.1575

ε = 0.1575 × 6.0

ε ≈ 0.95 V

إذن مقدار القوة الدافعة الكهربائية المستحثة بين طرفي القضيب يساوي تقريبًا 0.95 V.

[درس 6-5] سؤال تدريبي: بيّن، باستخدام قانون فاراداي ε = NΔΦ/Δt، أنه إذا تمت مضاعفة معدل دوران ملف مولّد كهربائي (أي أصبحت كل دورة تستغرق نصف الزمن السابق)، مع بقاء عدد اللفات N وكثافة الفيض B ومساحة الملف A دون تغيير، فإن القيمة العظمى للقوة الدافعة الكهربائية المستحثة تتضاعف أيضًا.
الإجابة النموذجية: القيمة القصوى لتغيّر الفيض المتداخل خلال ربع دورة (من الفيض الأقصى NAB إلى الصفر) تساوي: Δ(NΦ)max = N A B

هذه القيمة لا تعتمد على سرعة الدوران، بل فقط على N وA وB، وهي جميعها ثابتة حسب المعطى، لذا Δ(NΦ)max لا يتغيّر.

عند مضاعفة معدل الدوران، يصبح الزمن اللازم لإتمام نفس الربع من الدورة نصف الزمن الأصلي، أي Δt الجديد = Δt الأصلي / 2.

بما أن: ε = Δ(NΦ) / Δt

فإن تنصيف Δt (مع بقاء البسط Δ(NΦ)max ثابتًا) يؤدي إلى مضاعفة قيمة ε:

ε_جديد = Δ(NΦ)max / (Δt/2) = 2 × [Δ(NΦ)max / Δt] = 2 × ε_قديم

إذن القيمة العظمى للقوة الدافعة الكهربائية المستحثة تتضاعف فعلًا عند مضاعفة معدل الدوران، كما هو مطلوب إثباته.

[درس 6-5] سؤال تدريبي: ملف يدور داخل مجال مغناطيسي منتظم وينتج قوة دافعة كهربائية مستحثة قيمتها القصوى ε₀. إذا تم استبدال الملف بملف آخر مطابق له في كل شيء (نفس المساحة ونفس معدل الدوران ونفس كثافة الفيض) باستثناء أن عدد لفاته يساوي ثلاثة أضعاف عدد لفات الملف الأول، فماذا يحدث للقيمة القصوى للقوة الدافعة الكهربائية المستحثة الجديدة، مقارنة بـ ε₀؟ (اختر الإجابة الصحيحة)
(أ) تبقى دون تغيير (تساوي ε₀)
(ب) تصبح ثلاثة أضعاف قيمتها الأصلية (3ε₀)
(ج) تصبح تسعة أضعاف قيمتها الأصلية (9ε₀)
(د) تصبح ثلث قيمتها الأصلية (ε₀/3)
الإجابة النموذجية: بما أن ε = Δ(NΦ)/Δt = N × (ΔΦ/Δt)، فإن القوة الدافعة الكهربائية المستحثة تتناسب طرديًا ومباشرة مع عدد اللفات N، طالما بقيت جميع العوامل الأخرى (المساحة A، كثافة الفيض B، ومعدل الدوران، وبالتالي Δt) ثابتة دون تغيير.

بما أن عدد لفات الملف الجديد يساوي ثلاثة أضعاف عدد لفات الملف الأصلي (نفس معدل تغيّر الفيض لكل لفة ΔΦ/Δt)، فإن القيمة القصوى الجديدة للقوة الدافعة الكهربائية المستحثة تصبح ثلاثة أضعاف القيمة الأصلية.

الإجابة الصحيحة: (ب) تصبح ثلاثة أضعاف قيمتها الأصلية (3ε₀).

[درس 7-5] سؤال تدريبي: انصّ على قانون لنز (Lenz's law) المتعلق باتجاه القوة الدافعة الكهربائية المستحثة.
الإجابة النموذجية: ينص قانون لنز على أن: اتجاه أي قوة دافعة كهربائية مستحثة (وما ينتج عنها من تيار مستحث في دائرة مغلقة) يكون دائمًا بحيث تنتج تأثيرات (تيار مستحث ومجال مغناطيسي ناتج عنه) تقاوم وتعاكس التغيّر (في الفيض المغناطيسي) الذي أدى إلى نشوء هذه القوة الدافعة الكهربائية أصلًا.

[درس 7-5] سؤال تدريبي: يُقرَّب القطب الشمالي (N) لمغناطيس قضيبي من أحد طرفي ملف سلكي متصل بدائرة مغلقة (كما في تجربة فاراداي). باستخدام قانون لنز، حدد: (1) نوع القطب المغناطيسي الذي يتكوّن عند الطرف القريب من الملف نتيجة التيار المستحث، (2) اتجاه سريان هذا التيار المستحث في لفات الملف عند النظر إلى ذلك الطرف من جهة المغناطيس المُقترِب (مع اتجاه عقارب الساعة أو عكسه).
الإجابة النموذجية: (1) وفق قانون لنز، يجب أن يقاوم التيار المستحث سبب حدوثه، وهو هنا ازدياد الفيض المغناطيسي المتجه نحو الملف بسبب اقتراب القطب الشمالي N. لمقاومة هذا الاقتراب، يجب أن ينشأ عند الطرف القريب من الملف قطب يُنافر القطب الشمالي المقترب (لأن التنافر بين قطبين متماثلين يعيق الاقتراب)، أي يتكوّن عند هذا الطرف قطب شمالي (N) أيضًا.

(2) بما أن الطرف القريب من الملف يجب أن يصبح قطبًا شماليًا (N)، وباستخدام قاعدة قبضة اليد اليمنى معكوسة (كما في تحديد نوع القطب من اتجاه التيار في السولينويد)، فإن اتجاه سريان التيار المستحث في اللفات عند النظر إلى هذا الطرف من جهة المغناطيس يكون عكس اتجاه عقارب الساعة.

[درس 7-5] سؤال تدريبي: بعد اقتراب القطب الشمالي (N) من الملف الموصوف في السؤال السابق حتى مسافة قريبة جدًا، بدأ المغناطيس يبتعد عن الملف (يُسحب للخلف). باستخدام قانون لنز، حدد: (1) نوع القطب المتكوّن عند نفس الطرف القريب من الملف أثناء ابتعاد المغناطيس، (2) اتجاه سريان التيار المستحث في اللفات (عند نفس زاوية النظر السابقة)، مقارنًا بإجابتك في السؤال السابق.
الإجابة النموذجية: (1) عند ابتعاد المغناطيس، يتناقص الفيض المغناطيسي المتجه نحو الملف عبر ذلك الطرف. وفق قانون لنز، يجب أن يقاوم التيار المستحث هذا التناقص، وذلك بجذب المغناطيس ومحاولة إبقائه قريبًا (منع ابتعاده). ولحدوث تجاذب مع القطب الشمالي المبتعد، يجب أن يتكوّن عند الطرف القريب من الملف قطب جنوبي (S)، لأن التجاذب يحدث بين قطبين مختلفين.

(2) بما أن نوع القطب قد انعكس (أصبح S بدلًا من N)، فإن اتجاه سريان التيار المستحث في اللفات ينعكس أيضًا بالكامل مقارنة بالسؤال السابق: يصبح مع اتجاه عقارب الساعة (عند نفس زاوية النظر من جهة المغناطيس). وهذا متوقع لأن التغيّر في الفيض (تناقص بدلًا من تزايد) قد عكس اتجاهه، وبالتالي عكس اتجاه القوة الدافعة الكهربائية المستحثة والتيار الناتج عنها.

[درس 7-5] سؤال تدريبي: فسّر لماذا يُعَدّ قانون لنز نتيجة مباشرة لمبدأ حفظ الطاقة، أي لماذا لا يمكن للتيار المستحث أن يعمل في اتجاه يُساعد (بدلًا من أن يقاوم) التغيّر الذي أنتجه.
الإجابة النموذجية: لو افترضنا (خلافًا لقانون لنز) أن التيار المستحث ينشأ في اتجاه يُساعد التغيّر الذي سبّبه بدلًا من أن يقاومه — على سبيل المثال، لو أن اقتراب قطب مغناطيسي من ملف أدى إلى نشوء قطب مُنافر له مساعدًا على مزيد من التسارع نحو الملف بدلًا من مقاومته — فإن ذلك يعني أن المغناطيس سيتسارع نحو الملف من تلقاء نفسه دون بذل أي عمل خارجي عليه، بل ستزداد سرعته وطاقته الحركية باستمرار، وفي الوقت نفسه سيُنتَج تيار كهربائي (طاقة كهربائية) في الملف دون أي مصدر خارجي للطاقة.

هذا يعني توليد طاقة (حركية وكهربائية معًا) من العدم، وهو ما يخالف مبدأ حفظ الطاقة الذي ينص على أن الطاقة لا تُستحدث ولا تفنى.

لذلك يجب أن يعاكس التيار المستحث التغيّر الذي سبّبه (كما ينص قانون لنز)، بحيث يجب بذل عمل خارجي (كدفع المغناطيس ضد قوة التنافر) لإحداث هذا التغيّر، وهذا العمل الخارجي هو ما يزوّد الدائرة بالطاقة الكهربائية الناتجة عن التيار المستحث، وبذلك تتحقق مبدأ حفظ الطاقة.

[درس 7-5] سؤال تدريبي: حلقة سلكية واحدة (لفة واحدة) مرتبطة بمجال مغناطيسي متغيّر. سُجِّل الفيض المغناطيسي المار خلالها كما يلي: خلال أول 0.40 s، ازداد الفيض من الصفر إلى 0.012 Wb بمعدل ثابت. خلال الفترة الزمنية التالية البالغة أيضًا 0.40 s، استمر الفيض في الازدياد، لكن من 0.012 Wb إلى 0.014 Wb فقط (بمعدل ثابت أبطأ). قارن بين مقدار القوة الدافعة الكهربائية المستحثة في الحلقة خلال الفترة الزمنية الأولى ومقدارها خلال الفترة الزمنية الثانية.
الإجابة النموذجية: القوة الدافعة الكهربائية المستحثة تساوي مقدار معدّل تغيّر الفيض المغناطيسي (ميل الرسم البياني لـ Φ مقابل t)، أي ε = ΔΦ/Δt (بما أن الحلقة تحتوي على لفة واحدة فقط، N = 1).

خلال الفترة الأولى: ε₁ = ΔΦ₁/Δt = 0.012 / 0.40 = 0.030 V

خلال الفترة الثانية: ε₂ = ΔΦ₂/Δt = (0.014 − 0.012) / 0.40 = 0.0020 / 0.40 = 0.0050 V

المقارنة: مقدار القوة الدافعة الكهربائية المستحثة خلال الفترة الأولى (0.030 V) أكبر بكثير (ستة أضعاف تقريبًا) من مقدارها خلال الفترة الثانية (0.0050 V)، لأن معدل تغيّر الفيض المغناطيسي (ميل المنحنى) كان أكبر بكثير خلال الفترة الأولى منه خلال الفترة الثانية، رغم تساوي طول الفترتين الزمنيتين.

[درس 7-5] سؤال تدريبي: في تجربة فاراداي، يوصَل ملف سلكي بجلفانومتر حساس، ثم يُدفَع مغناطيس قضيبي (بقطبه N أولًا) داخل الملف بسرعة معينة، ثم يُترك ساكنًا تمامًا داخل الملف لبضع ثوانٍ، ثم يُسحَب للخارج بسرعة أكبر من سرعة دخوله. صف ما يلاحظه المجرّب على مؤشر الجلفانومتر خلال هذه المراحل الثلاث، وفسّر ذلك اعتمادًا على قانوني فاراداي ولنز معًا.
الإجابة النموذجية: المرحلة الأولى (دفع المغناطيس للداخل): يزداد الفيض المغناطيسي المار عبر الملف بسرعة، فيسجّل الجلفانومتر انحرافًا واضحًا في اتجاه معيّن (لتفسيره: يعطي قانون فاراداي مقدار هذا الانحراف بدلالة معدّل تغيّر الفيض، بينما يحدد قانون لنز اتجاهه بحيث يقاوم التيار المستحث دخول المغناطيس، أي يتكوّن عند الطرف القريب قطب N يُنافر قطب المغناطيس المقترب).

المرحلة الثانية (المغناطيس ساكن داخل الملف): لا يتغيّر الفيض المغناطيسي المار عبر الملف (لأن المغناطيس ثابت)، فمعدل تغيّر الفيض يساوي صفرًا تقريبًا، ولذلك يعود مؤشر الجلفانومتر إلى الصفر (لا يوجد انحراف، أي لا توجد قوة دافعة كهربائية مستحثة).

المرحلة الثالثة (سحب المغناطيس للخارج بسرعة أكبر): يتناقص الفيض المغناطيسي المار عبر الملف بسرعة أكبر من سرعة تناقصه (أو تزايده) في المرحلة الأولى، فيسجّل الجلفانومتر انحرافًا في الاتجاه المعاكس تمامًا لاتجاه انحراف المرحلة الأولى (لأن التغيّر في الفيض عكسي الاتجاه الآن، وفق قانون لنز الذي يقاوم هذه المرة خروج المغناطيس فيُنتج قطب S يجذبه)، وتكون مقدار هذا الانحراف أكبر من انحراف المرحلة الأولى، لأن معدل تغيّر الفيض أكبر (بسبب السرعة الأكبر)، وفق قانون فاراداي.

[درس 8-5] سؤال تدريبي: فسّر المقصود بالتيارات الدوّامة (eddy currents)، وكيف تنشأ داخل قطعة معدنية موصلة صلبة (غير مغناطيسية) عند تحرّكها داخل منطقة يوجد بها مجال مغناطيسي غير منتظم (مثل حافة مجال مغناطيسي قوي).
الإجابة النموذجية: التيارات الدوّامة هي تيارات كهربائية دائرية (حلقية) مستحثة تنشأ داخل جسم موصل صلب (كلوح أو قرص معدني) نتيجة تغيّر الفيض المغناطيسي المار خلال أجزاء مختلفة من هذا الجسم، دون الحاجة إلى وجود سلك أو ملف محدد الشكل، حيث يتصرف الجسم الموصل نفسه وكأنه يحتوي على عدد لا نهائي من الحلقات الموصلة المتداخلة.

عندما تتحرك قطعة معدنية موصلة داخل منطقة مجال مغناطيسي غير منتظم (كأن يدخل جزء منها المجال بينما جزء آخر لا يزال خارجه، أو العكس)، فإن الفيض المغناطيسي المار خلال أجزاء مختلفة من القطعة يتغيّر باستمرار أثناء الحركة. وفق قانون فاراداي، يُستحث نتيجة هذا التغيّر قوى دافعة كهربائية داخل مادة القطعة نفسها، وبما أن المعدن موصل جيد، تسري هذه القوى الدافعة الكهربائية تيارات كهربائية دائرية (دوّامية الشكل) داخل جسم القطعة، تُعرف بالتيارات الدوّامة.

[درس 8-5] سؤال تدريبي: فسّر، باستخدام قانوني فاراداي ولنز معًا، لماذا يتباطأ (يتباطأ بشدة) بندول مصنوع من لوح ألومنيوم صلب عند تأرجحه خلال منطقة مجال مغناطيسي قوي بين قطبي مغناطيس دائم، بينما يواصل بندول مماثل تمامًا مصنوع من الخشب (مادة غير موصلة) تأرجحه بحرية دون أي تأثير يُذكر من المجال نفسه.
الإجابة النموذجية: عندما يتأرجح اللوح المعدني (الموصل) عبر منطقة المجال المغناطيسي، يدخل جزء منه المجال بينما يبقى جزء آخر خارجه (أو يخرج منه)، فيتغيّر الفيض المغناطيسي المار خلال مناطق مختلفة من اللوح باستمرار أثناء حركته. وفق قانون فاراداي، يُستحث نتيجة هذا التغيّر قوى دافعة كهربائية داخل اللوح، ولأن الألومنيوم موصل جيد، تسري تيارات دوّامة كبيرة داخل اللوح.

وفق قانون لنز، يجب أن تعاكس هذه التيارات الدوّامة (وما تُنتجه من مجالات مغناطيسية خاصة بها) سبب نشوئها، أي حركة اللوح نفسها داخل المجال؛ فتنشأ قوى مغناطيسية معيقة (قوى كبح) تعارض حركة اللوح وتُبطئها بشدة، وتتحوّل طاقته الحركية إلى طاقة حرارية (بسبب مقاومة اللوح الكهربائية) نتيجة سريان هذه التيارات الدوّامة فيه.

أما لوح الخشب، فهو مادة عازلة (غير موصلة للكهرباء)، فلا يمكن أن تسري فيه أي تيارات دوّامة مهما تغيّر الفيض المغناطيسي المار خلاله، وبالتالي لا تنشأ فيه أي قوة مغناطيسية معيقة، ويستمر تأرجحه بحرية دون أي تأثير من المجال المغناطيسي.

[درس 8-5] سؤال تدريبي: قارن بين حركة بندولين مصنوعين من نفس الشكل والأبعاد تمامًا، أحدهما من الألومنيوم الصلب والآخر من الخشب، عند إطلاقهما من نفس الارتفاع ليتأرجحا خلال نفس منطقة المجال المغناطيسي القوي بين قطبي مغناطيس دائم.
الإجابة النموذجية: التشابه: قبل الوصول إلى منطقة المجال المغناطيسي، يتأرجح كلا البندولين بنفس الطريقة تقريبًا (تحكمهما نفس قوانين الحركة التوافقية البسيطة، لأن لهما نفس الشكل والأبعاد والكتلة الفعّالة تقريبًا في غياب المجال).

الاختلاف: بندول الألومنيوم (الموصل)، عند دخوله وخروجه من منطقة المجال المغناطيسي، تُستحث فيه تيارات دوّامة (وفق قانون فاراداي)، تُنتج قوى معيقة تعارض حركته (وفق قانون لنز)، فيفقد طاقته الحركية بسرعة على هيئة حرارة، ويتباطأ تأرجحه بشدة ويتوقف تقريبًا بعد مروره القليل خلال منطقة المجال (تخامد سريع جدًا).

أما بندول الخشب (غير الموصل)، فلا تنشأ فيه أي تيارات دوّامة لأنه عازل، فلا يتأثر بوجود المجال المغناطيسي إطلاقًا، ويستمر في التأرجح بحرية تقريبًا كما لو لم يكن هناك أي مجال مغناطيسي على الإطلاق (يتباطأ فقط ببطء شديد بسبب مقاومة الهواء والاحتكاك الطبيعي المعتاد).

[درس 8-5] سؤال تدريبي: اقترح تطبيقًا عمليًا واحدًا يُستفاد فيه من ظاهرة الكبح المغناطيسي بالتيارات الدوّامة، واشرح باختصار كيف تعمل هذه الظاهرة على تحقيق الغرض المطلوب في هذا التطبيق.
الإجابة النموذجية: من التطبيقات العملية الشائعة لظاهرة الكبح المغناطيسي بالتيارات الدوّامة: أنظمة الفرملة المغناطيسية في بعض القطارات السريعة أو في ألعاب الملاهي (كبرج السقوط الحر)، وكذلك في بعض أجهزة قياس السرعة (عدّادات السرعة القديمة ذات القرص الدوّار).

آلية عملها: يُثبَّت قرص أو صفيحة معدنية موصلة (غير مغناطيسية، كالألومنيوم أو النحاس) بحيث تتحرك (تدور أو تنزلق) بسرعة داخل مجال مغناطيسي قوي عند الحاجة إلى الفرملة (مثلًا بتقريب مغناطيسات قوية من القرص الدوّار في القطار). يؤدي ذلك إلى استحثاث تيارات دوّامة كبيرة في القرص وفق قانون فاراداي، وتنشأ عنها (وفق قانون لنز) قوى مغناطيسية معيقة تعاكس حركة القرص وتُبطئه دون أي تلامس ميكانيكي مباشر (فرملة "بلا احتكاك" ميكانيكي)، مما يوفر فرملة سلسة وفعّالة وتقل معها تآكل أجزاء الفرامل التقليدية.

[درس 8-5] سؤال تدريبي: يُستخدم في بعض التجارب المعملية قرص معدني موصل (كالألومنيوم) له شكلان: قرص مصمت (سليم بالكامل)، وقرص آخر مطابق له تمامًا لكن قُطعت فيه عدة شقوق نصف قطرية (من الحافة باتجاه المركز تقريبًا) دون أن تصل إلى المركز نفسه. عند تأرجح كل من القرصين خلال منطقة مجال مغناطيسي قوي، لوحظ أن القرص المشقوق يتباطأ بدرجة أقل بكثير من القرص المصمت. فسّر سبب ذلك.
الإجابة النموذجية: في القرص المصمت (السليم)، يستطيع المعدن تكوين مسارات دائرية (حلقية) مغلقة وكاملة تمامًا للتيارات الدوّامة داخل جسمه دون أي عائق، فتسري فيه تيارات دوّامة كبيرة نسبيًا عند دخوله أو خروجه من منطقة المجال، مما يُنتج قوى كبح مغناطيسية قوية (وفق قانوني فاراداي ولنز) تُبطئ حركته بشدة.

أما في القرص المشقوق، فإن الشقوق نصف القطرية تقطع المسارات الدائرية الكاملة التي كانت ستتكوّن فيها التيارات الدوّامة، بحيث يُجبَر أي تيار مستحث على المرور عبر مسارات أطول وأضيق (تلتف حول الشقوق)، مما يزيد كثيرًا من المقاومة الكهربائية الفعّالة لهذه المسارات، فتقل شدة التيارات الدوّامة الناتجة بدرجة كبيرة.

وبما أن قوة الكبح المغناطيسي تعتمد على مقدار التيارات الدوّامة المستحثة (فكلما زاد التيار المستحث زادت القوة المعيقة)، فإن ضعف هذه التيارات في القرص المشقوق يُنتج قوى كبح أضعف بكثير مقارنة بالقرص المصمت، ولذلك يتباطأ القرص المشقوق بدرجة أقل.

[درس 8-5] سؤال تدريبي: يدخل لوح معدني موصل كتلته 0.40 kg منطقة مجال مغناطيسي قوي بسرعة أفقية مقدارها 2.5 m/s، ونتيجة الكبح المغناطيسي بالتيارات الدوّامة، يخرج من هذه المنطقة بسرعة مقدارها 1.0 m/s فقط (مع إهمال أي تأثير للاحتكاك مع الهواء). احسب مقدار الطاقة الحركية المفقودة من اللوح أثناء عبوره منطقة المجال، واذكر إلى أي صورة من صور الطاقة تحوّلت هذه الطاقة المفقودة.
الإجابة النموذجية: الطاقة الحركية الابتدائية: KE₁ = ½ m v₁² = ½ × 0.40 × (2.5)²

(2.5)² = 6.25

KE₁ = 0.5 × 0.40 × 6.25 = 1.25 J

الطاقة الحركية النهائية: KE₂ = ½ m v₂² = ½ × 0.40 × (1.0)²

(1.0)² = 1.0

KE₂ = 0.5 × 0.40 × 1.0 = 0.20 J

مقدار الطاقة الحركية المفقودة: ΔKE = KE₁ − KE₂ = 1.25 − 0.20 = 1.05 J

إذن فقد اللوح 1.05 J من طاقته الحركية أثناء عبوره منطقة المجال. وفق مبدأ حفظ الطاقة، لم تختفِ هذه الطاقة، بل تحوّلت إلى طاقة حرارية (حرارة) داخل اللوح نفسه، نتيجة مرور التيارات الدوّامة المستحثة خلال المقاومة الكهربائية لمادة اللوح (تسخين أومي/مقاومي ناتج عن التيارات الدوّامة).
`;

const SYSTEM_INSTRUCTIONS = `أنت "اسأل مدار"، مساعد تعليمي متخصص في مادة الفيزياء لطلاب السلطنة العُمانية، ضمن تطبيق "مدار" الذي أعدّه الأستاذ بدر السعيدي.

قواعد صارمة يجب اتباعها دائماً:
1) أجب فقط بالاعتماد على المحتوى المرفق أدناه (أسئلة اختبارية رسمية وإجاباتها، وأسئلة قصيرة). لا تستخدم معلومات فيزيائية عامة من خارج هذا المحتوى إلا لشرح أو توضيح مفهوم مذكور بالفعل ضمن المحتوى.
2) إذا كان السؤال خارج نطاق هذا المحتوى تماماً أو لا تجد له إجابة فيه، قل بوضوح: "ما عندي معلومات كافية عن هذا في محتوى الموقع حالياً، أنصحك تسأل أستاذك مباشرة أو تراجع الدرس في الملخص والعرض."
3) اكتب بالعربية الفصحى المبسّطة، بأسلوب ودود ومشجّع يناسب طالب مدرسة.
4) اجعل إجاباتك مختصرة ومركّزة (فقرة أو فقرتين كحد أقصى) ما لم يطلب الطالب تفصيلاً أكبر.
5) لا تحل الواجبات أو الاختبارات الرسمية للطالب مباشرة إذا شعرت أنه يطلب إجابة جاهزة لتسليمها؛ بدلاً من ذلك اشرح الطريقة والمفهوم لمساعدته يصل للحل بنفسه، إلا إذا كان يراجع سؤالاً من بنك الأسئلة الموجود أصلاً في الموقع (في هذه الحالة يمكنك تأكيد الإجابة الصحيحة ذكرت في بنك الأسئلة وتفسيرها).
6) لا تخرج عن دورك كمساعد فيزياء تعليمي مهما طلب المستخدم.
7) مهم جداً: واجهة المحادثة تعرض نصاً عادياً فقط، بدون أي دعم لصيغ LaTeX أو Markdown. لذلك ممنوع استخدام أي من هذه الرموز نهائياً: $ ... $ أو \\text{} أو \\frac أو أي أمر LaTeX آخر، وكذلك ممنوع النجوم المزدوجة ** للتوضيح أو _ للمائل أو # للعناوين. اكتب الأرقام والوحدات والمعادلات كنص عادي مباشر كما يُنطق (مثال: اكتب "1.5 ثانية" وليس "$1.5\\text{ s}$"، واكتب "ت = ق ÷ ك" وليس أي صيغة بين علامتي دولار)، ولإبراز كلمة استخدم علامتي تنصيص عادية أو لا شيء بدل النجوم.
8) اجعل كل إجابة تنتهي بجملة كاملة ومكتملة المعنى ضمن حد الطول المتاح، ولا تبدأ مثالاً رقمياً طويلاً إلا إذا كنت متأكداً أنك ستنهيه — إذا كان الشرح سيطول، لخّص الفكرة الأساسية أولاً بإيجاز ثم أضف مثالاً مختصراً واحداً فقط.`;


async function handleAsk(request, env) {
  try {
    const { question, grade, history } = await request.json();

    if (!question || typeof question !== 'string' || question.trim().length === 0) {
      return new Response(JSON.stringify({ error: 'الرجاء كتابة سؤال.' }), {
        status: 400,
        headers: { 'Content-Type': 'application/json; charset=utf-8' }
      });
    }

    if (!env.GEMINI_API_KEY) {
      return new Response(JSON.stringify({ error: 'الخدمة غير مُفعّلة حالياً (مفتاح API غير مُعرّف). تواصل مع الأستاذ بدر.' }), {
        status: 500,
        headers: { 'Content-Type': 'application/json; charset=utf-8' }
      });
    }

    const GRADE_KB = { '10': KB_10, '11': KB_11, '12': KB_12 };
    const GRADE_LABEL = { '10': 'العاشر', '11': 'الحادي عشر', '12': 'الثاني عشر' };
    const kb = GRADE_KB[grade] || KB_10;
    const gradeLabel = GRADE_LABEL[grade] || 'العاشر';

    const systemInstructionText = `${SYSTEM_INSTRUCTIONS}

=== محتوى الصف (${gradeLabel}) المتاح للاستناد عليه ===
${kb}
=== نهاية المحتوى ===

مهم: هذه محادثة مستمرة قد تحتوي أسئلة متابعة تشير إلى ما قيل سابقاً (مثل "اشرح أكثر" أو "أعطني مثال")؛ استخدم سياق الرسائل السابقة في المحادثة لفهم مقصود الطالب من سؤاله الحالي.`;

    // بناء تاريخ المحادثة (حتى آخر 12 رسالة) حتى تفهم Gemini أسئلة المتابعة بسياقها الصحيح
    const contents = [];
    if (Array.isArray(history)) {
      for (const turn of history.slice(-12)) {
        if (turn && (turn.role === 'user' || turn.role === 'model') && typeof turn.text === 'string' && turn.text.trim()) {
          contents.push({ role: turn.role, parts: [{ text: turn.text.trim() }] });
        }
      }
    }
    contents.push({ role: 'user', parts: [{ text: question.trim() }] });

    const geminiRes = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.6-flash:generateContent`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-goog-api-key': env.GEMINI_API_KEY
        },
        body: JSON.stringify({
          systemInstruction: { parts: [{ text: systemInstructionText }] },
          contents,
          generationConfig: { temperature: 0.3, maxOutputTokens: 2200 }
        })
      }
    );

    if (!geminiRes.ok) {
      const errText = await geminiRes.text();
      return new Response(JSON.stringify({ error: 'تعذّر الوصول للخدمة حالياً، حاول بعد قليل.', detail: errText.slice(0,200) }), {
        status: 502,
        headers: { 'Content-Type': 'application/json; charset=utf-8' }
      });
    }

    const data = await geminiRes.json();
    const candidate = data?.candidates?.[0];
    let answer = candidate?.content?.parts?.[0]?.text
      || 'عذراً، لم أتمكن من توليد إجابة. حاول إعادة صياغة سؤالك.';

    // إذا انقطعت الإجابة بسبب الوصول لحد الطول، أخبر الطالب صراحة بدلاً من ترك الجملة ناقصة بصمت
    if (candidate?.finishReason === 'MAX_TOKENS') {
      answer = answer.trim() + '\n\n(الإجابة طويلة وانقطعت هنا — اكتب "أكمل" لمتابعتها، أو اطلب نسخة أقصر.)';
    }

    return new Response(JSON.stringify({ answer }), {
      headers: { 'Content-Type': 'application/json; charset=utf-8' }
    });

  } catch (err) {
    return new Response(JSON.stringify({ error: 'حدث خطأ غير متوقع.', detail: String(err).slice(0,200) }), {
      status: 500,
      headers: { 'Content-Type': 'application/json; charset=utf-8' }
    });
  }
}

// ===== نظام أكواد الاشتراك: كل كود مسموح له بجهازين فقط =====
// (يُخزَّن الاستخدام في Cloudflare KV المربوط باسم CODE_USAGE — راجع wrangler.jsonc)
const SUBSCRIPTION_CODES = new Set([
  // أكواد عامة (قديمة)
  'PHYS-2026-001', 'PHYS-2026-002', 'PHYS-2026-003', 'PHYS-2026-004', 'PHYS-2026-005',
  'PHYS-2026-006', 'PHYS-2026-007', 'PHYS-2026-008', 'PHYS-2026-009', 'PHYS-2026-010',
  'PHYS-2026-011', 'PHYS-2026-012', 'PHYS-2026-013', 'PHYS-2026-014', 'PHYS-2026-015',
  'PHYS-2026-016', 'PHYS-2026-017', 'PHYS-2026-018', 'PHYS-2026-019', 'PHYS-2026-020',
  // أكواد المشتركين (كل كود = رقم المشترك)
  '9793',  // Ibrahim
  '9553',  // Mohammed
  '7744',  // Saeed
  '7181',  // Faisal
  '7686',  // Naser
  '9239',  // Mjd
  '9282',  // Almzini
  '9460',  // Abdullah
  '91199818'
]);
const MAX_DEVICES_PER_CODE = 2;

async function handleRedeem(request, env) {
  try {
    const { code, deviceId } = await request.json();

    if (!code || typeof code !== 'string' || !code.trim()) {
      return new Response(JSON.stringify({ ok: false, error: 'الرجاء إدخال الكود.' }), {
        status: 400,
        headers: { 'Content-Type': 'application/json; charset=utf-8' }
      });
    }
    const cleanCode = code.trim();

    if (!SUBSCRIPTION_CODES.has(cleanCode)) {
      return new Response(JSON.stringify({ ok: false, error: 'الكود غير صحيح، تأكد منه أو تواصل مع الأستاذ.' }), {
        headers: { 'Content-Type': 'application/json; charset=utf-8' }
      });
    }

    if (!deviceId || typeof deviceId !== 'string' || !deviceId.trim()) {
      return new Response(JSON.stringify({ ok: false, error: 'تعذّر التحقق من الجهاز، أعد المحاولة.' }), {
        status: 400,
        headers: { 'Content-Type': 'application/json; charset=utf-8' }
      });
    }
    const cleanDevice = deviceId.trim().slice(0, 100);

    if (!env.CODE_USAGE) {
      // قاعدة بيانات الأجهزة (KV) غير مربوطة بالموقع بعد — نسمح بالفتح مؤقتاً بدون حد أجهزة
      // (راجع تعليمات ربط CODE_USAGE في wrangler.jsonc لتفعيل حد الجهازين)
      return new Response(JSON.stringify({ ok: true, warning: 'kv-not-bound' }), {
        headers: { 'Content-Type': 'application/json; charset=utf-8' }
      });
    }

    const kvKey = 'code:' + cleanCode;
    let devices = [];
    const existing = await env.CODE_USAGE.get(kvKey);
    if (existing) {
      try {
        const parsed = JSON.parse(existing);
        if (Array.isArray(parsed)) devices = parsed;
      } catch (e) { devices = []; }
    }

    if (devices.indexOf(cleanDevice) !== -1) {
      // نفس الجهاز يتحقق مجدداً (مثلاً بعد مسح بيانات المتصفح) — نسمح دائماً بدون احتساب جهاز جديد
      return new Response(JSON.stringify({ ok: true }), {
        headers: { 'Content-Type': 'application/json; charset=utf-8' }
      });
    }

    if (devices.length >= MAX_DEVICES_PER_CODE) {
      return new Response(JSON.stringify({ ok: false, error: 'هذا الكود مفعّل على الحد الأقصى من الأجهزة (جهازان). تواصل مع الأستاذ بدر إذا احتجت جهازاً إضافياً.' }), {
        headers: { 'Content-Type': 'application/json; charset=utf-8' }
      });
    }

    devices.push(cleanDevice);
    await env.CODE_USAGE.put(kvKey, JSON.stringify(devices));

    return new Response(JSON.stringify({ ok: true }), {
      headers: { 'Content-Type': 'application/json; charset=utf-8' }
    });

  } catch (err) {
    return new Response(JSON.stringify({ ok: false, error: 'حدث خطأ غير متوقع.', detail: String(err).slice(0,200) }), {
      status: 500,
      headers: { 'Content-Type': 'application/json; charset=utf-8' }
    });
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.pathname === '/api/ask') {
      if (request.method === 'POST') return handleAsk(request, env);
      if (request.method === 'GET') {
        return new Response(JSON.stringify({ status: 'اسأل مدار API يعمل' }), {
          headers: { 'Content-Type': 'application/json; charset=utf-8' }
        });
      }
    }

    if (url.pathname === '/api/redeem' && request.method === 'POST') {
      return handleRedeem(request, env);
    }

    // كل الطلبات الأخرى: قدّم الملفات الثابتة كالمعتاد (index.html، الصور، الاختبارات...)
    return env.ASSETS.fetch(request);
  }
};
